window.QUESTIONS={"list":[{"t":"s1","q":{"uk":"Що таке обгін?","ru":"Что такое обгон?"},"a":[{"uk":"Будь-яке випередження іншого транспортного засобу","ru":"Любое опережение другого транспортного средства"},{"uk":"Випередження одного або кількох транспортних засобів, пов'язане з виїздом на смугу зустрічного руху","ru":"Опережение одного или нескольких транспортных средств, связанное с выездом на полосу встречного движения"},{"uk":"Рух швидше за сусідню смугу","ru":"Движение быстрее соседней полосы"}],"c":1,"e":{"uk":"Обгін — випередження з виїздом на смугу зустрічного руху. Рух швидше за попутний транспорт сусідньою смугою — це випередження.","ru":"Обгон — опережение с выездом на полосу встречного движения. Движение быстрее попутного транспорта по соседней полосе — это опережение."},"ref":["1.10"],"id":"q1bfaf927f"},{"t":"s1","q":{"uk":"Яку видимість Правила вважають недостатньою?","ru":"Какую видимость Правила считают недостаточной?"},"a":[{"uk":"Менше 100 м","ru":"Менее 100 м"},{"uk":"Менше 200 м","ru":"Менее 200 м"},{"uk":"Менше 300 м у сутінках, тумані, дощ, снігопад тощо","ru":"Менее 300 м в сумерках, тумане, дождь, снегопад и т. п."}],"c":2,"e":{"uk":"Недостатня видимість — видимість дороги в напрямку руху менше ніж 300 м у сутінках, в умовах туману, дощу, снігопаду тощо.","ru":"Недостаточная видимость — видимость дороги в направлении движения менее 300 м в сумерках, в условиях тумана, дождя, снегопада и т. п."},"ref":["1.10"],"id":"q1abd56efe"},{"t":"s1","q":{"uk":"Чи є перехрестям місце, де до дороги прилягає виїзд з АЗС?","ru":"Является ли перекрёстком место, где к дороге примыкает выезд с АЗС?"},"a":[{"uk":"Так","ru":"Да"},{"uk":"Ні, це виїзд з прилеглої території","ru":"Нет, это выезд с прилегающей территории"}],"c":1,"e":{"uk":"Не вважається перехрестям місце прилягання до дороги виїзду з прилеглої території (двір, стоянка, АЗС). Той, хто виїжджає, пропускає всіх на дорозі.","ru":"Не считается перекрёстком место примыкания к дороге выезда с прилегающей территории (двор, стоянка, АЗС). Выезжающий пропускает всех на дороге."},"ref":["1.10","10.2"],"id":"q4f49bbc8d"},{"t":"s1","q":{"uk":"Яка з доріг є головною на перехресті дороги з асфальтовим покриттям і ґрунтової, якщо знаків немає?","ru":"Какая из дорог является главной на перекрёстке дороги с асфальтовым покрытием и грунтовой, если знаков нет?"},"a":[{"uk":"Дорога з покриттям","ru":"Дорога с покрытием"},{"uk":"Ґрунтова, бо вона праворуч","ru":"Грунтовая, так как она справа"},{"uk":"Вони рівнозначні","ru":"Они равнозначны"}],"c":0,"e":{"uk":"Головна дорога — дорога з покриттям відносно ґрунтової або позначена знаками {s:1.22}, {s:1.23.1}–{s:1.23.4}, {s:2.3}. Ділянка покриття на другорядній дорозі перед самим перехрестям не робить її рівнозначною.","ru":"Главная дорога — дорога с покрытием по отношению к грунтовой или обозначенная знаками {s:1.22}, {s:1.23.1}–{s:1.23.4}, {s:2.3}. Участок покрытия на второстепенной дороге прямо перед перекрёстком не делает её равнозначной."},"ref":["1.10"],"id":"qee89f9c49"},{"t":"s1","q":{"uk":"Скільки транспортних засобів мінімально утворюють колону?","ru":"Сколько транспортных средств минимально образуют колонну?"},"a":[{"uk":"Два","ru":"Два"},{"uk":"Три","ru":"Три"},{"uk":"П'ять","ru":"Пять"}],"c":1,"e":{"uk":"Колона транспортних засобів — організована група з трьох і більше транспортних засобів, що рухаються разом в одному напрямку один за одним з увімкненим ближнім світлом.","ru":"Колонна транспортных средств — организованная группа из трёх и более транспортных средств, движущихся вместе в одном направлении друг за другом с включённым ближним светом."},"ref":["1.10"],"id":"q88a767a90"},{"t":"s1","q":{"uk":"Людина веде велосипед по узбіччю. Хто вона з погляду Правил?","ru":"Человек ведёт велосипед по обочине. Кто он с точки зрения Правил?"},"a":[{"uk":"Велосипедист","ru":"Велосипедист"},{"uk":"Пішохід","ru":"Пешеход"},{"uk":"Водій","ru":"Водитель"}],"c":1,"e":{"uk":"До пішоходів прирівнюються особи, які ведуть велосипед, мопед, мотоцикл, везуть санки, візок, дитячу коляску чи рухаються в кріслі колісному без двигуна.","ru":"К пешеходам приравниваются лица, ведущие велосипед, мопед, мотоцикл, везущие санки, тележку, детскую коляску или передвигающиеся в кресле-коляске без двигателя."},"ref":["1.10"],"id":"q7ddf167d8"},{"t":"s1","q":{"uk":"Яка мінімальна ширина смуги руху за Правилами?","ru":"Какая минимальная ширина полосы движения по Правилам?"},"a":[{"uk":"2,5 м","ru":"2,5 м"},{"uk":"2,75 м","ru":"2,75 м"},{"uk":"3,5 м","ru":"3,5 м"}],"c":1,"e":{"uk":"Смуга руху — поздовжня смуга на проїзній частині завширшки щонайменше 2,75 м.","ru":"Полоса движения — продольная полоса на проезжей части шириной не менее 2,75 м."},"ref":["1.10"],"id":"qa1685d6bf"},{"t":"s1","q":{"uk":"Пішохідний перехід, на якому світлофор працює в режимі миготливого жовтого, вважається...","ru":"Пешеходный переход, на котором светофор работает в режиме мигающего жёлтого, считается..."},"a":[{"uk":"регульованим","ru":"регулируемым"},{"uk":"нерегульованим","ru":"нерегулируемым"}],"c":1,"e":{"uk":"Нерегульований пішохідний перехід — той, де немає регулювальника, а світлофори відсутні, вимкнені чи миготять жовтим.","ru":"Нерегулируемый пешеходный переход — тот, где нет регулировщика, а светофоры отсутствуют, выключены или мигают жёлтым."},"ref":["1.10"],"id":"q0c3c0d13b"},{"t":"s1","q":{"uk":"Що Правила вважають темною порою доби?","ru":"Что Правила считают тёмным временем суток?"},"a":[{"uk":"Частину доби від заходу до сходу сонця","ru":"Часть суток от захода до восхода солнца"},{"uk":"Час з 22:00 до 6:00","ru":"Время с 22:00 до 6:00"},{"uk":"Час, коли увімкнено вуличне освітлення","ru":"Время, когда включено уличное освещение"}],"c":0,"e":{"uk":"Темна пора доби — частина доби від заходу до сходу сонця.","ru":"Тёмное время суток — часть суток от захода до восхода солнца."},"ref":["1.10"],"id":"q6a3a32f57"},{"t":"s3","q":{"uk":"Наближається автомобіль з увімкненим синім маячком і сиреною. Що зобов'язаний зробити водій, який може йому заважати?","ru":"Приближается автомобиль с включённым синим маячком и сиреной. Что обязан сделать водитель, который может ему мешать?"},"a":[{"uk":"Продовжувати рух, не змінюючи смуги","ru":"Продолжать движение, не меняя полосы"},{"uk":"Дати дорогу й забезпечити безперешкодний проїзд","ru":"Уступить дорогу и обеспечить беспрепятственный проезд"},{"uk":"Зупинитися посеред смуги","ru":"Остановиться посреди полосы"}],"c":1,"e":{"uk":"Водії, які можуть заважати транспортному засобу із синім маячком та (або) спеціальним звуковим сигналом, зобов'язані дати йому дорогу. Якщо ввімкнено синій і червоний або лише червоний маячок — зупинитися біля правого краю.","ru":"Водители, которые могут мешать транспортному средству с синим маячком и (или) специальным звуковым сигналом, обязаны уступить ему дорогу. Если включены синий и красный или только красный маячок — остановиться у правого края."},"ref":["3.2"],"id":"qffe63bc61"},{"t":"s3","q":{"uk":"Позаду наближається автомобіль з увімкненими синім і червоним маячками. Як діяти?","ru":"Сзади приближается автомобиль с включёнными синим и красным маячками. Как поступить?"},"a":[{"uk":"Зупинитися біля правого краю проїзної частини (на правому узбіччі)","ru":"Остановиться у правого края проезжей части (на правой обочине)"},{"uk":"Прискоритися, щоб не заважати","ru":"Ускориться, чтобы не мешать"},{"uk":"Перестроїтися ліворуч","ru":"Перестроиться налево"}],"c":0,"e":{"uk":"Якщо ввімкнено синій і червоний або лише червоний маячок, водії зобов'язані зупинитися біля правого краю проїзної частини. На дорозі з розділювальною смугою — водії попутного напрямку.","ru":"Если включены синий и красный или только красный маячок, водители обязаны остановиться у правого края проезжей части. На дороге с разделительной полосой — водители попутного направления."},"ref":["3.2"],"id":"q2ab91d744"},{"t":"s3","q":{"uk":"Чи дає оранжевий проблисковий маячок перевагу в русі?","ru":"Даёт ли оранжевый проблесковый маячок преимущество в движении?"},"a":[{"uk":"Так, як і синій","ru":"Да, как и синий"},{"uk":"Ні, він лише привертає увагу і попереджає про небезпеку","ru":"Нет, он только привлекает внимание и предупреждает об опасности"}],"c":1,"e":{"uk":"Оранжевий маячок (дорожна техніка, великогабаритний транспорт, автобус «Діти» тощо) не дає переваги, а служить для привернення уваги та попередження про небезпеку.","ru":"Оранжевый маячок (дорожная техника, крупногабаритный транспорт, автобус «Дети» и т. п.) не даёт преимущества, а служит для привлечения внимания и предупреждения об опасности."},"ref":["3.6"],"id":"q102449b9c"},{"t":"s3","q":{"uk":"Попереду на узбіччі стоїть поліцейський автомобіль з увімкненим синім маячком. До якої швидкості треба знизити швидкість?","ru":"Впереди на обочине стоит полицейский автомобиль с включённым синим маячком. До какой скорости нужно снизить скорость?"},"a":[{"uk":"20 км/год","ru":"20 км/ч"},{"uk":"40 км/год","ru":"40 км/ч"},{"uk":"60 км/год","ru":"60 км/ч"}],"c":1,"e":{"uk":"Наближаючись до нерухомого транспортного засобу з увімкненим синім маячком, водій знижує швидкість до 40 км/год, а на сигнал регулювальника — зупиняється.","ru":"Приближаясь к неподвижному транспортному средству с включённым синим маячком, водитель снижает скорость до 40 км/ч, а по сигналу регулировщика — останавливается."},"ref":["3.5"],"id":"qeb6fcad38"},{"t":"s3","q":{"uk":"Чи можна обганяти колону, яку супроводжує автомобіль із синім і червоним маячками?","ru":"Можно ли обгонять колонну, которую сопровождает автомобиль с синим и красным маячками?"},"a":[{"uk":"Так, якщо зустрічна смуга вільна","ru":"Да, если встречная полоса свободна"},{"uk":"Ні, обгін і випередження такої колони заборонені, як і займати в ній місце","ru":"Нет, обгон и опережение такой колонны запрещены, как и занимать в ней место"}],"c":1,"e":{"uk":"Заборонено обганяти й випереджати транспортні засоби з увімкненими спецмаячками і супроводжувану ними колону, рухатися поруч зі швидкістю колони або займати місце в ній.","ru":"Запрещено обгонять и опережать транспортные средства с включёнными спецмаячками и сопровождаемую ими колонну, двигаться рядом со скоростью колонны или занимать в ней место."},"ref":["3.4"],"id":"q6f14dc3ee"},{"t":"s3","q":{"uk":"Ліворуч наближається автомобіль швидкої допомоги з увімкненим синім маячком і сиреною. Хто проїде перехрестя першим?","ru":"Слева приближается автомобиль скорой помощи с включённым синим маячком и сиреной. Кто проедет перекрёсток первым?"},"a":[{"uk":"Автомобіль 1, бо швидка ліворуч","ru":"Автомобиль 1, так как скорая слева"},{"uk":"Автомобіль швидкої допомоги","ru":"Автомобиль скорой помощи"}],"img":{"scene":{"road":"cross","cars":[{"arm":"S","move":"straight","label":"1","color":"red","me":true},{"arm":"W","move":"straight","label":"2","type":"ambulance"}]}},"c":1,"e":{"uk":"Транспортному засобу з увімкненим синім маячком і спеціальним звуковим сигналом треба дати дорогу, незалежно від правил проїзду перехресть.","ru":"Транспортному средству с включённым синим маячком и специальным звуковым сигналом нужно уступить дорогу независимо от правил проезда перекрёстков."},"ref":["3.2"],"id":"q70bee0ccc"},{"t":"s4","q":{"uk":"Як мають іти пішоходи узбіччям поза населеним пунктом?","ru":"Как должны идти пешеходы по обочине вне населённого пункта?"},"a":[{"uk":"Назустріч руху транспортних засобів","ru":"Навстречу движению транспортных средств"},{"uk":"У напрямку руху транспортних засобів","ru":"В направлении движения транспортных средств"},{"uk":"Будь-як","ru":"Как угодно"}],"c":0,"e":{"uk":"Поза населеними пунктами пішоходи йдуть узбіччям чи краєм проїзної частини назустріч руху транспорту. Ті, хто веде велосипед чи мотоцикл або рухається в кріслі колісному без двигуна, — у напрямку руху.","ru":"Вне населённых пунктов пешеходы идут по обочине или краю проезжей части навстречу движению транспорта. Те, кто ведёт велосипед или мотоцикл или передвигается в кресле-коляске без двигателя, — в направлении движения."},"ref":["4.3"],"id":"q803d925d1"},{"t":"s4","q":{"uk":"Де пішохід може перейти дорогу, якщо поблизу немає переходу і перехрестя?","ru":"Где пешеход может перейти дорогу, если поблизости нет перехода и перекрёстка?"},"a":[{"uk":"Будь-де і під будь-яким кутом","ru":"Где угодно и под любым углом"},{"uk":"Під прямим кутом там, де дорогу добре видно в обидва боки, якщо в ній не більше трьох смуг для обох напрямків","ru":"Под прямым углом там, где дорогу хорошо видно в обе стороны, если в ней не более трёх полос для обоих направлений"},{"uk":"Лише через розділювальну смугу","ru":"Только через разделительную полосу"}],"c":1,"e":{"uk":"Поза переходом можна переходити дорогу з не більше ніж трьома смугами (для обох напрямків) під прямим кутом у місці з хорошою оглядовістю, переконавшись у безпеці. Якщо є розділювальна смуга, чотири й більше смуг або огородження — заборонено.","ru":"Вне перехода можно переходить дорогу не более чем с тремя полосами (для обоих направлений) под прямым углом в месте с хорошей обзорностью, убедившись в безопасности. Если есть разделительная полоса, четыре и более полос или ограждение — запрещено."},"ref":["4.8","4.14"],"id":"q86a9952d2"},{"t":"s4","q":{"uk":"Що зобов'язані мати пішоходи, які йдуть узбіччям у темну пору доби?","ru":"Что обязаны иметь пешеходы, идущие по обочине в тёмное время суток?"},"a":[{"uk":"Світлоповертальні елементи (стрічку, жилет тощо)","ru":"Световозвращающие элементы (ленту, жилет и т. п.)"},{"uk":"Ліхтарик","ru":"Фонарик"},{"uk":"Нічого","ru":"Ничего"}],"c":0,"e":{"uk":"У темну пору доби та за недостатньої видимості пішоходи на проїзній частині чи узбіччі мають використовувати світлоповертальні елементи або одяг з ними.","ru":"В тёмное время суток и при недостаточной видимости пешеходы на проезжей части или обочине должны использовать световозвращающие элементы или одежду с ними."},"ref":["4.4"],"id":"q4524ca53b"},{"t":"s4","q":{"uk":"Пішохід почав переходити на зелений, але не встиг: увімкнувся червоний. Як йому діяти?","ru":"Пешеход начал переходить на зелёный, но не успел: включился красный. Как ему поступить?"},"a":[{"uk":"Бігти назад","ru":"Бежать назад"},{"uk":"Зупинитися на острівці безпеки або лінії, що розділяє потоки, і чекати дозвільного сигналу","ru":"Остановиться на островке безопасности или линии, разделяющей потоки, и ждать разрешающего сигнала"},{"uk":"Продовжити перехід, бо він має перевагу","ru":"Продолжить переход, так как у него преимущество"}],"c":1,"e":{"uk":"Пішоходи, які не встигли закінчити перехід, чекають на острівці безпеки чи лінії, що розділяє протилежні потоки (а якщо їх немає — посередині), і продовжують рух на дозвільний сигнал. Водії, проїжджаючи повз них, тримають безпечний інтервал.","ru":"Пешеходы, не успевшие закончить переход, ждут на островке безопасности или линии, разделяющей встречные потоки (а если их нет — посередине), и продолжают движение на разрешающий сигнал. Водители, проезжая мимо них, соблюдают безопасный интервал."},"ref":["4.9","18.3"],"id":"q9f99be67e"},{"t":"s5","q":{"uk":"Звідки пасажир може виходити з автомобіля, якщо немає посадкового майданчика, тротуару чи узбіччя?","ru":"Откуда пассажир может выходить из автомобиля, если нет посадочной площадки, тротуара или обочины?"},"a":[{"uk":"З крайньої смуги проїзної частини, але не з боку суміжної смуги руху, якщо це безпечно","ru":"С крайней полосы проезжей части, но не со стороны смежной полосы движения, если это безопасно"},{"uk":"З будь-якого боку","ru":"С любой стороны"},{"uk":"Виходити заборонено","ru":"Выходить запрещено"}],"c":0,"e":{"uk":"Посадку й висадку здійснюють після зупинки з посадкового майданчика, тротуару чи узбіччя, а якщо це неможливо — з крайньої смуги (але не з боку суміжної смуги руху), якщо це безпечно.","ru":"Посадку и высадку осуществляют после остановки с посадочной площадки, тротуара или обочины, а если это невозможно — с крайней полосы (но не со стороны смежной полосы движения), если это безопасно."},"ref":["5.1"],"id":"qe67eb2ae2"},{"t":"s5","q":{"uk":"Що заборонено пасажирам під час руху?","ru":"Что запрещено пассажирам во время движения?"},"a":[{"uk":"Розмовляти з водієм","ru":"Разговаривать с водителем"},{"uk":"Відволікати водія, відчиняти двері до зупинки, стояти в кузові вантажівки","ru":"Отвлекать водителя, открывать двери до остановки, стоять в кузове грузовика"},{"uk":"Пристібатися ременем на задньому сидінні","ru":"Пристёгиваться ремнём на заднем сиденье"}],"c":1,"e":{"uk":"Пасажирам заборонено відволікати водія, відчиняти двері, не переконавшись у зупинці біля тротуару чи узбіччя, заважати зачиненню дверей, їздити на підніжках, стояти в кузові вантажного автомобіля чи сидіти на бортах.","ru":"Пассажирам запрещено отвлекать водителя, открывать двери, не убедившись в остановке у тротуара или обочины, мешать закрыванию дверей, ездить на подножках, стоять в кузове грузового автомобиля или сидеть на бортах."},"ref":["5.3"],"id":"qfee0faa57"},{"t":"s6","q":{"uk":"З якого віку дозволено їздити дорогою на велосипеді?","ru":"С какого возраста разрешено ездить по дороге на велосипеде?"},"a":[{"uk":"З 12 років","ru":"С 12 лет"},{"uk":"З 14 років","ru":"С 14 лет"},{"uk":"З 16 років","ru":"С 16 лет"}],"c":1,"e":{"uk":"Рухатися дорогою на велосипеді дозволено особам, які досягли 14 років.","ru":"Двигаться по дороге на велосипеде разрешено лицам, достигшим 14 лет."},"ref":["6.1"],"id":"q723c923e6"},{"t":"s6","q":{"uk":"Велодоріжка перетинає дорогу поза перехрестям. Хто має перевагу?","ru":"Велодорожка пересекает дорогу вне перекрёстка. У кого преимущество?"},"a":[{"uk":"Велосипедисти","ru":"Велосипедисты"},{"uk":"Транспортні засоби, що рухаються дорогою","ru":"Транспортные средства, движущиеся по дороге"}],"img":{"sign":"1.34"},"c":1,"e":{"uk":"Якщо велосипедна доріжка перетинає дорогу поза перехрестям, велосипедисти дають дорогу транспортним засобам на дорозі. Водієві ж варто бути особливо уважним: знак {s:1.34} попереджає про можливу появу велосипедистів.","ru":"Если велосипедная дорожка пересекает дорогу вне перекрёстка, велосипедисты уступают дорогу транспортным средствам на дороге. Водителю же стоит быть особенно внимательным: знак {s:1.34} предупреждает о возможном появлении велосипедистов."},"ref":["6.5"],"id":"q07e4425eb"},{"t":"s6","q":{"uk":"Якого кольору мають бути світлоповертачі велосипеда позаду?","ru":"Какого цвета должны быть световозвращатели велосипеда сзади?"},"a":[{"uk":"Червоного","ru":"Красного"},{"uk":"Білого","ru":"Белого"},{"uk":"Оранжевого","ru":"Оранжевого"}],"c":0,"e":{"uk":"Велосипед обладнують звуковим сигналом і світлоповертачами: спереду — білого, по боках — оранжевого, позаду — червоного кольору. Уночі має горіти ліхтар (фара).","ru":"Велосипед оборудуют звуковым сигналом и световозвращателями: спереди — белого, по бокам — оранжевого, сзади — красного цвета. Ночью должен гореть фонарь (фара)."},"ref":["6.2"],"id":"qea9c435c5"},{"t":"s7","q":{"uk":"Коли дозволено переганяти стадо тварин дорогою?","ru":"Когда разрешено перегонять стадо животных по дороге?"},"a":[{"uk":"Лише у світлу пору доби","ru":"Только в светлое время суток"},{"uk":"У будь-який час із ліхтарями","ru":"В любое время с фонарями"},{"uk":"Лише вночі, коли мало транспорту","ru":"Только ночью, когда мало транспорта"}],"c":0,"e":{"uk":"Переганяти стадо дорогою дозволено лише у світлу пору доби, з достатньою кількістю погоничів, якомога ближче до правого краю.","ru":"Перегонять стадо по дороге разрешено только в светлое время суток, с достаточным количеством погонщиков, как можно ближе к правому краю."},"ref":["7.6"],"id":"q8d422d51f"},{"t":"s2","q":{"uk":"Які документи водій легкового автомобіля зобов'язаний мати при собі?","ru":"Какие документы водитель легкового автомобиля обязан иметь при себе?"},"a":[{"uk":"Лише посвідчення водія","ru":"Только водительское удостоверение"},{"uk":"Посвідчення водія відповідної категорії, реєстраційний документ на автомобіль і чинний поліс ОСЦПВ (можна електронний)","ru":"Удостоверение водителя соответствующей категории, регистрационный документ на автомобиль и действующий полис ОСАГО (можно электронный)"},{"uk":"Посвідчення водія, паспорт і медичну довідку","ru":"Удостоверение водителя, паспорт и медицинскую справку"}],"c":1,"e":{"uk":"Водій має мати посвідчення на право керування відповідної категорії, реєстраційний документ на транспортний засіб і чинний поліс обов'язкового страхування цивільно-правової відповідальності (на паперовому або електронному носії).","ru":"Водитель должен иметь удостоверение на право управления соответствующей категории, регистрационный документ на транспортное средство и действующий полис обязательного страхования гражданско-правовой ответственности (на бумажном или электронном носителе)."},"ref":["2.1"],"id":"q28326420c"},{"t":"s2","q":{"uk":"Чи можна під час руху розмовляти по телефону, тримаючи його в руці?","ru":"Можно ли во время движения разговаривать по телефону, держа его в руке?"},"a":[{"uk":"Так, якщо розмова коротка","ru":"Да, если разговор короткий"},{"uk":"Ні. Дозволено лише через гарнітуру або гучний зв'язок без утримання в руці","ru":"Нет. Разрешено только через гарнитуру или громкую связь, не держа в руке"},{"uk":"Так, у населеному пункті на швидкості до 20 км/год","ru":"Да, в населённом пункте на скорости до 20 км/ч"}],"c":1,"e":{"uk":"Водієві заборонено під час руху користуватися засобами зв'язку, тримаючи їх у руці (виняток — водії оперативних транспортних засобів під час невідкладного завдання).","ru":"Водителю запрещено во время движения пользоваться средствами связи, держа их в руке (исключение — водители оперативных транспортных средств во время неотложного задания)."},"ref":["2.9"],"id":"q5b1c437dd"},{"t":"s2","q":{"uk":"Кому можна передати керування своїм автомобілем?","ru":"Кому можно передать управление своим автомобилем?"},"a":[{"uk":"Будь-якому повнолітньому пасажиру","ru":"Любому совершеннолетнему пассажиру"},{"uk":"Особі, яка має при собі посвідчення водія відповідної категорії і не перебуває в стані сп'яніння чи хворобливому стані","ru":"Лицу, имеющему при себе удостоверение водителя соответствующей категории и не находящемуся в состоянии опьянения или болезненном состоянии"},{"uk":"Будь-кому, якщо власник сидить поруч","ru":"Кому угодно, если владелец сидит рядом"}],"c":1,"e":{"uk":"Керування можна передати особі, що має при собі посвідчення на право керування відповідної категорії. Заборонено передавати керування особам у стані сп'яніння, під дією ліків, у хворобливому стані або без посвідчення (крім навчальної їзди).","ru":"Управление можно передать лицу, имеющему при себе удостоверение на право управления соответствующей категории. Запрещено передавать управление лицам в состоянии опьянения, под действием лекарств, в болезненном состоянии или без удостоверения (кроме учебной езды)."},"ref":["2.2","2.9"],"id":"q6ac4c0d76"},{"t":"s2","q":{"uk":"Чи можна в населеному пункті не пристібатися ременем безпеки?","ru":"Можно ли в населённом пункте не пристёгиваться ремнём безопасности?"},"a":[{"uk":"Так, усім водіям","ru":"Да, всем водителям"},{"uk":"Лише особам з інвалідністю, яким фізіологічні особливості не дозволяють користуватися ременем, та водіям і пасажирам оперативних і спеціальних транспортних засобів","ru":"Только лицам с инвалидностью, которым физиологические особенности не позволяют пользоваться ремнём, и водителям и пассажирам оперативных и специальных транспортных средств"},{"uk":"Так, якщо швидкість не перевищує 50 км/год","ru":"Да, если скорость не превышает 50 км/ч"}],"c":1,"e":{"uk":"Водій зобов'язаний користуватися ременем і не перевозити непристебнутих пасажирів. Виняток у населених пунктах — особи з інвалідністю, яким фізіологічні особливості не дозволяють пристебнутися, та водії і пасажири оперативних і спеціальних транспортних засобів.","ru":"Водитель обязан пользоваться ремнём и не перевозить непристёгнутых пассажиров. Исключение в населённых пунктах — лица с инвалидностью, которым физиологические особенности не позволяют пристегнуться, и водители и пассажиры оперативных и специальных транспортных средств."},"ref":["2.3"],"id":"qf63d75ae9"},{"t":"s2","q":{"uk":"Ви стали учасником ДТП, є постраждалі. Що зробити насамперед?","ru":"Вы стали участником ДТП, есть пострадавшие. Что сделать в первую очередь?"},"a":[{"uk":"Зупинитися, увімкнути аварійку, виставити знак аварійної зупинки, надати домедичну допомогу і викликати швидку","ru":"Остановиться, включить аварийку, выставить знак аварийной остановки, оказать домедицинскую помощь и вызвать скорую"},{"uk":"Відвезти автомобіль на узбіччя, щоб не заважати руху","ru":"Отогнать автомобиль на обочину, чтобы не мешать движению"},{"uk":"Поїхати за допомогою до найближчого відділку поліції","ru":"Поехать за помощью в ближайший отдел полиции"}],"c":0,"e":{"uk":"Водій, причетний до ДТП, зупиняється й залишається на місці, вмикає аварійну сигналізацію, виставляє знак аварійної зупинки, не переміщує автомобіль і предмети, надає домедичну допомогу, викликає швидку та повідомляє поліцію.","ru":"Водитель, причастный к ДТП, останавливается и остаётся на месте, включает аварийную сигнализацию, выставляет знак аварийной остановки, не перемещает автомобиль и предметы, оказывает домедицинскую помощь, вызывает скорую и сообщает в полицию."},"ref":["2.10"],"id":"q8c30f5884"},{"t":"s2","q":{"uk":"Сталася ДТП за участю двох застрахованих автомобілів: постраждалих немає, водії тверезі й згодні щодо обставин. Як можна оформити пригоду?","ru":"Произошло ДТП с участием двух застрахованных автомобилей: пострадавших нет, водители трезвые и согласны насчёт обстоятельств. Как можно оформить происшествие?"},"a":[{"uk":"Лише викликавши поліцію","ru":"Только вызвав полицию"},{"uk":"Самостійно скласти спільне повідомлення для страховика (європротокол) без виклику поліції","ru":"Самостоятельно составить совместное сообщение для страховщика (европротокол) без вызова полиции"},{"uk":"Розійтися без оформлення","ru":"Разъехаться без оформления"}],"c":1,"e":{"uk":"Якщо зіткнулися лише два застраховані автомобілі, ніхто не постраждав, водії не мають ознак сп'яніння і згодні щодо обставин, вони можуть самі скласти повідомлення для страховика (паперове чи електронне) і залишити місце ДТП без виклику поліції.","ru":"Если столкнулись только два застрахованных автомобиля, никто не пострадал, водители не имеют признаков опьянения и согласны насчёт обстоятельств, они могут сами составить сообщение для страховщика (бумажное или электронное) и покинуть место ДТП без вызова полиции."},"ref":["2.11"],"id":"qce6a3a342"},{"t":"s2","q":{"uk":"З якого віку можна отримати право керування автомобілем категорії B?","ru":"С какого возраста можно получить право управления автомобилем категории B?"},"a":[{"uk":"З 16 років","ru":"С 16 лет"},{"uk":"З 17 років","ru":"С 17 лет"},{"uk":"З 18 років","ru":"С 18 лет"},{"uk":"З 19 років","ru":"С 19 лет"}],"c":2,"e":{"uk":"Категорії A1 і A — з 16 років; B1, B, C1, C — з 18 років; BE, C1E, CE — з 19 років; D1, D, D1E, DE, T — з 21 року.","ru":"Категории A1 и A — с 16 лет; B1, B, C1, C — с 18 лет; BE, C1E, CE — с 19 лет; D1, D, D1E, DE, T — с 21 года."},"ref":["2.13"],"id":"qe88996abe"},{"t":"s2","q":{"uk":"Якими транспортними засобами дозволяє керувати категорія B?","ru":"Какими транспортными средствами позволяет управлять категория B?"},"a":[{"uk":"Автомобілями з дозволеною максимальною масою до 3500 кг і не більше 8 сидячих місць, крім водійського (можна з причепом до 750 кг)","ru":"Автомобилями с разрешённой максимальной массой до 3500 кг и не более 8 сидячих мест, кроме водительского (можно с прицепом до 750 кг)"},{"uk":"Будь-якими автомобілями, крім автобусів","ru":"Любыми автомобилями, кроме автобусов"},{"uk":"Автомобілями до 7500 кг","ru":"Автомобилями до 7500 кг"}],"c":0,"e":{"uk":"Категорія B — автомобілі до 3500 кг з не більш ніж 8 місцями для сидіння, крім місця водія, а також состав з причепом повною масою до 750 кг. Важчий причіп потребує категорії BE.","ru":"Категория B — автомобили до 3500 кг с не более чем 8 местами для сидения, кроме места водителя, а также состав с прицепом полной массой до 750 кг. Более тяжёлый прицеп требует категории BE."},"ref":["2.13"],"id":"q9726f6a99"},{"t":"s2","q":{"uk":"Поліцейський зупинив ваш автомобіль. Що ви маєте право вимагати?","ru":"Полицейский остановил ваш автомобиль. Что вы вправе требовать?"},"a":[{"uk":"Нічого, ви зобов'язані лише виконувати вимоги","ru":"Ничего, вы обязаны только выполнять требования"},{"uk":"Дізнатися причину зупинки, прізвище і посаду поліцейського та побачити його посвідчення","ru":"Узнать причину остановки, фамилию и должность полицейского и увидеть его удостоверение"},{"uk":"Відео з нагрудної камери негайно на місці","ru":"Видео с нагрудной камеры немедленно на месте"}],"c":1,"e":{"uk":"Водій має право знати причину зупинки, перевірки та огляду, прізвище і посаду посадової особи та вимагати пред'явлення її посвідчення, а також оскаржити дії поліцейського.","ru":"Водитель имеет право знать причину остановки, проверки и осмотра, фамилию и должность должностного лица и требовать предъявления его удостоверения, а также обжаловать действия полицейского."},"ref":["2.14"],"id":"q24097ab56"},{"t":"s2","q":{"uk":"Чи можна керувати автомобілем у стані сильної втоми або під дією ліків, що знижують реакцію?","ru":"Можно ли управлять автомобилем в состоянии сильного утомления или под действием лекарств, снижающих реакцию?"},"a":[{"uk":"Так, якщо їхати повільно","ru":"Да, если ехать медленно"},{"uk":"Ні","ru":"Нет"},{"uk":"Так, на короткі відстані","ru":"Да, на короткие расстояния"}],"c":1,"e":{"uk":"Заборонено керувати в стані будь-якого сп'яніння, у хворобливому стані, у стані стомлення та під впливом ліків, що знижують увагу і швидкість реакції.","ru":"Запрещено управлять в состоянии любого опьянения, в болезненном состоянии, в состоянии утомления и под влиянием лекарств, снижающих внимание и скорость реакции."},"ref":["2.9"],"id":"q648c60a6c"},{"t":"s2","q":{"uk":"З якої відстані мають чітко читатися символи номерного знака?","ru":"С какого расстояния должны чётко читаться символы номерного знака?"},"a":[{"uk":"10 м","ru":"10 м"},{"uk":"20 м","ru":"20 м"},{"uk":"50 м","ru":"50 м"}],"c":1,"e":{"uk":"Заборонено керувати автомобілем, номерний знак якого закритий чи забруднений так, що символи не можна чітко визначити з відстані 20 м, а також неосвітленим у темряві чи перевернутим.","ru":"Запрещено управлять автомобилем, номерной знак которого закрыт или загрязнён так, что символы нельзя чётко определить с расстояния 20 м, а также не освещён в темноте или перевёрнут."},"ref":["2.9"],"id":"qe637309df"},{"t":"s2","q":{"uk":"Після ДТП водій чекає на поліцію. Чи можна йому випити заспокійливе на основі спирту?","ru":"После ДТП водитель ждёт полицию. Можно ли ему выпить успокоительное на основе спирта?"},"a":[{"uk":"Так, якщо він не керуватиме","ru":"Да, если он не будет управлять"},{"uk":"Ні, до медичного огляду без призначення медика не можна вживати алкоголь і ліки на його основі (крім складу аптечки)","ru":"Нет, до медосмотра без назначения медика нельзя употреблять алкоголь и лекарства на его основе (кроме состава аптечки)"}],"c":1,"e":{"uk":"До проведення медичного огляду водієві заборонено без призначення медичного працівника вживати алкоголь, наркотики та ліки на їх основі, крім препаратів з офіційної аптечки.","ru":"До проведения медицинского осмотра водителю запрещено без назначения медицинского работника употреблять алкоголь, наркотики и лекарства на их основе, кроме препаратов из официальной аптечки."},"ref":["2.10"],"id":"q52b37e77b"},{"t":"s8","q":{"uk":"Сигнали регулювальника суперечать сигналам світлофора. Чим має керуватися водій?","ru":"Сигналы регулировщика противоречат сигналам светофора. Чем должен руководствоваться водитель?"},"a":[{"uk":"Сигналами регулювальника","ru":"Сигналами регулировщика"},{"uk":"Сигналами світлофора","ru":"Сигналами светофора"},{"uk":"Знаками пріоритету","ru":"Знаками приоритета"}],"c":0,"e":{"uk":"Сигнали регулювальника мають перевагу перед сигналами світлофорів і вимогами дорожніх знаків. Його додаткові вимоги виконують, навіть якщо вони суперечать світлофору, знакам і розмітці.","ru":"Сигналы регулировщика имеют преимущество перед сигналами светофоров и требованиями дорожных знаков. Его дополнительные требования выполняют, даже если они противоречат светофору, знакам и разметке."},"ref":["8.3"],"id":"q7e20fe99a"},{"t":"s8","q":{"uk":"Тимчасовий знак на жовтому щиті суперечить постійному знаку. Який знак виконувати?","ru":"Временный знак на жёлтом щите противоречит постоянному знаку. Какой знак выполнять?"},"a":[{"uk":"Постійний","ru":"Постоянный"},{"uk":"Тимчасовий","ru":"Временный"},{"uk":"Той, що встановлено ближче до проїзної частини","ru":"Тот, что установлен ближе к проезжей части"}],"c":1,"e":{"uk":"Тимчасові дорожні знаки (на переносних пристроях або на щиті з жовтим фоном) мають перевагу перед постійними.","ru":"Временные дорожные знаки (на переносных устройствах или на щите с жёлтым фоном) имеют преимущество перед постоянными."},"ref":["8.2"],"id":"q044e692d8"},{"t":"s8","q":{"uk":"Вимоги дорожнього знака і горизонтальної розмітки суперечать одна одній. Чим керуватися?","ru":"Требования дорожного знака и горизонтальной разметки противоречат друг другу. Чем руководствоваться?"},"a":[{"uk":"Дорожнім знаком","ru":"Дорожным знаком"},{"uk":"Розміткою","ru":"Разметкой"},{"uk":"На власний розсуд","ru":"На своё усмотрение"}],"c":0,"e":{"uk":"Дорожні знаки мають перевагу перед дорожньою розміткою.","ru":"Дорожные знаки имеют преимущество перед дорожной разметкой."},"ref":["8.2"],"id":"q7bf3536d3"},{"t":"s8","q":{"uk":"Що означає жовтий миготливий сигнал світлофора?","ru":"Что означает жёлтый мигающий сигнал светофора?"},"a":[{"uk":"Забороняє рух","ru":"Запрещает движение"},{"uk":"Дозволяє рух та інформує про небезпечне нерегульоване перехрестя або пішохідний перехід","ru":"Разрешает движение и информирует об опасном нерегулируемом перекрёстке или пешеходном переходе"},{"uk":"Попереджає, що зараз увімкнеться зелений","ru":"Предупреждает, что сейчас включится зелёный"}],"img":{"scene":{"road":"cross","cars":[{"arm":"S","move":"straight","label":"1","color":"red","me":true}],"lights":[{"arm":"S","state":"flash"}]}},"c":1,"e":{"uk":"Жовтий миготливий сигнал дозволяє рух і попереджає про небезпечне нерегульоване перехрестя чи пішохідний перехід. Черговість проїзду в такому разі визначають знаки пріоритету.","ru":"Жёлтый мигающий сигнал разрешает движение и предупреждает об опасном нерегулируемом перекрёстке или пешеходном переходе. Очерёдность проезда в этом случае определяют знаки приоритета."},"ref":["8.7","16.1"],"id":"qe92cd8db2"},{"t":"s8","q":{"uk":"Під час наближення до перехрестя увімкнувся жовтий сигнал. Зупинитися перед стоп-лінією можна лише екстреним гальмуванням. Як діяти?","ru":"При приближении к перекрёстку включился жёлтый сигнал. Остановиться перед стоп-линией можно только экстренным торможением. Как поступить?"},"a":[{"uk":"Екстрено загальмувати","ru":"Экстренно затормозить"},{"uk":"Продовжити рух, забезпечивши безпеку","ru":"Продолжить движение, обеспечив безопасность"},{"uk":"Зупинитися за стоп-лінією посередині перехрестя","ru":"Остановиться за стоп-линией посередине перекрёстка"}],"c":1,"e":{"uk":"Водіям, які на жовтий сигнал або підняту вгору руку регулювальника не можуть зупинитися без екстреного гальмування, дозволено рухатися далі за умови безпеки руху.","ru":"Водителям, которые на жёлтый сигнал или поднятую вверх руку регулировщика не могут остановиться без экстренного торможения, разрешено двигаться дальше при условии безопасности движения."},"ref":["8.11"],"id":"q958fb265e"},{"t":"s8","q":{"uk":"Що означає поєднання червоного і жовтого сигналів світлофора?","ru":"Что означает сочетание красного и жёлтого сигналов светофора?"},"a":[{"uk":"Дозволяє рух з обережністю","ru":"Разрешает движение с осторожностью"},{"uk":"Дозволяє рух лише праворуч","ru":"Разрешает движение только направо"},{"uk":"Забороняє рух і попереджає, що незабаром увімкнеться зелений","ru":"Запрещает движение и предупреждает, что скоро включится зелёный"}],"img":{"scene":{"road":"cross","cars":[{"arm":"S","move":"straight","label":"1","color":"red","me":true}],"lights":[{"arm":"S","state":"redyellow"}]}},"c":2,"e":{"uk":"Поєднання червоного і жовтого забороняє рух і інформує про наступне вмикання зеленого сигналу.","ru":"Сочетание красного и жёлтого запрещает движение и информирует о предстоящем включении зелёного сигнала."},"ref":["8.7"],"id":"q661ce55a3"},{"t":"s8","q":{"uk":"Горить червоний сигнал і зелена стрілка в додатковій секції. Як можна рухатися в напрямку стрілки?","ru":"Горит красный сигнал и зелёная стрелка в дополнительной секции. Как можно двигаться в направлении стрелки?"},"a":[{"uk":"Рух заборонено, доки не ввімкнеться зелений","ru":"Движение запрещено, пока не включится зелёный"},{"uk":"Можна, пропустивши транспортні засоби, що рухаються з інших напрямків","ru":"Можно, пропустив транспортные средства, движущиеся с других направлений"},{"uk":"Можна, маючи перевагу перед усіма","ru":"Можно, имея преимущество перед всеми"}],"c":1,"e":{"uk":"Зелена стрілка в додатковій секції разом із жовтим або червоним сигналом дозволяє рух у напрямку стрілки за умови безперешкодного пропуску транспортних засобів з інших напрямків.","ru":"Зелёная стрелка в дополнительной секции вместе с жёлтым или красным сигналом разрешает движение в направлении стрелки при условии беспрепятственного пропуска транспортных средств с других направлений."},"ref":["8.7","16.9"],"id":"qc9c6cefb1"},{"t":"s8","q":{"uk":"На рівні червоного сигналу встановлено білу табличку із зеленою стрілкою праворуч. Звідки дозволено повертати праворуч на червоний?","ru":"На уровне красного сигнала установлена белая табличка с зелёной стрелкой направо. Откуда разрешено поворачивать направо на красный?"},"a":[{"uk":"Лише з крайньої правої смуги, пропустивши інших учасників руху","ru":"Только из крайней правой полосы, пропустив других участников движения"},{"uk":"З будь-якої смуги","ru":"Из любой полосы"},{"uk":"Повертати на червоний заборонено в будь-якому разі","ru":"Поворачивать на красный запрещено в любом случае"}],"c":0,"e":{"uk":"Стрілка на табличці дозволяє рух на червоний з крайньої правої смуги (на дорогах з одностороннім рухом ліворуч — з крайньої лівої) за умови, що водій дасть дорогу всім, хто рухається з інших напрямків на дозвільний сигнал.","ru":"Стрелка на табличке разрешает движение на красный из крайней правой полосы (на дорогах с односторонним движением налево — из крайней левой) при условии, что водитель уступит дорогу всем, кто движется с других направлений на разрешающий сигнал."},"ref":["8.7","16.9"],"id":"qb5b013e3d"},{"t":"s8","q":{"uk":"Сигнал додаткової секції світлофора вимкнено. Що це означає?","ru":"Сигнал дополнительной секции светофора выключен. Что это значит?"},"a":[{"uk":"Рух у напрямку стрілки дозволено з обережністю","ru":"Движение в направлении стрелки разрешено с осторожностью"},{"uk":"Рух у напрямку, вказаному стрілкою, заборонено","ru":"Движение в направлении, указанном стрелкой, запрещено"},{"uk":"Секція несправна, тож можна рухатися за основним сигналом","ru":"Секция неисправна, поэтому можно двигаться по основному сигналу"}],"c":1,"e":{"uk":"Вимкнений сигнал додаткової секції забороняє рух у напрямку, вказаному її стрілкою.","ru":"Выключенный сигнал дополнительной секции запрещает движение в направлении, указанном её стрелкой."},"ref":["8.7"],"id":"q0c0cbc4f9"},{"t":"s8","q":{"uk":"Сигнали реверсивного світлофора над смугою, позначеною з обох боків розміткою 1.9, вимкнені. Чи можна в'їжджати на цю смугу?","ru":"Сигналы реверсивного светофора над полосой, обозначенной с обеих сторон разметкой 1.9, выключены. Можно ли въезжать на эту полосу?"},"a":[{"uk":"Так, з обережністю","ru":"Да, с осторожностью"},{"uk":"Ні, в'їзд заборонено","ru":"Нет, въезд запрещён"},{"uk":"Так, якщо смуга вільна","ru":"Да, если полоса свободна"}],"img":{"mark":"1.9"},"c":1,"e":{"uk":"При вимкнених сигналах реверсивного світлофора над смугою, позначеною з обох боків розміткою {m:1.9}, в'їзд на цю смугу заборонено.","ru":"При выключенных сигналах реверсивного светофора над полосой, обозначенной с обеих сторон разметкой {m:1.9}, въезд на эту полосу запрещён."},"ref":["8.7"],"id":"q67c391764"},{"t":"s8","q":{"uk":"Регулювальник стоїть до вас боком, руки витягнуті в сторони. Куди можна рухатися на легковому автомобілі?","ru":"Регулировщик стоит к вам боком, руки вытянуты в стороны. Куда можно двигаться на легковом автомобиле?"},"a":[{"uk":"Лише прямо","ru":"Только прямо"},{"uk":"Прямо і праворуч","ru":"Прямо и направо"},{"uk":"У всіх напрямках","ru":"Во всех направлениях"},{"uk":"Рух заборонено","ru":"Движение запрещено"}],"c":1,"e":{"uk":"Руки витягнуті в сторони або опущені: з лівого і правого боків дозволено рух трамвая прямо, нерейковим транспортним засобам — прямо і праворуч. З боку грудей і спини рух заборонено.","ru":"Руки вытянуты в стороны или опущены: с левой и правой сторон разрешено движение трамвая прямо, нерельсовым транспортным средствам — прямо и направо. Со стороны груди и спины движение запрещено."},"ref":["8.8"],"id":"q2eb013dad"},{"t":"s8","q":{"uk":"Регулювальник стоїть до вас грудьми, руки опущені. Що означає цей сигнал?","ru":"Регулировщик стоит к вам грудью, руки опущены. Что означает этот сигнал?"},"a":[{"uk":"Рух заборонено","ru":"Движение запрещено"},{"uk":"Дозволено рух прямо","ru":"Разрешено движение прямо"},{"uk":"Дозволено рух лише праворуч","ru":"Разрешено движение только направо"}],"c":0,"e":{"uk":"Якщо руки витягнуті в сторони або опущені, з боку грудей і спини регулювальника рух усіх транспортних засобів і пішоходів заборонено.","ru":"Если руки вытянуты в стороны или опущены, со стороны груди и спины регулировщика движение всех транспортных средств и пешеходов запрещено."},"ref":["8.8"],"id":"qc85918764"},{"t":"s8","q":{"uk":"Регулювальник витягнув праву руку вперед, ви наближаєтеся з його лівого боку. Куди дозволено рух легковому автомобілю?","ru":"Регулировщик вытянул правую руку вперёд, вы приближаетесь с его левой стороны. Куда разрешено движение легковому автомобилю?"},"a":[{"uk":"Лише праворуч","ru":"Только направо"},{"uk":"Лише прямо","ru":"Только прямо"},{"uk":"У всіх напрямках","ru":"Во всех направлениях"}],"c":2,"e":{"uk":"Права рука витягнута вперед: з лівого боку регулювальника нерейковим транспортним засобам дозволено рух у всіх напрямках, трамваю — ліворуч.","ru":"Правая рука вытянута вперёд: с левой стороны регулировщика нерельсовым транспортным средствам разрешено движение во всех направлениях, трамваю — налево."},"ref":["8.8"],"id":"q2dea8ff24"},{"t":"s8","q":{"uk":"Регулювальник витягнув праву руку вперед і стоїть до вас грудьми. Куди можна рухатися?","ru":"Регулировщик вытянул правую руку вперёд и стоит к вам грудью. Куда можно двигаться?"},"a":[{"uk":"Лише праворуч","ru":"Только направо"},{"uk":"Прямо і праворуч","ru":"Прямо и направо"},{"uk":"Рух заборонено","ru":"Движение запрещено"}],"c":0,"e":{"uk":"Коли права рука витягнута вперед, з боку грудей усім транспортним засобам дозволено рух лише праворуч. З правого боку і зі спини рух заборонено.","ru":"Когда правая рука вытянута вперёд, со стороны груди всем транспортным средствам разрешено движение только направо. С правой стороны и со спины движение запрещено."},"ref":["8.8"],"id":"qe58d73b8d"},{"t":"s8","q":{"uk":"Що означає піднята вгору рука регулювальника?","ru":"Что означает поднятая вверх рука регулировщика?"},"a":[{"uk":"Увага, зараз зміниться сигнал, можна продовжувати рух","ru":"Внимание, сейчас сменится сигнал, можно продолжать движение"},{"uk":"Рух усіх транспортних засобів і пішоходів заборонено в усіх напрямках","ru":"Движение всех транспортных средств и пешеходов запрещено во всех направлениях"},{"uk":"Рух дозволено лише трамваям","ru":"Движение разрешено только трамваям"}],"c":1,"e":{"uk":"Рука, піднята вгору, забороняє рух усім в усіх напрямках. Хто вже не може зупинитися без екстреного гальмування, може проїхати далі.","ru":"Поднятая вверх рука запрещает движение всем во всех направлениях. Кто уже не может остановиться без экстренного торможения, может проехать дальше."},"ref":["8.8","8.11"],"id":"qb22313d65"},{"t":"s8","q":{"uk":"Перед залізничним переїздом горить заборонний сигнал, стоп-лінії та знака 5.69 немає. Де треба зупинитися?","ru":"Перед железнодорожным переездом горит запрещающий сигнал, стоп-линии и знака 5.69 нет. Где нужно остановиться?"},"a":[{"uk":"Безпосередньо перед рейками","ru":"Непосредственно перед рельсами"},{"uk":"Не ближче 10 м до найближчої рейки","ru":"Не ближе 10 м до ближайшего рельса"},{"uk":"Не ближче 5 м до шлагбаума","ru":"Не ближе 5 м до шлагбаума"}],"c":1,"e":{"uk":"На заборонний сигнал водій зупиняється перед стоп-лінією або знаком {s:5.69}, а якщо їх немає — не ближче 10 м до найближчої рейки.","ru":"На запрещающий сигнал водитель останавливается перед стоп-линией или знаком {s:5.69}, а если их нет — не ближе 10 м до ближайшего рельса."},"ref":["8.10"],"id":"qc6751ad4a"},{"t":"s8","q":{"uk":"Сигнали світлофора (крім жовтого миготливого) і знаки пріоритету суперечать одне одному. Чим керуватися?","ru":"Сигналы светофора (кроме жёлтого мигающего) и знаки приоритета противоречат друг другу. Чем руководствоваться?"},"a":[{"uk":"Знаками пріоритету","ru":"Знаками приоритета"},{"uk":"Сигналами світлофора","ru":"Сигналами светофора"}],"c":1,"e":{"uk":"Сигнали світлофорів, крім жовтого миготливого, мають перевагу перед знаками пріоритету.","ru":"Сигналы светофоров, кроме жёлтого мигающего, имеют преимущество перед знаками приоритета."},"ref":["8.3"],"id":"q86f7b0f02"},{"t":"s8","q":{"uk":"Якого кольору світлоповертачі на напрямних стовпчиках праворуч від дороги?","ru":"Какого цвета световозвращатели на направляющих столбиках справа от дороги?"},"a":[{"uk":"Червоного","ru":"Красного"},{"uk":"Білого","ru":"Белого"},{"uk":"Жовтого","ru":"Жёлтого"}],"c":0,"e":{"uk":"Напрямні стовпчики обладнують світлоповертачами: праворуч — червоного кольору, ліворуч — білого.","ru":"Направляющие столбики оборудуют световозвращателями: справа — красного цвета, слева — белого."},"ref":["8.6"],"id":"q9ff604df9"},{"t":"s9","q":{"uk":"За яку відстань до маневру в населеному пункті треба вмикати покажчик повороту?","ru":"За какое расстояние до манёвра в населённом пункте нужно включать указатель поворота?"},"a":[{"uk":"Завчасно, але не менш як за 50–100 м","ru":"Заблаговременно, но не менее чем за 50–100 м"},{"uk":"За 10–20 м","ru":"За 10–20 м"},{"uk":"За 150–200 м","ru":"За 150–200 м"}],"c":0,"e":{"uk":"Сигнал подають завчасно з урахуванням швидкості: у населених пунктах не менш як за 50–100 м, поза ними — за 150–200 м. Вимикають одразу після маневру.","ru":"Сигнал подают заблаговременно с учётом скорости: в населённых пунктах не менее чем за 50–100 м, вне их — за 150–200 м. Выключают сразу после манёвра."},"ref":["9.4"],"id":"q01bbe5de0"},{"t":"s9","q":{"uk":"Чи дає увімкнений покажчик повороту перевагу в русі?","ru":"Даёт ли включённый указатель поворота преимущество в движении?"},"a":[{"uk":"Так, інші мають пропустити","ru":"Да, другие должны пропустить"},{"uk":"Ні, він не дає переваги і не звільняє від запобіжних заходів","ru":"Нет, он не даёт преимущества и не освобождает от мер предосторожности"},{"uk":"Так, але лише в населеному пункті","ru":"Да, но только в населённом пункте"}],"c":1,"e":{"uk":"Подавання попереджувального сигналу не дає водієві переваги і не звільняє його від вжиття запобіжних заходів.","ru":"Подача предупредительного сигнала не даёт водителю преимущества и не освобождает его от принятия мер предосторожности."},"ref":["9.4"],"id":"qb35ea7989"},{"t":"s9","q":{"uk":"Покажчики повороту несправні. Як подати сигнал повороту ліворуч?","ru":"Указатели поворота неисправны. Как подать сигнал поворота налево?"},"a":[{"uk":"Лівою рукою, витягнутою вбік, або правою рукою, витягнутою вбік і зігнутою в лікті вгору","ru":"Левой рукой, вытянутой в сторону, или правой рукой, вытянутой в сторону и согнутой в локте вверх"},{"uk":"Рукою, піднятою вгору","ru":"Рукой, поднятой вверх"},{"uk":"Правою рукою, витягнутою вбік","ru":"Правой рукой, вытянутой в сторону"}],"c":0,"e":{"uk":"Поворот ліворуч (а також розворот, перестроювання ліворуч, зупинка зліва) показують лівою рукою, витягнутою вбік, або правою, витягнутою вбік і зігнутою в лікті під прямим кутом угору. Рука, піднята вгору, — сигнал гальмування.","ru":"Поворот налево (а также разворот, перестроение налево, остановку слева) показывают левой рукой, вытянутой в сторону, или правой, вытянутой в сторону и согнутой в локте под прямым углом вверх. Рука, поднятая вверх, — сигнал торможения."},"ref":["9.3"],"id":"qd696f51a0"},{"t":"s9","q":{"uk":"Коли в населеному пункті можна подавати звуковий сигнал?","ru":"Когда в населённом пункте можно подавать звуковой сигнал?"},"a":[{"uk":"Для привернення уваги водія, якого обганяють","ru":"Для привлечения внимания обгоняемого водителя"},{"uk":"Лише коли без цього неможливо запобігти ДТП","ru":"Только когда без этого невозможно предотвратить ДТП"},{"uk":"Перед кожним перехрестям","ru":"Перед каждым перекрёстком"}],"c":1,"e":{"uk":"У населених пунктах звуковий сигнал заборонено, крім випадків, коли без нього неможливо запобігти ДТП. Поза населеними пунктами звуком можна попередити водія, якого обганяєте.","ru":"В населённых пунктах звуковой сигнал запрещён, кроме случаев, когда без него невозможно предотвратить ДТП. Вне населённых пунктов звуком можно предупредить обгоняемого водителя."},"ref":["9.5","9.6"],"id":"qfd3a3059d"},{"t":"s9","q":{"uk":"Що має бути ввімкнено на легковому автомобілі поза населеним пунктом удень?","ru":"Что должно быть включено на легковом автомобиле вне населённого пункта днём?"},"a":[{"uk":"Нічого","ru":"Ничего"},{"uk":"Денні ходові вогні, а якщо їх немає — ближнє світло","ru":"Дневные ходовые огни, а если их нет — ближний свет"},{"uk":"Протитуманні фари","ru":"Противотуманные фары"},{"uk":"Габаритні вогні","ru":"Габаритные огни"}],"c":1,"e":{"uk":"Поза населеними пунктами на всіх механічних транспортних засобах мають бути ввімкнені денні ходові вогні, а якщо їх немає в конструкції — ближнє світло фар.","ru":"Вне населённых пунктов на всех механических транспортных средствах должны быть включены дневные ходовые огни, а если их нет в конструкции — ближний свет фар."},"ref":["9.8"],"id":"q5a2e1f3ca"},{"t":"s9","q":{"uk":"У якому з випадків вмикати аварійну сигналізацію НЕ обов'язково?","ru":"В каком из случаев включать аварийную сигнализацию НЕ обязательно?"},"a":[{"uk":"Вимушена зупинка на дорозі","ru":"Вынужденная остановка на дороге"},{"uk":"Зупинка через засліплення світлом фар","ru":"Остановка из-за ослепления светом фар"},{"uk":"Зупинка для посадки пасажира в дозволеному місці","ru":"Остановка для посадки пассажира в разрешённом месте"},{"uk":"Автомобіль буксирують","ru":"Автомобиль буксируют"}],"c":2,"e":{"uk":"Аварійну сигналізацію вмикають за вимушеної зупинки, зупинки на вимогу поліцейського чи через засліплення, під час руху з несправностями, на автомобілі, що буксирується, під час посадки дітей в автобус зі знаком «Діти», на зупинці колони та в разі ДТП.","ru":"Аварийную сигнализацию включают при вынужденной остановке, остановке по требованию полицейского или из-за ослепления, при движении с неисправностями, на буксируемом автомобиле, при посадке детей в автобус со знаком «Дети», на остановке колонны и при ДТП."},"ref":["9.9"],"id":"q2ff1de7b8"},{"t":"s9","q":{"uk":"На якій відстані від автомобіля треба виставити знак аварійної зупинки після ДТП у населеному пункті?","ru":"На каком расстоянии от автомобиля нужно выставить знак аварийной остановки после ДТП в населённом пункте?"},"a":[{"uk":"Не ближче 10 м","ru":"Не ближе 10 м"},{"uk":"Не ближче 20 м","ru":"Не ближе 20 м"},{"uk":"Не ближче 40 м","ru":"Не ближе 40 м"},{"uk":"Не ближче 50 м","ru":"Не ближе 50 м"}],"c":1,"e":{"uk":"Знак аварійної зупинки (або миготливий червоний ліхтар) встановлюють не ближче 20 м від автомобіля в населеному пункті і 40 м — поза ним.","ru":"Знак аварийной остановки (или мигающий красный фонарь) устанавливают не ближе 20 м от автомобиля в населённом пункте и 40 м — вне его."},"ref":["9.10"],"id":"qb7e34f572"},{"t":"s9","q":{"uk":"Знак аварійної зупинки поза населеним пунктом встановлюють не ближче ніж...","ru":"Знак аварийной остановки вне населённого пункта устанавливают не ближе чем..."},"a":[{"uk":"20 м","ru":"20 м"},{"uk":"30 м","ru":"30 м"},{"uk":"40 м","ru":"40 м"},{"uk":"100 м","ru":"100 м"}],"c":2,"e":{"uk":"Поза населеними пунктами знак аварійної зупинки — не ближче 40 м від транспортного засобу.","ru":"Вне населённых пунктов знак аварийной остановки — не ближе 40 м от транспортного средства."},"ref":["9.10"],"id":"q3eacf129d"},{"t":"s9","q":{"uk":"Коли, крім ДТП, обов'язково виставляти знак аварійної зупинки?","ru":"Когда, кроме ДТП, обязательно выставлять знак аварийной остановки?"},"a":[{"uk":"За вимушеної зупинки там, де оглядовість хоча б в одному напрямку менше 100 м","ru":"При вынужденной остановке там, где обзорность хотя бы в одном направлении менее 100 м"},{"uk":"За будь-якої зупинки в темну пору доби","ru":"При любой остановке в тёмное время суток"},{"uk":"Під час стоянки понад 5 хвилин","ru":"Во время стоянки более 5 минут"}],"c":0,"e":{"uk":"Разом з аварійкою знак виставляють у разі ДТП і вимушеної зупинки там, де оглядовість дороги хоча б в одному напрямку менше 100 м.","ru":"Вместе с аварийкой знак выставляют при ДТП и вынужденной остановке там, где обзорность дороги хотя бы в одном направлении менее 100 м."},"ref":["9.10"],"id":"qf1a5d8516"},{"t":"s9","q":{"uk":"Як попередити водія, якого обганяєте, у населеному пункті?","ru":"Как предупредить обгоняемого водителя в населённом пункте?"},"a":[{"uk":"Звуковим сигналом","ru":"Звуковым сигналом"},{"uk":"Перемиканням світла фар","ru":"Переключением света фар"},{"uk":"Аварійною сигналізацією","ru":"Аварийной сигнализацией"}],"c":1,"e":{"uk":"Для привернення уваги водія, якого обганяють, можна перемикати світло фар, а поза населеними пунктами — ще й подати звуковий сигнал.","ru":"Для привлечения внимания обгоняемого водителя можно переключать свет фар, а вне населённых пунктов — ещё и подать звуковой сигнал."},"ref":["9.6","9.5"],"id":"q38a148288"},{"t":"s10","q":{"uk":"Водій виїжджає з території АЗС на дорогу. Кому він повинен дати дорогу?","ru":"Водитель выезжает с территории АЗС на дорогу. Кому он должен уступить дорогу?"},"a":[{"uk":"Лише транспортним засобам, що наближаються ліворуч","ru":"Только транспортным средствам, приближающимся слева"},{"uk":"Нікому, якщо він увімкнув покажчик повороту","ru":"Никому, если он включил указатель поворота"},{"uk":"Пішоходам і транспортним засобам, що рухаються дорогою","ru":"Пешеходам и транспортным средствам, движущимся по дороге"}],"c":2,"e":{"uk":"Виїжджаючи з прилеглої території (двори, стоянки, АЗС, житлова зона), водій дає дорогу пішоходам і транспортним засобам, що рухаються по дорозі чи тротуару, який він перетинає.","ru":"Выезжая с прилегающей территории (дворы, стоянки, АЗС, жилая зона), водитель уступает дорогу пешеходам и транспортным средствам, движущимся по дороге или тротуару, который он пересекает."},"ref":["10.2"],"id":"q26b0b546e"},{"t":"s10","q":{"uk":"Водій 1 перестроюється ліворуч. Хто має перевагу?","ru":"Водитель 1 перестраивается налево. У кого преимущество?"},"a":[{"uk":"Автомобіль 1, бо він увімкнув покажчик повороту","ru":"Автомобиль 1, так как он включил указатель поворота"},{"uk":"Автомобіль 2, що рухається смугою, на яку перестроюється водій 1","ru":"Автомобиль 2, движущийся по полосе, на которую перестраивается водитель 1"},{"uk":"Той, хто рухається швидше","ru":"Тот, кто движется быстрее"}],"img":{"scene":{"road":"straight","lanes":2,"center":"solid","cars":[{"x":150,"dir":"E","lane":0,"move":"left","label":"1","color":"red","me":true},{"x":60,"dir":"E","lane":1,"move":"straight","label":"2","color":"blue"}]}},"c":1,"e":{"uk":"Перестроюючись, водій дає дорогу транспортним засобам, що рухаються в попутному напрямку смугою, на яку він має намір перестроїтися.","ru":"При перестроении водитель уступает дорогу транспортным средствам, движущимся в попутном направлении по полосе, на которую он намерен перестроиться."},"ref":["10.3"],"id":"q40e2cf663"},{"t":"s10","q":{"uk":"Водії 1 і 2 одночасно перестроюються на середню смугу. Хто має поступитися?","ru":"Водители 1 и 2 одновременно перестраиваются на среднюю полосу. Кто должен уступить?"},"a":[{"uk":"Водій 1, бо водій 2 знаходиться праворуч від нього","ru":"Водитель 1, так как водитель 2 находится справа от него"},{"uk":"Водій 2, бо водій 1 рухається лівішою смугою","ru":"Водитель 2, так как водитель 1 движется по более левой полосе"},{"uk":"Той, хто першим увімкнув покажчик","ru":"Тот, кто первым включил указатель"}],"img":{"scene":{"road":"straight","lanes":3,"center":"double","cars":[{"x":120,"dir":"E","lane":2,"move":"right","label":"1","color":"red","me":true},{"x":120,"dir":"E","lane":0,"move":"left","label":"2","color":"blue"}]}},"c":0,"e":{"uk":"За одночасного перестроювання водій, який знаходиться ліворуч, дає дорогу транспортному засобу, що знаходиться праворуч.","ru":"При одновременном перестроении водитель, находящийся слева, уступает дорогу транспортному средству, находящемуся справа."},"ref":["10.3"],"id":"q87bf6c3da"},{"t":"s10","q":{"uk":"Як треба підготуватися до повороту ліворуч на дорозі з двома смугами в одному напрямку?","ru":"Как нужно подготовиться к повороту налево на дороге с двумя полосами в одном направлении?"},"a":[{"uk":"Повертати з будь-якої смуги, увімкнувши покажчик","ru":"Поворачивать с любой полосы, включив указатель"},{"uk":"Завчасно зайняти крайнє ліве положення на проїзній частині цього напрямку","ru":"Заблаговременно занять крайнее левое положение на проезжей части этого направления"},{"uk":"Зупинитися на правому узбіччі й пропустити всіх","ru":"Остановиться на правой обочине и пропустить всех"}],"c":1,"e":{"uk":"Перед поворотом праворуч чи ліворуч або розворотом водій завчасно займає відповідне крайнє положення. Винятки — в'їзд на кільце та випадки, коли напрямок визначено знаками чи розміткою.","ru":"Перед поворотом направо или налево либо разворотом водитель заблаговременно занимает соответствующее крайнее положение. Исключения — въезд на кольцо и случаи, когда направление определено знаками или разметкой."},"ref":["10.4"],"id":"qfd0ca0d82"},{"t":"s10","q":{"uk":"У якому з перелічених місць розворот заборонено?","ru":"В каком из перечисленных мест разворот запрещён?"},"a":[{"uk":"На мосту","ru":"На мосту"},{"uk":"У тунелі","ru":"В тоннеле"},{"uk":"На залізничному переїзді","ru":"На железнодорожном переезде"},{"uk":"У всіх перелічених місцях","ru":"Во всех перечисленных местах"}],"c":3,"e":{"uk":"Розворот заборонено на залізничних переїздах, на мостах, шляхопроводах, естакадах і під ними, у тунелях, за видимості менше 100 м хоча б в одному напрямку, на пішохідних переходах і ближче 10 м від них, на автомагістралях і дорогах для автомобілів (крім перехресть і місць {s:5.29}, {s:5.30}).","ru":"Разворот запрещён на железнодорожных переездах, на мостах, путепроводах, эстакадах и под ними, в тоннелях, при видимости менее 100 м хотя бы в одном направлении, на пешеходных переходах и ближе 10 м от них, на автомагистралях и дорогах для автомобилей (кроме перекрёстков и мест {s:5.29}, {s:5.30})."},"ref":["10.7"],"id":"qa7334e352"},{"t":"s10","q":{"uk":"За якої видимості дороги розворот заборонено?","ru":"При какой видимости дороги разворот запрещён?"},"a":[{"uk":"Менше 50 м в обох напрямках","ru":"Менее 50 м в обоих направлениях"},{"uk":"Менше 100 м хоча б в одному напрямку","ru":"Менее 100 м хотя бы в одном направлении"},{"uk":"Менше 300 м у напрямку руху","ru":"Менее 300 м в направлении движения"}],"c":1,"e":{"uk":"Розворот заборонено, якщо видимість дороги менше 100 м хоча б в одному напрямку.","ru":"Разворот запрещён, если видимость дороги менее 100 м хотя бы в одном направлении."},"ref":["10.7"],"id":"qb06af2fb4"},{"t":"s10","q":{"uk":"На якій найменшій відстані від пішохідного переходу дозволено розворот поза перехрестям?","ru":"На каком наименьшем расстоянии от пешеходного перехода разрешён разворот вне перекрёстка?"},"a":[{"uk":"5 м","ru":"5 м"},{"uk":"10 м","ru":"10 м"},{"uk":"15 м","ru":"15 м"},{"uk":"20 м","ru":"20 м"}],"c":1,"e":{"uk":"Розворот заборонено на пішохідних переходах і ближче 10 м від них з обох боків (крім дозволеного розвороту на перехресті).","ru":"Разворот запрещён на пешеходных переходах и ближе 10 м от них с обеих сторон (кроме разрешённого разворота на перекрёстке)."},"ref":["10.7"],"id":"qeedd67e1e"},{"t":"s10","q":{"uk":"Де дозволено рух заднім ходом?","ru":"Где разрешено движение задним ходом?"},"a":[{"uk":"На перехресті, якщо немає інших транспортних засобів","ru":"На перекрёстке, если нет других транспортных средств"},{"uk":"На мосту, якщо водій пропустив поворот","ru":"На мосту, если водитель пропустил поворот"},{"uk":"На дорозі з одностороннім рухом, якщо інакше під'їхати до об'єкта неможливо","ru":"На дороге с односторонним движением, если иначе подъехать к объекту невозможно"}],"c":2,"e":{"uk":"Рух заднім ходом заборонено на автомагістралях, дорогах для автомобілів, переїздах, пішохідних переходах, перехрестях, мостах, естакадах, у тунелях і на ділянках з обмеженою оглядовістю. На дорозі з одностороннім рухом він дозволений, якщо інакше під'їхати неможливо і це безпечно.","ru":"Движение задним ходом запрещено на автомагистралях, дорогах для автомобилей, переездах, пешеходных переходах, перекрёстках, мостах, эстакадах, в тоннелях и на участках с ограниченной обзорностью. На дороге с односторонним движением оно разрешено, если иначе подъехать невозможно и это безопасно."},"ref":["10.10"],"id":"q11098d50a"},{"t":"s10","q":{"uk":"Перед з'їздом з дороги є смуга гальмування. Де слід знижувати швидкість?","ru":"Перед съездом с дороги есть полоса торможения. Где следует снижать скорость?"},"a":[{"uk":"Лише на смузі гальмування, своєчасно на неї перестроївшись","ru":"Только на полосе торможения, своевременно на неё перестроившись"},{"uk":"На основній смузі перед смугою гальмування","ru":"На основной полосе перед полосой торможения"},{"uk":"Байдуже, де саме","ru":"Неважно, где именно"}],"c":0,"e":{"uk":"Якщо є смуга гальмування, водій своєчасно перестроюється на неї і знижує швидкість тільки на ній, щоб не заважати потоку.","ru":"Если есть полоса торможения, водитель своевременно перестраивается на неё и снижает скорость только на ней, чтобы не мешать потоку."},"ref":["10.8"],"id":"q9c3d0e51f"},{"t":"s10","q":{"uk":"Водій виїжджає на дорогу смугою розгону. Хто має перевагу?","ru":"Водитель выезжает на дорогу по полосе разгона. У кого преимущество?"},"a":[{"uk":"Водій на смузі розгону","ru":"Водитель на полосе разгона"},{"uk":"Транспортні засоби, що рухаються цією дорогою","ru":"Транспортные средства, движущиеся по этой дороге"}],"c":1,"e":{"uk":"Рухаючись смугою розгону, водій вливається в потік, даючи дорогу транспортним засобам, що рухаються дорогою.","ru":"Двигаясь по полосе разгона, водитель вливается в поток, уступая дорогу транспортным средствам, движущимся по дороге."},"ref":["10.8"],"id":"qb88e2c3c5"},{"t":"s10","q":{"uk":"Траєкторії руху двох автомобілів перетинаються, а черговість проїзду Правилами не обумовлена. Хто поступається?","ru":"Траектории движения двух автомобилей пересекаются, а очерёдность проезда Правилами не оговорена. Кто уступает?"},"a":[{"uk":"Водій, до якого інший автомобіль наближається з правого боку","ru":"Водитель, к которому другой автомобиль приближается справа"},{"uk":"Водій, до якого інший автомобіль наближається з лівого боку","ru":"Водитель, к которому другой автомобиль приближается слева"},{"uk":"Водій, який рухається повільніше","ru":"Водитель, который движется медленнее"}],"c":0,"e":{"uk":"Якщо траєкторії перетинаються, а черговість не визначено Правилами (наприклад, на парковці), діє правило «перешкода праворуч».","ru":"Если траектории пересекаются, а очерёдность не определена Правилами (например, на парковке), действует правило «помеха справа»."},"ref":["10.11"],"id":"q1597e588b"},{"t":"s10","q":{"uk":"Водій повертає ліворуч поза перехрестям, посередині дороги — трамвайна колія. Кому він дає дорогу?","ru":"Водитель поворачивает налево вне перекрёстка, посередине дороги — трамвайные пути. Кому он уступает дорогу?"},"a":[{"uk":"Лише зустрічним автомобілям","ru":"Только встречным автомобилям"},{"uk":"Зустрічним транспортним засобам і трамваю","ru":"Встречным транспортным средствам и трамваю"},{"uk":"Нікому, бо він на головній дорозі","ru":"Никому, так как он на главной дороге"}],"c":1,"e":{"uk":"Повертаючи ліворуч або розвертаючись поза перехрестям, водій дає дорогу зустрічним транспортним засобам, а за наявності трамвайної колії посередині — і трамваю.","ru":"Поворачивая налево или разворачиваясь вне перекрёстка, водитель уступает дорогу встречным транспортным средствам, а при наличии трамвайных путей посередине — и трамваю."},"ref":["10.4"],"id":"q4339e47ca"},{"t":"s10","q":{"uk":"З якої смуги можна виїхати з перехрестя з круговим рухом, якщо напрямок не визначено знаками чи розміткою?","ru":"С какой полосы можно выехать с перекрёстка с круговым движением, если направление не определено знаками или разметкой?"},"a":[{"uk":"Лише з крайньої правої","ru":"Только с крайней правой"},{"uk":"З будь-якої смуги, якщо це не заважає транспортним засобам праворуч","ru":"С любой полосы, если это не мешает транспортным средствам справа"},{"uk":"Лише з крайньої лівої","ru":"Только с крайней левой"}],"c":1,"e":{"uk":"Виїзд з кільця можливий з будь-якої смуги, якщо напрямок не визначено знаками чи розміткою і це не створить перешкод попутним транспортним засобам праворуч.","ru":"Выезд с кольца возможен с любой полосы, если направление не определено знаками или разметкой и это не создаст помех попутным транспортным средствам справа."},"ref":["10.5"],"id":"q589d49eae"},{"t":"s11","q":{"uk":"Якою смугою має рухатися легковий автомобіль на дорозі з двома смугами в одному напрямку, якщо обидві вільні?","ru":"По какой полосе должен двигаться легковой автомобиль на дороге с двумя полосами в одном направлении, если обе свободны?"},"a":[{"uk":"Якнайближче до правого краю, тобто правою смугою","ru":"Как можно ближе к правому краю, то есть по правой полосе"},{"uk":"Будь-якою на вибір водія","ru":"Любой по выбору водителя"},{"uk":"Лівою, бо вона швидша","ru":"Левой, так как она быстрее"}],"c":0,"e":{"uk":"На дорогах з двома і більше смугами в одному напрямку нерейкові транспортні засоби рухаються якнайближче до правого краю. Ліву смугу використовують для випередження, об'їзду чи перестроювання перед поворотом ліворуч або розворотом, а також коли праві смуги зайняті.","ru":"На дорогах с двумя и более полосами в одном направлении нерельсовые транспортные средства движутся как можно ближе к правому краю. Левую полосу используют для опережения, объезда или перестроения перед поворотом налево либо разворотом, а также когда правые полосы заняты."},"ref":["11.2","11.5"],"id":"q541400072"},{"t":"s11","q":{"uk":"Дорога з двостороннім рухом має по дві смуги в кожному напрямку, розмітки немає. Чи можна виїхати на зустрічний бік для обгону?","ru":"Дорога с двусторонним движением имеет по две полосы в каждом направлении, разметки нет. Можно ли выехать на встречную сторону для обгона?"},"a":[{"uk":"Так, якщо зустрічна смуга вільна","ru":"Да, если встречная полоса свободна"},{"uk":"Ні, це заборонено","ru":"Нет, это запрещено"},{"uk":"Так, але лише поза населеним пунктом","ru":"Да, но только вне населённого пункта"}],"c":1,"e":{"uk":"На дорогах з двостороннім рухом, які мають щонайменше дві смуги для руху в одному напрямку, виїжджати на бік дороги, призначений для зустрічного руху, заборонено.","ru":"На дорогах с двусторонним движением, имеющих не менее двух полос для движения в одном направлении, выезжать на сторону дороги, предназначенную для встречного движения, запрещено."},"ref":["11.4"],"id":"qa7b23d917"},{"t":"s11","q":{"uk":"Для чого вантажному автомобілю масою понад 3,5 т дозволено займати крайню ліву смугу на дорозі з трьома смугами в одному напрямку?","ru":"Для чего грузовому автомобилю массой более 3,5 т разрешено занимать крайнюю левую полосу на дороге с тремя полосами в одном направлении?"},"a":[{"uk":"Для випередження","ru":"Для опережения"},{"uk":"Лише для повороту ліворуч і розвороту","ru":"Только для поворота налево и разворота"},{"uk":"У будь-якому разі, якщо праві смуги зайняті","ru":"В любом случае, если правые полосы заняты"}],"c":1,"e":{"uk":"На дорогах з трьома і більше смугами в одному напрямку вантажівки понад 3,5 т, трактори та самохідні машини виїжджають на крайню ліву смугу лише для повороту ліворуч і розвороту.","ru":"На дорогах с тремя и более полосами в одном направлении грузовики более 3,5 т, тракторы и самоходные машины выезжают на крайнюю левую полосу только для поворота налево и разворота."},"ref":["11.6"],"id":"q09a1d5e64"},{"t":"s11","q":{"uk":"Чи можна рухатися трамвайною колією зустрічного напрямку?","ru":"Можно ли двигаться по трамвайным путям встречного направления?"},"a":[{"uk":"Так, якщо немає трамвая","ru":"Да, если нет трамвая"},{"uk":"Так, для об'їзду перешкоди","ru":"Да, для объезда препятствия"},{"uk":"Ні, це заборонено","ru":"Нет, это запрещено"}],"c":2,"e":{"uk":"Виїжджати на трамвайну колію зустрічного напрямку, відокремлені від проїзної частини трамвайні колії та розділювальну смугу заборонено.","ru":"Выезжать на трамвайные пути встречного направления, обособленные от проезжей части трамвайные пути и разделительную полосу запрещено."},"ref":["11.9"],"id":"q7006d4e84"},{"t":"s11","q":{"uk":"Звідки треба виконувати поворот ліворуч, якщо посередині дороги на одному рівні з проїзною частиною проходить трамвайна колія попутного напрямку, а знаків і розмітки немає?","ru":"Откуда нужно выполнять поворот налево, если посередине дороги на одном уровне с проезжей частью проходят трамвайные пути попутного направления, а знаков и разметки нет?"},"a":[{"uk":"З трамвайної колії попутного напрямку, не заважаючи трамваю","ru":"С трамвайных путей попутного направления, не мешая трамваю"},{"uk":"З крайньої лівої смуги проїзної частини поруч із коліями","ru":"С крайней левой полосы проезжей части рядом с путями"},{"uk":"З правої смуги","ru":"С правой полосы"}],"c":0,"e":{"uk":"Поворот ліворуч і розворот виконують з трамвайної колії попутного напрямку, розташованої на одному рівні з проїзною частиною, якщо знаки {s:5.16}, {s:5.18} або розмітка {m:1.18} не встановлюють іншого порядку. Трамваю заважати не можна.","ru":"Поворот налево и разворот выполняют с трамвайных путей попутного направления, расположенных на одном уровне с проезжей частью, если знаки {s:5.16}, {s:5.18} или разметка {m:1.18} не устанавливают иного порядка. Трамваю мешать нельзя."},"ref":["11.8"],"id":"q410e0f616"},{"t":"s11","q":{"uk":"Чи можна рухатися, займаючи одночасно дві смуги, розділені переривчастою лінією?","ru":"Можно ли двигаться, занимая одновременно две полосы, разделённые прерывистой линией?"},"a":[{"uk":"Так, якщо інших автомобілів немає","ru":"Да, если других автомобилей нет"},{"uk":"Ні. Наїжджати на переривчасту лінію можна лише під час перестроювання","ru":"Нет. Наезжать на прерывистую линию можно только при перестроении"},{"uk":"Так, у темну пору доби","ru":"Да, в тёмное время суток"}],"c":1,"e":{"uk":"Рухатися, займаючи одночасно дві смуги, заборонено. Наїжджати на переривчасті лінії розмітки дозволено лише під час перестроювання.","ru":"Двигаться, занимая одновременно две полосы, запрещено. Наезжать на прерывистые линии разметки разрешено только при перестроении."},"ref":["11.10"],"id":"qe17e833b0"},{"t":"s11","q":{"uk":"Рух інтенсивний. У яких випадках можна змінювати смугу?","ru":"Движение интенсивное. В каких случаях можно менять полосу?"},"a":[{"uk":"У будь-яких, якщо увімкнено покажчик повороту","ru":"В любых, если включён указатель поворота"},{"uk":"Лише для об'їзду перешкоди, повороту, розвороту або зупинки","ru":"Только для объезда препятствия, поворота, разворота или остановки"},{"uk":"Лише для обгону","ru":"Только для обгона"}],"c":1,"e":{"uk":"При інтенсивному русі змінювати смугу дозволено лише для об'їзду перешкоди, повороту, розвороту або зупинки.","ru":"При интенсивном движении менять полосу разрешено только для объезда препятствия, поворота, разворота или остановки."},"ref":["11.11"],"id":"q593379c9e"},{"t":"s11","q":{"uk":"Як мають рухатися велосипедисти по проїзній частині?","ru":"Как должны двигаться велосипедисты по проезжей части?"},"a":[{"uk":"Не більше ніж у два ряди","ru":"Не более чем в два ряда"},{"uk":"В один ряд по крайній правій смузі якомога правіше","ru":"В один ряд по крайней правой полосе как можно правее"},{"uk":"Будь-якою смугою","ru":"По любой полосе"}],"c":1,"e":{"uk":"Велосипеди, мопеди, гужові вози та вершники рухаються проїзною частиною лише в один ряд по крайній правій смузі якомога правіше. Рух узбіччям дозволено, якщо це не заважає пішоходам.","ru":"Велосипеды, мопеды, гужевые повозки и всадники движутся по проезжей части только в один ряд по крайней правой полосе как можно правее. Движение по обочине разрешено, если это не мешает пешеходам."},"ref":["11.14"],"id":"q8f647d731"},{"t":"s11","q":{"uk":"На дорозі з однією смугою в кожному напрямку немає суцільної розмітки. Для чого можна виїхати на смугу зустрічного руху?","ru":"На дороге с одной полосой в каждом направлении нет сплошной разметки. Для чего можно выехать на полосу встречного движения?"},"a":[{"uk":"Для обгону, об'їзду перешкоди, а в населених пунктах — для зупинки чи стоянки біля лівого краю в дозволених випадках","ru":"Для обгона, объезда препятствия, а в населённых пунктах — для остановки или стоянки у левого края в разрешённых случаях"},{"uk":"Для руху в заторі","ru":"Для движения в заторе"},{"uk":"Лише для розвороту","ru":"Только для разворота"}],"c":0,"e":{"uk":"Виїзд на смугу зустрічного руху можливий лише для обгону, об'їзду перешкоди або зупинки чи стоянки біля лівого краю в населених пунктах у дозволених випадках. Зустрічні водії мають перевагу.","ru":"Выезд на полосу встречного движения возможен только для обгона, объезда препятствия или остановки либо стоянки у левого края в населённых пунктах в разрешённых случаях. Встречные водители имеют преимущество."},"ref":["11.3"],"id":"q085ad07c4"},{"t":"s12","q":{"uk":"З якою максимальною швидкістю дозволено рух легкового автомобіля в населеному пункті, якщо знаки не встановлюють інших обмежень?","ru":"С какой максимальной скоростью разрешено движение легкового автомобиля в населённом пункте, если знаки не устанавливают иных ограничений?"},"a":[{"uk":"40 км/год","ru":"40 км/ч"},{"uk":"50 км/год","ru":"50 км/ч"},{"uk":"60 км/год","ru":"60 км/ч"},{"uk":"70 км/год","ru":"70 км/ч"}],"c":1,"e":{"uk":"У населених пунктах рух транспортних засобів дозволено зі швидкістю не більше 50 км/год.","ru":"В населённых пунктах движение транспортных средств разрешено со скоростью не более 50 км/ч."},"ref":["12.4"],"id":"q7777014f1"},{"t":"s12","q":{"uk":"Яка максимальна швидкість у житловій та пішохідній зоні?","ru":"Какая максимальная скорость в жилой и пешеходной зоне?"},"a":[{"uk":"20 км/год","ru":"20 км/ч"},{"uk":"10 км/год","ru":"10 км/ч"},{"uk":"30 км/год","ru":"30 км/ч"},{"uk":"50 км/год","ru":"50 км/ч"}],"img":{"sign":"5.34"},"c":0,"e":{"uk":"У житлових і пішохідних зонах швидкість не повинна перевищувати 20 км/год.","ru":"В жилых и пешеходных зонах скорость не должна превышать 20 км/ч."},"ref":["12.5"],"id":"qd625e7bed"},{"t":"s12","q":{"uk":"З якою максимальною швидкістю може рухатися легковий автомобіль поза населеним пунктом на звичайній дорозі без розділювальної смуги? Стаж водія — понад 2 роки.","ru":"С какой максимальной скоростью может двигаться легковой автомобиль вне населённого пункта на обычной дороге без разделительной полосы? Стаж водителя — более 2 лет."},"a":[{"uk":"70 км/год","ru":"70 км/ч"},{"uk":"90 км/год","ru":"90 км/ч"},{"uk":"110 км/год","ru":"110 км/ч"},{"uk":"130 км/год","ru":"130 км/ч"}],"c":1,"e":{"uk":"Поза населеними пунктами: на автомагістралі ({s:5.1}) — до 130 км/год, на дорозі з розділювальною смугою — до 110 км/год, на інших дорогах — до 90 км/год.","ru":"Вне населённых пунктов: на автомагистрали ({s:5.1}) — до 130 км/ч, на дороге с разделительной полосой — до 110 км/ч, на остальных дорогах — до 90 км/ч."},"ref":["12.6"],"id":"qf4e283c2d"},{"t":"s12","q":{"uk":"Яка максимальна швидкість легкового автомобіля на автомагістралі?","ru":"Какая максимальная скорость легкового автомобиля на автомагистрали?"},"a":[{"uk":"110 км/год","ru":"110 км/ч"},{"uk":"120 км/год","ru":"120 км/ч"},{"uk":"130 км/год","ru":"130 км/ч"},{"uk":"150 км/год","ru":"150 км/ч"}],"img":{"sign":"5.1"},"c":2,"e":{"uk":"На автомобільній дорозі, позначеній знаком {s:5.1} «Автомагістраль», — не більше 130 км/год (для водіїв зі стажем до 2 років — не більше 70 км/год).","ru":"На автомобильной дороге, обозначенной знаком {s:5.1} «Автомагистраль», — не более 130 км/ч (для водителей со стажем до 2 лет — не более 70 км/ч)."},"ref":["12.6"],"id":"q07377be82"},{"t":"s12","q":{"uk":"Яка максимальна швидкість легкового автомобіля поза населеним пунктом на дорозі з окремими проїзними частинами, розділеними розділювальною смугою?","ru":"Какая максимальная скорость легкового автомобиля вне населённого пункта на дороге с отдельными проезжими частями, разделёнными разделительной полосой?"},"a":[{"uk":"90 км/год","ru":"90 км/ч"},{"uk":"110 км/год","ru":"110 км/ч"},{"uk":"130 км/год","ru":"130 км/ч"}],"c":1,"e":{"uk":"На дорозі з окремими проїзними частинами, відокремленими розділювальною смугою, дозволено до 110 км/год.","ru":"На дороге с отдельными проезжими частями, отделёнными разделительной полосой, разрешено до 110 км/ч."},"ref":["12.6"],"id":"q414b9311c"},{"t":"s12","q":{"uk":"З якою максимальною швидкістю поза населеним пунктом може рухатися водій зі стажем менше 2 років?","ru":"С какой максимальной скоростью вне населённого пункта может двигаться водитель со стажем менее 2 лет?"},"a":[{"uk":"50 км/год","ru":"50 км/ч"},{"uk":"60 км/год","ru":"60 км/ч"},{"uk":"70 км/год","ru":"70 км/ч"},{"uk":"90 км/год","ru":"90 км/ч"}],"c":2,"e":{"uk":"Транспортним засобам, якими керують водії зі стажем до 2 років, поза населеними пунктами дозволено не більше 70 км/год на будь-якій дорозі.","ru":"Транспортным средствам, которыми управляют водители со стажем до 2 лет, вне населённых пунктов разрешено не более 70 км/ч на любой дороге."},"ref":["12.6"],"id":"qf4f6ec38a"},{"t":"s12","q":{"uk":"Яка максимальна швидкість легкового автомобіля з причепом поза населеним пунктом?","ru":"Какая максимальная скорость легкового автомобиля с прицепом вне населённого пункта?"},"a":[{"uk":"80 км/год","ru":"80 км/ч"},{"uk":"70 км/год","ru":"70 км/ч"},{"uk":"90 км/год","ru":"90 км/ч"}],"c":0,"e":{"uk":"Легковим автомобілям з причепом, мотоциклам і автобусам з організованими групами дітей поза населеними пунктами дозволено не більше 80 км/год.","ru":"Легковым автомобилям с прицепом, мотоциклам и автобусам с организованными группами детей вне населённых пунктов разрешено не более 80 км/ч."},"ref":["12.6"],"id":"q84772d6d8"},{"t":"s12","q":{"uk":"Яка максимальна швидкість під час буксирування?","ru":"Какая максимальная скорость при буксировке?"},"a":[{"uk":"40 км/год","ru":"40 км/ч"},{"uk":"50 км/год","ru":"50 км/ч"},{"uk":"60 км/год","ru":"60 км/ч"},{"uk":"70 км/год","ru":"70 км/ч"}],"c":1,"e":{"uk":"Під час буксирування швидкість не повинна перевищувати 50 км/год.","ru":"При буксировке скорость не должна превышать 50 км/ч."},"ref":["12.7"],"id":"q0b6307c33"},{"t":"s12","q":{"uk":"Як вибирати швидкість у темну пору доби та за недостатньої видимості?","ru":"Как выбирать скорость в тёмное время суток и при недостаточной видимости?"},"a":[{"uk":"Не більше 40 км/год","ru":"Не более 40 км/ч"},{"uk":"Так, щоб можна було зупинитися в межах видимості дороги","ru":"Так, чтобы можно было остановиться в пределах видимости дороги"},{"uk":"На 20 км/год менше від дозволеної","ru":"На 20 км/ч меньше разрешённой"}],"c":1,"e":{"uk":"У темряві та за недостатньої видимості швидкість має бути такою, щоб водій міг зупинити транспортний засіб у межах видимості дороги.","ru":"В темноте и при недостаточной видимости скорость должна быть такой, чтобы водитель мог остановить транспортное средство в пределах видимости дороги."},"ref":["12.2"],"id":"qd5edef0a6"},{"t":"s12","q":{"uk":"Водій помітив перешкоду на своїй смузі. Що він зобов'язаний зробити?","ru":"Водитель заметил препятствие на своей полосе. Что он обязан сделать?"},"a":[{"uk":"Подати звуковий сигнал і продовжувати рух","ru":"Подать звуковой сигнал и продолжать движение"},{"uk":"Негайно знизити швидкість аж до зупинки або безпечно об'їхати перешкоду","ru":"Немедленно снизить скорость вплоть до остановки или безопасно объехать препятствие"},{"uk":"Обов'язково перестроїтися на іншу смугу","ru":"Обязательно перестроиться на другую полосу"}],"c":1,"e":{"uk":"Виявивши небезпеку чи перешкоду, водій негайно вживає заходів для зменшення швидкості аж до зупинки або для безпечного для інших об'їзду перешкоди.","ru":"Обнаружив опасность или препятствие, водитель немедленно принимает меры для снижения скорости вплоть до остановки или для безопасного для других объезда препятствия."},"ref":["12.3"],"id":"q8b02e87d5"},{"t":"s12","q":{"uk":"Коли дозволено різко гальмувати?","ru":"Когда разрешено резко тормозить?"},"a":[{"uk":"Коли за вами немає інших транспортних засобів","ru":"Когда за вами нет других транспортных средств"},{"uk":"Лише коли без цього неможливо запобігти ДТП","ru":"Только когда без этого невозможно предотвратить ДТП"},{"uk":"Перед кожним пішохідним переходом","ru":"Перед каждым пешеходным переходом"}],"c":1,"e":{"uk":"Водієві заборонено різко гальмувати, крім випадків, коли без цього неможливо запобігти дорожньо-транспортній пригоді.","ru":"Водителю запрещено резко тормозить, кроме случаев, когда без этого невозможно предотвратить дорожно-транспортное происшествие."},"ref":["12.9"],"id":"q4b7343641"},{"t":"s12","q":{"uk":"Ви проїжджаєте населений пункт, позначений цим знаком (синій фон). З якою швидкістю можна рухатися легковим автомобілем?","ru":"Вы проезжаете населённый пункт, обозначенный этим знаком (синий фон). С какой скоростью можно двигаться на легковом автомобиле?"},"a":[{"uk":"Не більше 50 км/год, як у будь-якому населеному пункті","ru":"Не более 50 км/ч, как в любом населённом пункте"},{"uk":"Як поза населеним пунктом (на звичайній дорозі — до 90 км/год)","ru":"Как вне населённого пункта (на обычной дороге — до 90 км/ч)"},{"uk":"Не більше 60 км/год","ru":"Не более 60 км/ч"}],"img":{"sign":"5.51"},"c":1,"e":{"uk":"На дорогах, що проходять через населені пункти, позначені знаком {s:5.51}, діють обмеження швидкості як поза населеними пунктами.","ru":"На дорогах, проходящих через населённые пункты, обозначенные знаком {s:5.51}, действуют ограничения скорости как вне населённых пунктов."},"ref":["12.6"],"id":"qa8427bd4e"},{"t":"s12","q":{"uk":"Що водієві заборонено робити зі швидкістю?","ru":"Что водителю запрещено делать со скоростью?"},"a":[{"uk":"Рухатися повільніше за потік","ru":"Двигаться медленнее потока"},{"uk":"Без потреби рухатися з дуже малою швидкістю, заважаючи іншим","ru":"Без необходимости двигаться с очень малой скоростью, мешая другим"},{"uk":"Рухатися з максимально дозволеною швидкістю","ru":"Двигаться с максимально разрешённой скоростью"}],"c":1,"e":{"uk":"Водієві заборонено перешкоджати іншим транспортним засобам, рухаючись без потреби з дуже малою швидкістю, а також перевищувати максимальну швидкість, визначену технічною характеристикою транспортного засобу.","ru":"Водителю запрещено мешать другим транспортным средствам, двигаясь без необходимости с очень малой скоростью, а также превышать максимальную скорость, определённую технической характеристикой транспортного средства."},"ref":["12.9"],"id":"q0c8ecfd24"},{"t":"s13","q":{"uk":"Зустрічний роз'їзд утруднений, на вашій смузі стоїть перешкода. Хто повинен дати дорогу?","ru":"Встречный разъезд затруднён, на вашей полосе стоит препятствие. Кто должен уступить дорогу?"},"a":[{"uk":"Ви, бо перешкода на вашій смузі","ru":"Вы, так как препятствие на вашей полосе"},{"uk":"Зустрічний водій","ru":"Встречный водитель"},{"uk":"Той, хто рухається швидше","ru":"Тот, кто движется быстрее"}],"c":0,"e":{"uk":"Якщо зустрічний роз'їзд утруднений, дорогу дає водій, на смузі якого є перешкода або габарити транспортного засобу якого заважають зустрічному руху.","ru":"Если встречный разъезд затруднён, дорогу уступает водитель, на полосе которого есть препятствие или габариты транспортного средства которого мешают встречному движению."},"ref":["13.4"],"id":"q2fa7201c2"},{"t":"s13","q":{"uk":"На крутому спуску, позначеному цим знаком, зустрічний роз'їзд утруднений через перешкоду. Хто має дати дорогу?","ru":"На крутом спуске, обозначенном этим знаком, встречный разъезд затруднён из-за препятствия. Кто должен уступить дорогу?"},"a":[{"uk":"Водій, який рухається на підйом","ru":"Водитель, движущийся на подъём"},{"uk":"Водій, який рухається на спуск","ru":"Водитель, движущийся на спуск"},{"uk":"Той, на чиїй смузі перешкода, навіть якщо він їде вгору","ru":"Тот, на чьей полосе препятствие, даже если он едет вверх"}],"img":{"sign":"1.7"},"c":1,"e":{"uk":"На ділянках, позначених знаками {s:1.6} і {s:1.7}, за наявності перешкоди дорогу дає водій, що рухається на спуск: на підйомі важче рушити з місця.","ru":"На участках, обозначенных знаками {s:1.6} и {s:1.7}, при наличии препятствия дорогу уступает водитель, движущийся на спуск: на подъёме труднее тронуться с места."},"ref":["13.4"],"id":"q07aa54599"},{"t":"s13","q":{"uk":"Яку дистанцію мають тримати поза населеним пунктом транспортні засоби, швидкість яких не перевищує 40 км/год?","ru":"Какую дистанцию должны соблюдать вне населённого пункта транспортные средства, скорость которых не превышает 40 км/ч?"},"a":[{"uk":"Не менше 50 м","ru":"Не менее 50 м"},{"uk":"Таку, щоб ті, хто обганяє, могли безперешкодно повернутися на свою смугу","ru":"Такую, чтобы обгоняющие могли беспрепятственно вернуться на свою полосу"},{"uk":"Не менше 100 м","ru":"Не менее 100 м"}],"c":1,"e":{"uk":"Тихохідні транспортні засоби (до 40 км/год) поза населеними пунктами тримають таку дистанцію, щоб автомобілі, які їх обганяють, могли безперешкодно повернутися на свою смугу. Вимога не діє, якщо тихохідний водій сам подає сигнал про обгін чи об'їзд.","ru":"Тихоходные транспортные средства (до 40 км/ч) вне населённых пунктов соблюдают такую дистанцию, чтобы обгоняющие их автомобили могли беспрепятственно вернуться на свою полосу. Требование не действует, если водитель тихоходного средства сам подаёт сигнал об обгоне или объезде."},"ref":["13.2"],"id":"q9c4a2e6ab"},{"t":"s13","q":{"uk":"Яку дистанцію вважають безпечною?","ru":"Какую дистанцию считают безопасной?"},"a":[{"uk":"Не менше 10 м за будь-якої швидкості","ru":"Не менее 10 м при любой скорости"},{"uk":"Таку, за якої в разі раптового гальмування переднього автомобіля можна уникнути зіткнення без маневру","ru":"Такую, при которой в случае внезапного торможения переднего автомобиля можно избежать столкновения без манёвра"},{"uk":"Рівну половині показника спідометра в метрах","ru":"Равную половине показания спидометра в метрах"}],"c":1,"e":{"uk":"Безпечна дистанція — відстань до транспортного засобу попереду, яка в разі його раптового гальмування дає змогу уникнути зіткнення без будь-якого маневру. Її вибирають з урахуванням швидкості, дорожньої обстановки, вантажу і стану автомобіля.","ru":"Безопасная дистанция — расстояние до транспортного средства впереди, которое при его внезапном торможении позволяет избежать столкновения без какого-либо манёвра. Её выбирают с учётом скорости, дорожной обстановки, груза и состояния автомобиля."},"ref":["13.1","1.10"],"id":"q21e6491b1"},{"t":"s14","q":{"uk":"Чи дозволено обгін на перехресті?","ru":"Разрешён ли обгон на перекрёстке?"},"a":[{"uk":"Так, на нерегульованому перехресті","ru":"Да, на нерегулируемом перекрёстке"},{"uk":"Так, якщо рухаєтеся головною дорогою","ru":"Да, если движетесь по главной дороге"},{"uk":"Ні, на перехресті обгін заборонено","ru":"Нет, на перекрёстке обгон запрещён"}],"c":2,"e":{"uk":"Обгін заборонено на перехресті, на залізничних переїздах і ближче 100 м перед ними, перед пішохідними переходами, у тунелях, на мостах, у кінці підйому та на інших ділянках з обмеженою оглядовістю.","ru":"Обгон запрещён на перекрёстке, на железнодорожных переездах и ближе 100 м перед ними, перед пешеходными переходами, в тоннелях, на мостах, в конце подъёма и на других участках с ограниченной обзорностью."},"ref":["14.6"],"id":"qa9b5c7264"},{"t":"s14","q":{"uk":"На якій відстані перед залізничним переїздом заборонено обгін?","ru":"На каком расстоянии перед железнодорожным переездом запрещён обгон?"},"a":[{"uk":"Ближче 50 м","ru":"Ближе 50 м"},{"uk":"Ближче 100 м","ru":"Ближе 100 м"},{"uk":"Ближче 150 м","ru":"Ближе 150 м"}],"c":1,"e":{"uk":"Обгін заборонено на залізничних переїздах і ближче ніж за 100 м перед ними.","ru":"Обгон запрещён на железнодорожных переездах и ближе чем за 100 м перед ними."},"ref":["14.6"],"id":"q47179a89d"},{"t":"s14","q":{"uk":"Ближче якої відстані до пішохідного переходу в населеному пункті заборонено обгін?","ru":"Ближе какого расстояния до пешеходного перехода в населённом пункте запрещён обгон?"},"a":[{"uk":"50 м","ru":"50 м"},{"uk":"10 м","ru":"10 м"},{"uk":"100 м","ru":"100 м"}],"c":0,"e":{"uk":"Обгін заборонено ближче 50 м перед пішохідним переходом у населеному пункті та ближче 100 м — поза населеним пунктом.","ru":"Обгон запрещён ближе 50 м перед пешеходным переходом в населённом пункте и ближе 100 м — вне населённого пункта."},"ref":["14.6"],"id":"q80283c964"},{"t":"s14","q":{"uk":"Водій 1 хоче обігнати автомобіль 2, який уже обганяє автомобіль 3. Чи дозволено це?","ru":"Водитель 1 хочет обогнать автомобиль 2, который уже обгоняет автомобиль 3. Разрешено ли это?"},"a":[{"uk":"Так, якщо зустрічна смуга вільна","ru":"Да, если встречная полоса свободна"},{"uk":"Ні, обганяти транспортний засіб, що сам виконує обгін, заборонено","ru":"Нет, обгонять транспортное средство, которое само выполняет обгон, запрещено"},{"uk":"Так, якщо автомобіль 2 рухається повільно","ru":"Да, если автомобиль 2 движется медленно"}],"img":{"scene":{"road":"straight","lanes":1,"center":"dashed","cars":[{"x":245,"dir":"E","lane":0,"label":"3","color":"green","type":"truck"},{"x":160,"dir":"E","lane":0,"move":"overtake","label":"2","color":"blue"},{"x":60,"dir":"E","lane":0,"move":"overtake","label":"1","color":"red","me":true}]}},"c":1,"e":{"uk":"Обгін транспортного засобу, який сам здійснює обгін або об'їзд, заборонено. Крім того, перед обгоном треба переконатися, що ніхто попереду не почав обгону і зустрічна смуга вільна.","ru":"Обгон транспортного средства, которое само выполняет обгон или объезд, запрещён. Кроме того, перед обгоном нужно убедиться, что никто впереди не начал обгона и встречная полоса свободна."},"ref":["14.6","14.2"],"id":"q64a839530"},{"t":"s14","q":{"uk":"Чи можна обганяти на дорозі, що має дві смуги для руху в одному напрямку?","ru":"Можно ли обгонять на дороге, имеющей две полосы для движения в одном направлении?"},"a":[{"uk":"Так, якщо немає суцільної розмітки","ru":"Да, если нет сплошной разметки"},{"uk":"Ні, обгін на таких дорогах заборонено","ru":"Нет, обгон на таких дорогах запрещён"},{"uk":"Так, лише поза населеним пунктом","ru":"Да, только вне населённого пункта"}],"c":1,"e":{"uk":"На дорогах з двома і більше смугами в одному напрямку обгін (з виїздом на зустрічну смугу) заборонено. Випереджати можна сусідньою смугою свого напрямку.","ru":"На дорогах с двумя и более полосами в одном направлении обгон (с выездом на встречную полосу) запрещён. Опережать можно по соседней полосе своего направления."},"ref":["14.6","11.4"],"id":"qa101f1d5c"},{"t":"s14","q":{"uk":"Вас обганяють. Що вам заборонено?","ru":"Вас обгоняют. Что вам запрещено?"},"a":[{"uk":"Перешкоджати обгону, підвищуючи швидкість або іншими діями","ru":"Препятствовать обгону, повышая скорость или иными действиями"},{"uk":"Знижувати швидкість","ru":"Снижать скорость"},{"uk":"Рухатися ближче до правого краю","ru":"Двигаться ближе к правому краю"}],"c":0,"e":{"uk":"Водієві транспортного засобу, якого обганяють, заборонено перешкоджати обгону підвищенням швидкості або іншими діями.","ru":"Водителю обгоняемого транспортного средства запрещено препятствовать обгону повышением скорости или иными действиями."},"ref":["14.3"],"id":"q7819aaf94"},{"t":"s14","q":{"uk":"У чому має переконатися водій перед початком обгону?","ru":"В чём должен убедиться водитель перед началом обгона?"},"a":[{"uk":"Що ніхто позаду не почав обгону","ru":"Что никто сзади не начал обгона"},{"uk":"Що водій попереду не подав сигналу повороту ліворуч","ru":"Что водитель впереди не подал сигнала поворота налево"},{"uk":"Що зустрічна смуга вільна на достатній відстані і він зможе повернутися на свою смугу","ru":"Что встречная полоса свободна на достаточном расстоянии и он сможет вернуться на свою полосу"},{"uk":"У всьому переліченому","ru":"Во всём перечисленном"}],"c":3,"e":{"uk":"Перед обгоном водій переконується, що ніхто позаду не почав обгону, водій попереду не сигналить про поворот ліворуч, зустрічна смуга вільна на достатній відстані і він зможе повернутися, не заважаючи тому, кого обганяє.","ru":"Перед обгоном водитель убеждается, что никто сзади не начал обгона, водитель впереди не сигналит о повороте налево, встречная полоса свободна на достаточном расстоянии и он сможет вернуться, не мешая обгоняемому."},"ref":["14.2"],"id":"q707903757"},{"t":"s14","q":{"uk":"Позаду колони автомобілів рухається автомобіль з увімкненим синім проблисковим маячком. Чи можна обганяти цю колону?","ru":"Позади колонны автомобилей движется автомобиль с включённым синим проблесковым маячком. Можно ли обгонять эту колонну?"},"a":[{"uk":"Так, якщо зустрічна смуга вільна","ru":"Да, если встречная полоса свободна"},{"uk":"Ні, заборонено","ru":"Нет, запрещено"},{"uk":"Так, але лише з дозволу поліцейського","ru":"Да, но только с разрешения полицейского"}],"c":1,"e":{"uk":"Заборонено обганяти колону транспортних засобів, позаду якої рухається транспортний засіб з увімкненим проблисковим маячком (крім оранжевого).","ru":"Запрещено обгонять колонну транспортных средств, позади которой движется транспортное средство с включённым проблесковым маячком (кроме оранжевого)."},"ref":["14.6"],"id":"qd403f7d74"},{"t":"s14","q":{"uk":"Поза населеним пунктом обігнати тихохідну сільгосптехніку шириною понад 2,6 м неможливо через дорожню обстановку. Що повинен зробити її водій?","ru":"Вне населённого пункта обогнать тихоходную сельхозтехнику шириной более 2,6 м невозможно из-за дорожной обстановки. Что должен сделать её водитель?"},"a":[{"uk":"Збільшити швидкість","ru":"Увеличить скорость"},{"uk":"Рухатися якомога правіше, а за потреби зупинитися на узбіччі й пропустити транспорт позаду","ru":"Двигаться как можно правее, а при необходимости остановиться на обочине и пропустить транспорт сзади"},{"uk":"Нічого, це проблема тих, хто позаду","ru":"Ничего, это проблема тех, кто сзади"}],"c":1,"e":{"uk":"Водій тихохідного, великогабаритного транспортного засобу або сільгосптехніки шириною понад 2,6 м, якщо обгін неможливий, рухається якомога правіше, а за потреби зупиняється на узбіччі, щоб пропустити транспорт.","ru":"Водитель тихоходного, крупногабаритного транспортного средства или сельхозтехники шириной более 2,6 м, если обгон невозможен, движется как можно правее, а при необходимости останавливается на обочине, чтобы пропустить транспорт."},"ref":["14.4"],"id":"qc32529dd0"},{"t":"s14","q":{"uk":"Знак 3.25 «Обгін заборонено». Кого все ж можна обганяти в зоні його дії?","ru":"Знак 3.25 «Обгон запрещён». Кого всё же можно обгонять в зоне его действия?"},"a":[{"uk":"Нікого","ru":"Никого"},{"uk":"Поодинокі транспортні засоби, що рухаються зі швидкістю менше 30 км/год","ru":"Одиночные транспортные средства, движущиеся со скоростью менее 30 км/ч"},{"uk":"Будь-які транспортні засоби, якщо зустрічна смуга вільна","ru":"Любые транспортные средства, если встречная полоса свободна"}],"img":{"sign":"3.25"},"c":1,"e":{"uk":"Знак {s:3.25} забороняє обгін усіх транспортних засобів, крім поодиноких, що рухаються зі швидкістю менше 30 км/год.","ru":"Знак {s:3.25} запрещает обгон всех транспортных средств, кроме одиночных, движущихся со скоростью менее 30 км/ч."},"ref":["33.3"],"id":"qdac9640a9"},{"t":"s14","q":{"uk":"Чи можна обганяти в кінці підйому або на мосту?","ru":"Можно ли обгонять в конце подъёма или на мосту?"},"a":[{"uk":"Ні","ru":"Нет"},{"uk":"Так, якщо немає знаків, що забороняють обгін","ru":"Да, если нет знаков, запрещающих обгон"},{"uk":"На мосту можна, у кінці підйому — ні","ru":"На мосту можно, в конце подъёма — нет"}],"c":0,"e":{"uk":"Обгін заборонено в кінці підйому, на мостах, естакадах, шляхопроводах, крутих поворотах і на ділянках з обмеженою оглядовістю чи за недостатньої видимості.","ru":"Обгон запрещён в конце подъёма, на мостах, эстакадах, путепроводах, крутых поворотах и на участках с ограниченной обзорностью или при недостаточной видимости."},"ref":["14.6"],"id":"q5efe35744"},{"t":"s15","q":{"uk":"Чим зупинка відрізняється від стоянки?","ru":"Чем остановка отличается от стоянки?"},"a":[{"uk":"Зупинка — припинення руху до 5 хвилин (або довше для посадки чи вантаження); стоянка — понад 5 хвилин з інших причин","ru":"Остановка — прекращение движения до 5 минут (или дольше для посадки или погрузки); стоянка — более 5 минут по другим причинам"},{"uk":"Зупинка — до 10 хвилин, стоянка — понад 10 хвилин","ru":"Остановка — до 10 минут, стоянка — более 10 минут"},{"uk":"Під час зупинки водій не виходить з автомобіля","ru":"При остановке водитель не выходит из автомобиля"}],"c":0,"e":{"uk":"Зупинка — припинення руху на час до 5 хвилин або більше, якщо це потрібно для посадки (висадки) пасажирів, вантаження чи виконання вимог Правил. Стоянка — понад 5 хвилин з інших причин.","ru":"Остановка — прекращение движения на время до 5 минут или более, если это нужно для посадки (высадки) пассажиров, погрузки или выполнения требований Правил. Стоянка — более 5 минут по другим причинам."},"ref":["1.10"],"id":"q026d68119"},{"t":"s15","q":{"uk":"Ближче якої відстані до пішохідного переходу заборонено зупинку?","ru":"Ближе какого расстояния до пешеходного перехода запрещена остановка?"},"a":[{"uk":"5 м","ru":"5 м"},{"uk":"10 м","ru":"10 м"},{"uk":"15 м","ru":"15 м"},{"uk":"30 м","ru":"30 м"}],"c":1,"e":{"uk":"Зупинку заборонено на пішохідних переходах і ближче 10 м від них з обох боків, крім зупинки для надання переваги в русі.","ru":"Остановка запрещена на пешеходных переходах и ближе 10 м от них с обеих сторон, кроме остановки для предоставления преимущества в движении."},"ref":["15.9"],"id":"q4d28eccb0"},{"t":"s15","q":{"uk":"Ближче якої відстані до зупинки маршрутного транспорту заборонено зупиняти автомобіль?","ru":"Ближе какого расстояния к остановке маршрутного транспорта запрещено останавливать автомобиль?"},"a":[{"uk":"10 м","ru":"10 м"},{"uk":"20 м","ru":"20 м"},{"uk":"30 м","ru":"30 м"},{"uk":"50 м","ru":"50 м"}],"c":2,"e":{"uk":"Зупинку заборонено ближче 30 м від посадкових майданчиків маршрутного транспорту, а якщо їх немає — ближче 30 м від знака зупинки з обох боків.","ru":"Остановка запрещена ближе 30 м от посадочных площадок маршрутного транспорта, а если их нет — ближе 30 м от знака остановки с обеих сторон."},"ref":["15.9"],"id":"qd09116827"},{"t":"s15","q":{"uk":"Чи можна зупинитися на мосту?","ru":"Можно ли остановиться на мосту?"},"a":[{"uk":"Так, біля правого краю","ru":"Да, у правого края"},{"uk":"Ні, зупинку на мостах, естакадах, шляхопроводах, під ними і в тунелях заборонено","ru":"Нет, остановка на мостах, эстакадах, путепроводах, под ними и в тоннелях запрещена"},{"uk":"Так, на час до 5 хвилин","ru":"Да, на время до 5 минут"}],"c":1,"e":{"uk":"Зупинка заборонена на естакадах, мостах, шляхопроводах і під ними, а також у тунелях.","ru":"Остановка запрещена на эстакадах, мостах, путепроводах и под ними, а также в тоннелях."},"ref":["15.9"],"id":"q0b93c5b86"},{"t":"s15","q":{"uk":"Яку найменшу відстань має бути між автомобілем, що зупинився, і суцільною лінією розмітки?","ru":"Какое наименьшее расстояние должно быть между остановившимся автомобилем и сплошной линией разметки?"},"a":[{"uk":"3 м","ru":"3 м"},{"uk":"1 м","ru":"1 м"},{"uk":"2 м","ru":"2 м"},{"uk":"5 м","ru":"5 м"}],"c":0,"e":{"uk":"Зупинку заборонено там, де між суцільною лінією розмітки, розділювальною смугою або протилежним краєм проїзної частини і транспортним засобом залишається менше 3 м.","ru":"Остановка запрещена там, где между сплошной линией разметки, разделительной полосой или противоположным краем проезжей части и транспортным средством остаётся менее 3 м."},"ref":["15.9"],"id":"qe621244cf"},{"t":"s15","q":{"uk":"На якій відстані від залізничного переїзду заборонено стоянку?","ru":"На каком расстоянии от железнодорожного переезда запрещена стоянка?"},"a":[{"uk":"Ближче 10 м","ru":"Ближе 10 м"},{"uk":"Ближче 30 м","ru":"Ближе 30 м"},{"uk":"Ближче 50 м","ru":"Ближе 50 м"},{"uk":"Ближче 100 м","ru":"Ближе 100 м"}],"c":2,"e":{"uk":"Стоянку заборонено ближче 50 м від залізничних переїздів. Зупинку на самому переїзді заборонено.","ru":"Стоянка запрещена ближе 50 м от железнодорожных переездов. Остановка на самом переезде запрещена."},"ref":["15.10"],"id":"q4799d646c"},{"t":"s15","q":{"uk":"За якої умови легковий автомобіль можна поставити на краю тротуару?","ru":"При каком условии легковой автомобиль можно поставить на краю тротуара?"},"a":[{"uk":"Якщо пішоходам залишається щонайменше 1 м","ru":"Если пешеходам остаётся не менее 1 м"},{"uk":"Якщо пішоходам залишається щонайменше 2 м","ru":"Если пешеходам остаётся не менее 2 м"},{"uk":"Ставити на тротуар заборонено завжди","ru":"Ставить на тротуар запрещено всегда"}],"c":1,"e":{"uk":"Легкові автомобілі та мотоцикли можна ставити на краю тротуару, якщо для руху пішоходів залишається щонайменше 2 м (і якщо це не заборонено знаками).","ru":"Легковые автомобили и мотоциклы можно ставить на краю тротуара, если для движения пешеходов остаётся не менее 2 м (и если это не запрещено знаками)."},"ref":["15.10"],"id":"q7d89f6da3"},{"t":"s15","q":{"uk":"Де в населеному пункті можна зупинитися на лівому боці дороги?","ru":"Где в населённом пункте можно остановиться на левой стороне дороги?"},"a":[{"uk":"На дорозі з однією смугою в кожному напрямку без трамвайних колій посередині і без розмітки 1.1, а також на дорозі з одностороннім рухом","ru":"На дороге с одной полосой в каждом направлении без трамвайных путей посередине и без разметки 1.1, а также на дороге с односторонним движением"},{"uk":"На будь-якій дорозі, якщо немає знаків заборони","ru":"На любой дороге, если нет запрещающих знаков"},{"uk":"Лише на дорозі з двома смугами в кожному напрямку","ru":"Только на дороге с двумя полосами в каждом направлении"}],"c":0,"e":{"uk":"У населених пунктах зупинку і стоянку зліва дозволено на дорогах з однією смугою в кожному напрямку (без трамвая посередині і без розмітки {m:1.1}), а також на дорогах з одностороннім рухом. Біля бульвару чи розділювальної смуги зупинятися не можна.","ru":"В населённых пунктах остановка и стоянка слева разрешены на дорогах с одной полосой в каждом направлении (без трамвая посередине и без разметки {m:1.1}), а также на дорогах с односторонним движением. У бульвара или разделительной полосы останавливаться нельзя."},"ref":["15.3"],"id":"q033551304"},{"t":"s15","q":{"uk":"Як поставити автомобіль під кутом до тротуару на рівній дорозі?","ru":"Как поставить автомобиль под углом к тротуару на ровной дороге?"},"a":[{"uk":"Лише передньою частиною до тротуару","ru":"Только передней частью к тротуару"},{"uk":"Лише задньою частиною до тротуару","ru":"Только задней частью к тротуару"},{"uk":"Будь-якою частиною","ru":"Любой частью"}],"c":0,"e":{"uk":"Біля тротуарів під кутом ставлять лише передньою частиною, а на підйомах — тільки задньою, щоб автомобіль не міг самовільно скотитися.","ru":"У тротуаров под углом ставят только передней частью, а на подъёмах — только задней, чтобы автомобиль не мог самопроизвольно скатиться."},"ref":["15.5"],"id":"qb6ca144a4"},{"t":"s15","q":{"uk":"Чи можна зупинитися ближче 10 м від виїзду з прилеглої території?","ru":"Можно ли остановиться ближе 10 м от выезда с прилегающей территории?"},"a":[{"uk":"Так, якщо водій не виходить з автомобіля","ru":"Да, если водитель не выходит из автомобиля"},{"uk":"Ні","ru":"Нет"},{"uk":"Так, у світлу пору доби","ru":"Да, в светлое время суток"}],"c":1,"e":{"uk":"Зупинку заборонено ближче 10 м від виїздів з прилеглих територій і безпосередньо в місці виїзду.","ru":"Остановка запрещена ближе 10 м от выездов с прилегающих территорий и непосредственно в месте выезда."},"ref":["15.9"],"id":"q9c9a44908"},{"t":"s15","q":{"uk":"Де можна стояти поза населеним пунктом у темну пору доби?","ru":"Где можно стоять вне населённого пункта в тёмное время суток?"},"a":[{"uk":"На узбіччі з увімкненими габаритними вогнями","ru":"На обочине с включёнными габаритными огнями"},{"uk":"Лише на майданчиках для стоянки або за межами дороги","ru":"Только на площадках для стоянки или за пределами дороги"},{"uk":"Біля правого краю проїзної частини з аварійною сигналізацією","ru":"У правого края проезжей части с аварийной сигнализацией"}],"c":1,"e":{"uk":"У темну пору доби і за недостатньої видимості стоянка поза населеними пунктами дозволена лише на майданчиках для стоянки або за межами дороги.","ru":"В тёмное время суток и при недостаточной видимости стоянка вне населённых пунктов разрешена только на площадках для стоянки или за пределами дороги."},"ref":["15.11"],"id":"qd2eb408fe"},{"t":"s15","q":{"uk":"Автомобіль 1 зупинився на перехресті, поруч немає пішохідного переходу. Чи порушив водій Правила?","ru":"Автомобиль 1 остановился на перекрёстке, рядом нет пешеходного перехода. Нарушил ли водитель Правила?"},"a":[{"uk":"Ні, якщо зупинка триває менше 5 хвилин","ru":"Нет, если остановка длится менее 5 минут"},{"uk":"Так. Зупинка на перехресті і ближче 10 м від краю перехрещуваної проїзної частини заборонена (крім надання переваги)","ru":"Да. Остановка на перекрёстке и ближе 10 м от края пересекаемой проезжей части запрещена (кроме предоставления преимущества)"},{"uk":"Ні, якщо він увімкнув аварійну сигналізацію","ru":"Нет, если он включил аварийную сигнализацию"}],"c":1,"e":{"uk":"Зупинку заборонено на перехрестях і ближче 10 м від краю перехрещуваної проїзної частини. Винятки — зупинка для надання переваги та зупинка навпроти бокового проїзду на Т-подібному перехресті з суцільною лінією або розділювальною смугою.","ru":"Остановка запрещена на перекрёстках и ближе 10 м от края пересекаемой проезжей части. Исключения — остановка для предоставления преимущества и остановка напротив бокового проезда на Т-образном перекрёстке со сплошной линией или разделительной полосой."},"ref":["15.9"],"id":"q2b628c82f"},{"t":"s15","q":{"uk":"Чи можна ставити легкові автомобілі на проїзній частині у два ряди?","ru":"Можно ли ставить легковые автомобили на проезжей части в два ряда?"},"a":[{"uk":"Так, на короткий час","ru":"Да, на короткое время"},{"uk":"Ні. У два ряди можна ставити лише велосипеди, мопеди та мотоцикли без бокового причепа","ru":"Нет. В два ряда можно ставить только велосипеды, мопеды и мотоциклы без бокового прицепа"},{"uk":"Так, якщо ширина проїзної частини дозволяє","ru":"Да, если ширина проезжей части позволяет"}],"c":1,"e":{"uk":"Транспортні засоби не можна ставити на проїзній частині у два і більше ряди. Велосипеди, мопеди та мотоцикли без бокового причепа — не більше ніж у два ряди.","ru":"Транспортные средства нельзя ставить на проезжей части в два и более ряда. Велосипеды, мопеды и мотоциклы без бокового прицепа — не более чем в два ряда."},"ref":["15.4"],"id":"q26ef5dc0c"},{"t":"s15","q":{"uk":"Чи можна відчинити двері автомобіля з боку проїзної частини, якщо це заважає іншим?","ru":"Можно ли открыть дверь автомобиля со стороны проезжей части, если это мешает другим?"},"a":[{"uk":"Так, на короткий час","ru":"Да, на короткое время"},{"uk":"Ні, якщо це загрожує безпеці чи створює перешкоди","ru":"Нет, если это угрожает безопасности или создаёт помехи"},{"uk":"Так, якщо автомобіль стоїть на стоянці","ru":"Да, если автомобиль стоит на стоянке"}],"c":1,"e":{"uk":"Заборонено відчиняти двері, залишати їх відчиненими і виходити з автомобіля, якщо це загрожує безпеці або створює перешкоди іншим учасникам руху.","ru":"Запрещено открывать двери, оставлять их открытыми и выходить из автомобиля, если это угрожает безопасности или создаёт помехи другим участникам движения."},"ref":["15.13"],"id":"q2e113f8a7"},{"t":"s16","q":{"uk":"Хто з водіїв першим проїде перехрестя рівнозначних доріг?","ru":"Кто из водителей первым проедет перекрёсток равнозначных дорог?"},"a":[{"uk":"Водій автомобіля 1","ru":"Водитель автомобиля 1"},{"uk":"Водій автомобіля 2","ru":"Водитель автомобиля 2"},{"uk":"Вони роз'їжджаються за взаємною домовленістю","ru":"Они разъезжаются по взаимной договорённости"}],"img":{"scene":{"road":"cross","cars":[{"arm":"S","move":"straight","label":"1","color":"red","me":true},{"arm":"E","move":"straight","label":"2","color":"blue"}]}},"c":1,"e":{"uk":"На перехресті рівнозначних доріг діє правило «перешкода праворуч»: автомобіль 2 наближається праворуч від автомобіля 1, тому водій 1 дає йому дорогу.","ru":"На перекрёстке равнозначных дорог действует правило «помеха справа»: автомобиль 2 приближается справа от автомобиля 1, поэтому водитель 1 уступает ему дорогу."},"ref":["16.12"],"id":"q6ecd3b18e"},{"t":"s16","q":{"uk":"Хто першим проїде перехрестя?","ru":"Кто первым проедет перекрёсток?"},"a":[{"uk":"Автомобіль 2","ru":"Автомобиль 2"},{"uk":"Автомобіль 1","ru":"Автомобиль 1"},{"uk":"Автомобіль 1, бо автомобіль 2 наближається ліворуч","ru":"Автомобиль 1, так как автомобиль 2 приближается слева"}],"img":{"scene":{"road":"cross","cars":[{"arm":"S","move":"straight","label":"1","color":"red","me":true},{"arm":"W","move":"straight","label":"2","color":"blue"}],"signs":[{"arm":"S","code":"2.1"},{"arm":"W","code":"2.3"}]}},"c":0,"e":{"uk":"Автомобіль 1 стоїть перед знаком {s:2.1} «Дати дорогу» — він на другорядній дорозі. Автомобіль 2 рухається головною ({s:2.3}), тому має перевагу незалежно від того, з якого боку наближається.","ru":"Автомобиль 1 стоит перед знаком {s:2.1} «Уступить дорогу» — он на второстепенной дороге. Автомобиль 2 едет по главной ({s:2.3}), поэтому имеет преимущество независимо от того, с какой стороны приближается."},"ref":["16.11"],"id":"qe30de3907"},{"t":"s16","q":{"uk":"Водій автомобіля 1 повертає ліворуч на перехресті рівнозначних доріг. Хто проїде першим?","ru":"Водитель автомобиля 1 поворачивает налево на перекрёстке равнозначных дорог. Кто проедет первым?"},"a":[{"uk":"Автомобіль 1","ru":"Автомобиль 1"},{"uk":"Автомобіль 2","ru":"Автомобиль 2"}],"img":{"scene":{"road":"cross","cars":[{"arm":"S","move":"left","label":"1","color":"red","me":true},{"arm":"N","move":"straight","label":"2","color":"blue"}]}},"c":1,"e":{"uk":"Перед поворотом ліворуч водій зобов'язаний дати дорогу зустрічним транспортним засобам, що рухаються прямо або праворуч.","ru":"Перед поворотом налево водитель обязан уступить дорогу встречным транспортным средствам, движущимся прямо или направо."},"ref":["16.13"],"id":"qcbcf355cd"},{"t":"s16","q":{"uk":"Хто має перевагу на цьому нерегульованому перехресті рівнозначних доріг?","ru":"У кого преимущество на этом нерегулируемом перекрёстке равнозначных дорог?"},"a":[{"uk":"Автомобіль 1, бо трамвай наближається ліворуч","ru":"Автомобиль 1, так как трамвай приближается слева"},{"uk":"Трамвай 2","ru":"Трамвай 2"},{"uk":"Той, хто першим під'їхав до перехрестя","ru":"Тот, кто первым подъехал к перекрёстку"}],"img":{"scene":{"road":"cross","tram":true,"cars":[{"arm":"E","move":"straight","label":"1","color":"red","me":true},{"arm":"S","move":"straight","label":"2","type":"tram"}]}},"c":1,"e":{"uk":"На нерегульованому перехресті рівнозначних доріг трамвай має перевагу перед нерейковими транспортними засобами незалежно від напрямку руху. Правило «перешкода праворуч» тут не застосовується.","ru":"На нерегулируемом перекрёстке равнозначных дорог трамвай имеет преимущество перед нерельсовыми транспортными средствами независимо от направления движения. Правило «помеха справа» здесь не применяется."},"ref":["16.12"],"id":"q22740d9f8"},{"t":"s16","q":{"uk":"Обом водіям горить зелений сигнал. Автомобіль 1 повертає ліворуч. Хто проїде першим?","ru":"Обоим водителям горит зелёный сигнал. Автомобиль 1 поворачивает налево. Кто проедет первым?"},"a":[{"uk":"Автомобіль 1","ru":"Автомобиль 1"},{"uk":"Автомобіль 2","ru":"Автомобиль 2"},{"uk":"Хто першим в'їхав на перехрестя","ru":"Тот, кто первым въехал на перекрёсток"}],"img":{"scene":{"road":"cross","cars":[{"arm":"S","move":"left","label":"1","color":"red","me":true},{"arm":"N","move":"straight","label":"2","color":"green"}],"lights":[{"arm":"S","state":"green"},{"arm":"N","state":"green"}]}},"c":1,"e":{"uk":"Повертаючи ліворуч на зелений сигнал, водій дає дорогу зустрічним транспортним засобам, що рухаються прямо або праворуч, і трамваю попутного напрямку.","ru":"Поворачивая налево на зелёный сигнал, водитель уступает дорогу встречным транспортным средствам, движущимся прямо или направо, и трамваю попутного направления."},"ref":["16.6"],"id":"qc2565fad2"},{"t":"s16","q":{"uk":"Світлофор працює в режимі миготіння жовтого сигналу. Хто проїде перехрестя першим?","ru":"Светофор работает в режиме мигающего жёлтого сигнала. Кто проедет перекрёсток первым?"},"a":[{"uk":"Автомобіль 1","ru":"Автомобиль 1"},{"uk":"Автомобіль 2, бо він праворуч","ru":"Автомобиль 2, так как он справа"}],"img":{"scene":{"road":"cross","cars":[{"arm":"S","move":"straight","label":"1","color":"red","me":true},{"arm":"E","move":"straight","label":"2","color":"blue"}],"lights":[{"arm":"S","state":"flash"},{"arm":"E","state":"flash"}],"signs":[{"arm":"S","code":"2.3"},{"arm":"E","code":"2.1"}]}},"c":0,"e":{"uk":"Миготливий жовтий означає, що перехрестя нерегульоване, тож діють знаки пріоритету. Автомобіль 1 на головній дорозі ({s:2.3}), автомобіль 2 — перед знаком {s:2.1}.","ru":"Мигающий жёлтый означает, что перекрёсток нерегулируемый, поэтому действуют знаки приоритета. Автомобиль 1 на главной дороге ({s:2.3}), автомобиль 2 — перед знаком {s:2.1}."},"ref":["16.1","16.11"],"id":"qa2200bfd6"},{"t":"s16","q":{"uk":"Чи діють знаки пріоритету на перехресті, де рух регулює працюючий світлофор?","ru":"Действуют ли знаки приоритета на перекрёстке, где движение регулирует работающий светофор?"},"a":[{"uk":"Так, вони мають перевагу над світлофором","ru":"Да, они имеют приоритет над светофором"},{"uk":"Діють лише для поворотів ліворуч","ru":"Действуют только для поворотов налево"},{"uk":"Ні, не діють","ru":"Нет, не действуют"}],"c":2,"e":{"uk":"Перехрестя, де черговість визначають світлофор або регулювальник, — регульоване. На ньому знаки пріоритету не діють. Вони потрібні, якщо світлофор вимкнеться або перейде на миготливий жовтий.","ru":"Перекрёсток, где очерёдность определяют светофор или регулировщик, — регулируемый. На нём знаки приоритета не действуют. Они нужны, если светофор выключится или перейдёт на мигающий жёлтый."},"ref":["16.1"],"id":"qd8ed205ae"},{"t":"s16","q":{"uk":"Кому надається перевага на перехресті з круговим рухом, позначеному цим знаком?","ru":"Кому предоставляется преимущество на перекрёстке с круговым движением, обозначенном этим знаком?"},"a":[{"uk":"Транспортним засобам, що в'їжджають на коло","ru":"Транспортным средствам, въезжающим на круг"},{"uk":"Транспортним засобам, які вже рухаються по колу","ru":"Транспортным средствам, которые уже движутся по кругу"},{"uk":"Тим, хто наближається праворуч","ru":"Тем, кто приближается справа"}],"img":{"sign":"4.10"},"c":1,"e":{"uk":"На перехрестях з круговим рухом, позначених знаком {s:4.10}, перевагу мають ті, хто вже рухається по колу. Правило «перешкода праворуч» тут не діє.","ru":"На перекрёстках с круговым движением, обозначенных знаком {s:4.10}, преимущество у тех, кто уже движется по кругу. Правило «помеха справа» здесь не действует."},"ref":["16.12"],"id":"q046aa3b33"},{"t":"s16","q":{"uk":"Головна дорога на перехресті змінює напрямок. Як мають роз'їжджатися між собою водії, що рухаються головною дорогою?","ru":"Главная дорога на перекрёстке меняет направление. Как должны разъезжаться между собой водители, движущиеся по главной дороге?"},"a":[{"uk":"Перевагу має той, хто їде прямо","ru":"Преимущество у того, кто едет прямо"},{"uk":"За правилами проїзду перехресть рівнозначних доріг","ru":"По правилам проезда перекрёстков равнозначных дорог"},{"uk":"Перевагу має той, хто повертає за головною дорогою","ru":"Преимущество у того, кто поворачивает по главной дороге"}],"img":{"signs":["2.3","7.8"]},"c":1,"e":{"uk":"Табличка {s:7.8} показує напрямок головної дороги. Водії на головній дорозі між собою керуються правилами для рівнозначних доріг («перешкода праворуч», поворот ліворуч поступається зустрічним). Так само між собою роз'їжджаються водії на другорядних дорогах.","ru":"Табличка {s:7.8} показывает направление главной дороги. Водители на главной дороге между собой руководствуются правилами для равнозначных дорог («помеха справа», поворот налево уступает встречным). Так же между собой разъезжаются водители на второстепенных дорогах."},"ref":["16.14"],"id":"qa78b2fde3"},{"t":"s16","q":{"uk":"Вночі на засніженій дорозі неможливо визначити, чи є покриття, а знаків пріоритету немає. Як має діяти водій на перехресті?","ru":"Ночью на заснеженной дороге невозможно определить наличие покрытия, а знаков приоритета нет. Как должен действовать водитель на перекрёстке?"},"a":[{"uk":"Вважати, що він на другорядній дорозі","ru":"Считать, что он на второстепенной дороге"},{"uk":"Вважати, що він на головній дорозі","ru":"Считать, что он на главной дороге"},{"uk":"Керуватися правилом «перешкода праворуч»","ru":"Руководствоваться правилом «помеха справа»"}],"c":0,"e":{"uk":"Якщо неможливо визначити наявність покриття (темрява, бруд, сніг), а знаків пріоритету немає, водій повинен вважати, що перебуває на другорядній дорозі, і пропускати всіх.","ru":"Если невозможно определить наличие покрытия (темнота, грязь, снег), а знаков приоритета нет, водитель должен считать, что находится на второстепенной дороге, и пропускать всех."},"ref":["16.15"],"id":"qec01abfe4"},{"t":"s16","q":{"uk":"Горить зелений сигнал, але за перехрестям утворився затор. Що має зробити водій?","ru":"Горит зелёный сигнал, но за перекрёстком образовался затор. Что должен сделать водитель?"},"a":[{"uk":"Виїхати на перехрестя, бо зелений сигнал дозволяє рух","ru":"Выехать на перекрёсток, так как зелёный сигнал разрешает движение"},{"uk":"Не виїжджати на перехрестя, якщо доведеться на ньому зупинитися й заважати іншим","ru":"Не выезжать на перекрёсток, если придётся на нём остановиться и мешать другим"},{"uk":"Виїхати й зупинитися в центрі перехрестя з аварійною сигналізацією","ru":"Выехать и остановиться в центре перекрёстка с аварийной сигнализацией"}],"c":1,"e":{"uk":"Заборонено виїжджати на будь-яке перехрестя, навіть на дозвільний сигнал, якщо через затор доведеться зупинитися на ньому і створити перешкоду іншим транспортним засобам та пішоходам.","ru":"Запрещено выезжать на любой перекрёсток, даже на разрешающий сигнал, если из-за затора придётся остановиться на нём и создать помеху другим транспортным средствам и пешеходам."},"ref":["16.4"],"id":"q0a6d7df88"},{"t":"s16","q":{"uk":"Водій повертає праворуч. Кому він зобов'язаний дати дорогу?","ru":"Водитель поворачивает направо. Кому он обязан уступить дорогу?"},"a":[{"uk":"Нікому, бо перехрестя нерегульоване","ru":"Никому, так как перекрёсток нерегулируемый"},{"uk":"Пішоходу, який переходить проїзну частину, на яку він повертає","ru":"Пешеходу, переходящему проезжую часть, на которую он поворачивает"},{"uk":"Пішоходу — лише якщо є розмітка «зебра»","ru":"Пешеходу — только если есть разметка «зебра»"}],"img":{"scene":{"road":"cross","cars":[{"arm":"S","move":"right","label":"1","color":"red","me":true}],"peds":[{"arm":"E"}]}},"c":1,"e":{"uk":"Повертаючи праворуч або ліворуч, водій дає дорогу пішоходам, які переходять проїзну частину, на яку він повертає, а також велосипедистам, що рухаються прямо в попутному напрямку. На перехресті межі переходу без розмітки визначаються шириною тротуарів чи узбіч.","ru":"Поворачивая направо или налево, водитель уступает дорогу пешеходам, переходящим проезжую часть, на которую он поворачивает, а также велосипедистам, движущимся прямо в попутном направлении. На перекрёстке границы перехода без разметки определяются шириной тротуаров или обочин."},"ref":["16.2"],"id":"q8d6f43406"},{"t":"s16","q":{"uk":"Увімкнувся зелений сигнал. Що повинен зробити водій перед початком руху?","ru":"Включился зелёный сигнал. Что должен сделать водитель перед началом движения?"},"a":[{"uk":"Негайно рушити — він має перевагу","ru":"Немедленно начать движение — у него преимущество"},{"uk":"Дати дорогу транспортним засобам, що завершують проїзд перехрестя, і пішоходам, які закінчують перехід","ru":"Уступить дорогу транспортным средствам, завершающим проезд перекрёстка, и пешеходам, заканчивающим переход"},{"uk":"Подати звуковий сигнал і рушати","ru":"Подать звуковой сигнал и начинать движение"}],"c":1,"e":{"uk":"Дозвільний сигнал не скасовує обов'язку пропустити тих, хто ще завершує рух через перехрестя або перехід.","ru":"Разрешающий сигнал не отменяет обязанности пропустить тех, кто ещё завершает движение через перекрёсток или переход."},"ref":["16.5"],"id":"qcfba1f559"},{"t":"s16","q":{"uk":"Водій 1 повертає праворуч у напрямку зеленої стрілки додаткової секції, коли основний сигнал червоний. Хто проїде першим?","ru":"Водитель 1 поворачивает направо по зелёной стрелке дополнительной секции, когда основной сигнал красный. Кто проедет первым?"},"a":[{"uk":"Автомобіль 1, бо для нього горить стрілка","ru":"Автомобиль 1, так как для него горит стрелка"},{"uk":"Автомобіль 2","ru":"Автомобиль 2"}],"img":{"scene":{"road":"cross","cars":[{"arm":"S","move":"right","label":"1","color":"red","me":true},{"arm":"W","move":"straight","label":"2","color":"blue"}],"lights":[{"arm":"S","state":"red","arrow":"right"},{"arm":"W","state":"green"}]}},"c":1,"e":{"uk":"Рухаючись у напрямку стрілки додаткової секції, увімкненої разом із червоним чи жовтим сигналом, водій дає дорогу транспортним засобам, що рухаються з інших напрямків.","ru":"Двигаясь по стрелке дополнительной секции, включённой вместе с красным или жёлтым сигналом, водитель уступает дорогу транспортным средствам, движущимся с других направлений."},"ref":["16.9"],"id":"q28a75804c"},{"t":"s16","q":{"uk":"Де повинен зупинитися водій, який надає перевагу транспортним засобам на перехрещуваній дорозі, якщо стоп-лінії немає?","ru":"Где должен остановиться водитель, предоставляющий преимущество транспортным средствам на пересекаемой дороге, если стоп-линии нет?"},"a":[{"uk":"Посередині перехрестя","ru":"Посередине перекрёстка"},{"uk":"Біля знака «Дати дорогу», навіть якщо він за 50 м до перехрестя","ru":"У знака «Уступить дорогу», даже если он в 50 м до перекрёстка"},{"uk":"Перед краєм перехрещуваної проїзної частини, не заважаючи пішоходам","ru":"Перед краем пересекаемой проезжей части, не мешая пешеходам"}],"c":2,"e":{"uk":"Водій зупиняється перед розміткою {m:1.12} (стоп-лінія) або {m:1.13}, перед світлофором так, щоб бачити його сигнали. Якщо їх немає — перед краєм перехрещуваної проїзної частини, не створюючи перешкод пішоходам.","ru":"Водитель останавливается перед разметкой {m:1.12} (стоп-линия) или {m:1.13}, перед светофором так, чтобы видеть его сигналы. Если их нет — перед краем пересекаемой проезжей части, не создавая помех пешеходам."},"ref":["16.3"],"id":"q04078e10d"},{"t":"s16","q":{"uk":"Водій виїхав на перехрестя на зелений сигнал. На виїзді з перехрестя для нього горить червоний, стоп-лінії та знака 5.69 немає. Як діяти?","ru":"Водитель выехал на перекрёсток на зелёный сигнал. На выезде с перекрёстка для него горит красный, стоп-линии и знака 5.69 нет. Как поступить?"},"a":[{"uk":"Виїхати з перехрестя в наміченому напрямку","ru":"Выехать с перекрёстка в намеченном направлении"},{"uk":"Зупинитися перед світлофором на виїзді","ru":"Остановиться перед светофором на выезде"},{"uk":"Зупинитися й увімкнути аварійну сигналізацію","ru":"Остановиться и включить аварийную сигнализацию"}],"c":0,"e":{"uk":"Водій, який виїхав на перехрестя на дозвільний сигнал, повинен виїхати в наміченому напрямку незалежно від сигналів світлофора на виїзді. Виняток — коли перед світлофором є стоп-лінія {m:1.12} або знак {s:5.69}.","ru":"Водитель, выехавший на перекрёсток на разрешающий сигнал, должен выехать в намеченном направлении независимо от сигналов светофора на выезде. Исключение — когда перед светофором есть стоп-линия {m:1.12} или знак {s:5.69}."},"ref":["16.8"],"id":"q0792f1411"},{"t":"s16","q":{"uk":"Хто першим проїде перехрестя?","ru":"Кто первым проедет перекрёсток?"},"a":[{"uk":"Автомобіль 1, потім 2 і 3","ru":"Автомобиль 1, затем 2 и 3"},{"uk":"Автомобілі 2 і 3 одночасно, потім автомобіль 1","ru":"Автомобили 2 и 3 одновременно, затем автомобиль 1"},{"uk":"Автомобіль 3, потім 1, потім 2","ru":"Автомобиль 3, затем 1, затем 2"}],"img":{"scene":{"road":"T","cars":[{"arm":"S","move":"left","label":"1","color":"red","me":true},{"arm":"E","move":"straight","label":"2","color":"blue"},{"arm":"W","move":"straight","label":"3","color":"green"}],"signs":[{"arm":"S","code":"2.1"},{"arm":"E","code":"2.3"},{"arm":"W","code":"2.3"}]}},"c":1,"e":{"uk":"Автомобілі 2 і 3 рухаються головною дорогою назустріч один одному прямо — їхні траєкторії не перетинаються. Автомобіль 1 на другорядній дорозі ({s:2.1}) пропускає обох.","ru":"Автомобили 2 и 3 движутся по главной дороге навстречу друг другу прямо — их траектории не пересекаются. Автомобиль 1 на второстепенной дороге ({s:2.1}) пропускает обоих."},"ref":["16.11"],"id":"q3c18c2713"},{"t":"s16","q":{"uk":"Водій 1 повертає праворуч, водій 2 — ліворуч. Перехрестя рівнозначних доріг. Хто проїде першим?","ru":"Водитель 1 поворачивает направо, водитель 2 — налево. Перекрёсток равнозначных дорог. Кто проедет первым?"},"a":[{"uk":"Автомобіль 1","ru":"Автомобиль 1"},{"uk":"Автомобіль 2","ru":"Автомобиль 2"},{"uk":"Одночасно","ru":"Одновременно"}],"img":{"scene":{"road":"cross","cars":[{"arm":"S","move":"right","label":"1","color":"red","me":true},{"arm":"N","move":"left","label":"2","color":"blue"}]}},"c":0,"e":{"uk":"Обидва виїжджають на одну дорогу. Водій 2, повертаючи ліворуч, дає дорогу зустрічному транспорту, що рухається прямо або праворуч, тобто автомобілю 1.","ru":"Оба выезжают на одну дорогу. Водитель 2, поворачивая налево, уступает дорогу встречному транспорту, движущемуся прямо или направо, то есть автомобилю 1."},"ref":["16.13"],"id":"q87a13e0a6"},{"t":"s16","q":{"uk":"У якій послідовності автомобілі проїдуть перехрестя?","ru":"В какой последовательности автомобили проедут перекрёсток?"},"a":[{"uk":"1, 2, 3","ru":"1, 2, 3"},{"uk":"2, 1, 3","ru":"2, 1, 3"},{"uk":"2, 3, 1","ru":"2, 3, 1"},{"uk":"3, 2, 1","ru":"3, 2, 1"}],"img":{"scene":{"road":"cross","cars":[{"arm":"S","move":"left","label":"1","color":"red","me":true},{"arm":"N","move":"straight","label":"2","color":"blue"},{"arm":"E","move":"straight","label":"3","color":"green"}],"signs":[{"arm":"S","code":"2.3"},{"arm":"N","code":"2.3"},{"arm":"E","code":"2.1"}]}},"c":1,"e":{"uk":"Автомобілі 1 і 2 — на головній дорозі, між собою вони роз'їжджаються як на рівнозначній: водій 1, повертаючи ліворуч, пропускає зустрічний автомобіль 2. Автомобіль 3 стоїть перед знаком {s:2.1} і пропускає обох.","ru":"Автомобили 1 и 2 — на главной дороге, между собой они разъезжаются как на равнозначной: водитель 1, поворачивая налево, пропускает встречный автомобиль 2. Автомобиль 3 стоит перед знаком {s:2.1} и пропускает обоих."},"ref":["16.11","16.13"],"id":"q25b862bbf"},{"t":"s16","q":{"uk":"Водіям 1 і 2 горить зелений, водію 3 — червоний. Хто проїде першим?","ru":"Водителям 1 и 2 горит зелёный, водителю 3 — красный. Кто проедет первым?"},"a":[{"uk":"Автомобіль 1","ru":"Автомобиль 1"},{"uk":"Автомобіль 2","ru":"Автомобиль 2"},{"uk":"Автомобіль 3, бо він праворуч","ru":"Автомобиль 3, так как он справа"}],"img":{"scene":{"road":"cross","cars":[{"arm":"S","move":"straight","label":"1","color":"red","me":true},{"arm":"N","move":"left","label":"2","color":"blue"},{"arm":"E","move":"straight","label":"3","color":"green"}],"lights":[{"arm":"S","state":"green"},{"arm":"N","state":"green"},{"arm":"E","state":"red"}]}},"c":0,"e":{"uk":"Автомобіль 3 стоїть на червоний. Водій 2 повертає ліворуч на зелений і пропускає зустрічний автомобіль 1, що їде прямо.","ru":"Автомобиль 3 стоит на красный. Водитель 2 поворачивает налево на зелёный и пропускает встречный автомобиль 1, едущий прямо."},"ref":["16.6"],"id":"q7490be4a4"},{"t":"s17","q":{"uk":"Кому, крім маршрутного транспорту, дозволено рухатися смугою, позначеною знаком 5.11?","ru":"Кому, кроме маршрутного транспорта, разрешено двигаться по полосе, обозначенной знаком 5.11?"},"a":[{"uk":"Нікому","ru":"Никому"},{"uk":"Таксі, мотоциклам без бокового причепа, мопедам і велосипедистам","ru":"Такси, мотоциклам без бокового прицепа, мопедам и велосипедистам"},{"uk":"Усім легковим автомобілям","ru":"Всем легковым автомобилям"}],"img":{"sign":"5.11"},"c":1,"e":{"uk":"На смузі для маршрутних транспортних засобів ({s:5.8}, {s:5.11}) заборонено рух і зупинку інших транспортних засобів, крім таксі, мопедів, мотоциклів без бокового причепа та велосипедистів.","ru":"На полосе для маршрутных транспортных средств ({s:5.8}, {s:5.11}) запрещены движение и остановка других транспортных средств, кроме такси, мопедов, мотоциклов без бокового прицепа и велосипедистов."},"ref":["17.1"],"id":"q70dd5452f"},{"t":"s17","q":{"uk":"Смуга для маршрутного транспорту відокремлена переривчастою лінією. Чи можна з неї повернути праворуч на легковому автомобілі?","ru":"Полоса для маршрутного транспорта отделена прерывистой линией. Можно ли с неё повернуть направо на легковом автомобиле?"},"a":[{"uk":"Так","ru":"Да"},{"uk":"Ні, поворот праворуч дозволено лише з сусідньої смуги","ru":"Нет, поворот направо разрешён только с соседней полосы"}],"c":0,"e":{"uk":"Якщо смуга для маршрутних транспортних засобів відокремлена переривчастою лінією, водій, який повертає праворуч, може виконувати поворот із цієї смуги. Так само на неї можна заїжджати під час виїзду на дорогу та для посадки чи висадки пасажирів біля правого краю.","ru":"Если полоса для маршрутных транспортных средств отделена прерывистой линией, водитель, поворачивающий направо, может выполнять поворот с этой полосы. Так же на неё можно заезжать при выезде на дорогу и для посадки или высадки пассажиров у правого края."},"ref":["17.2"],"id":"qb6175032c"},{"t":"s17","q":{"uk":"У населеному пункті автобус починає рух від зупинки в заїзному «кармані». Що має зробити водій легкового автомобіля?","ru":"В населённом пункте автобус начинает движение от остановки в заездном «кармане». Что должен сделать водитель легкового автомобиля?"},"a":[{"uk":"Продовжити рух, бо автобус виїжджає з прилеглої території","ru":"Продолжить движение, так как автобус выезжает с прилегающей территории"},{"uk":"Зменшити швидкість, а за потреби зупинитися, щоб автобус міг рушити","ru":"Снизить скорость, а при необходимости остановиться, чтобы автобус мог начать движение"},{"uk":"Подати звуковий сигнал","ru":"Подать звуковой сигнал"}],"c":1,"e":{"uk":"У населених пунктах водії зобов'язані дати можливість автобусу, мікроавтобусу чи тролейбусу рушити від позначеної зупинки в «кармані»: зменшити швидкість, а за потреби зупинитися.","ru":"В населённых пунктах водители обязаны дать возможность автобусу, микроавтобусу или троллейбусу начать движение от обозначенной остановки в «кармане»: снизить скорость, а при необходимости остановиться."},"ref":["17.4"],"id":"q8a6ecea13"},{"t":"s17","q":{"uk":"Поза перехрестям трамвайна колія перетинає смугу руху автомобілів. Хто має перевагу?","ru":"Вне перекрёстка трамвайные пути пересекают полосу движения автомобилей. У кого преимущество?"},"a":[{"uk":"Трамвай, крім випадків його виїзду з депо","ru":"Трамвай, кроме случаев его выезда из депо"},{"uk":"Автомобіль, що наближається праворуч","ru":"Автомобиль, приближающийся справа"},{"uk":"Той, хто першим під'їхав","ru":"Тот, кто первым подъехал"}],"c":0,"e":{"uk":"Поза перехрестями, де трамвайні колії перетинають смугу нерейкових транспортних засобів, перевагу має трамвай (крім виїзду з депо).","ru":"Вне перекрёстков, где трамвайные пути пересекают полосу нерельсовых транспортных средств, преимущество имеет трамвай (кроме выезда из депо)."},"ref":["17.3"],"id":"qd3bcfd514"},{"t":"s18","q":{"uk":"Водій наближається до нерегульованого пішохідного переходу, на якому є пішохід. Як він повинен діяти?","ru":"Водитель приближается к нерегулируемому пешеходному переходу, на котором есть пешеход. Как он должен действовать?"},"a":[{"uk":"Подати звуковий сигнал і проїхати перед пішоходом","ru":"Подать звуковой сигнал и проехать перед пешеходом"},{"uk":"Зменшити швидкість, а за потреби зупинитися, щоб дати дорогу пішоходу","ru":"Снизить скорость, а при необходимости остановиться, чтобы уступить дорогу пешеходу"},{"uk":"Проїхати, якщо пішохід ще не дійшов до його смуги","ru":"Проехать, если пешеход ещё не дошёл до его полосы"}],"img":{"scene":{"road":"straight","lanes":1,"center":"dashed","zebra":200,"cars":[{"x":90,"dir":"E","lane":0,"move":"straight","label":"1","color":"red","me":true}],"peds":[{"x":200,"y":140}]}},"c":1,"e":{"uk":"Наближаючись до нерегульованого переходу з пішоходами, водій зменшує швидкість, а за потреби зупиняється, щоб дати дорогу пішоходам, яким може бути створено перешкоду чи небезпеку.","ru":"Приближаясь к нерегулируемому переходу с пешеходами, водитель снижает скорость, а при необходимости останавливается, чтобы уступить дорогу пешеходам, которым может быть создана помеха или опасность."},"ref":["18.1"],"id":"q0ced9bd7e"},{"t":"s18","q":{"uk":"Перед нерегульованим пішохідним переходом на сусідній смузі зупинився автомобіль. Що робити водію 1?","ru":"Перед нерегулируемым пешеходным переходом на соседней полосе остановился автомобиль. Что делать водителю 1?"},"a":[{"uk":"Продовжити рух, бо його смуга вільна","ru":"Продолжить движение, так как его полоса свободна"},{"uk":"Зменшити швидкість, а за потреби зупинитися і рушати, лише переконавшись, що на переході немає пішоходів","ru":"Снизить скорость, а при необходимости остановиться и ехать, только убедившись, что на переходе нет пешеходов"},{"uk":"Об'їхати автомобіль 2 і подати звуковий сигнал","ru":"Объехать автомобиль 2 и подать звуковой сигнал"}],"img":{"scene":{"road":"straight","lanes":2,"center":"solid","zebra":215,"cars":[{"x":180,"dir":"E","lane":0,"label":"2","color":"blue"},{"x":90,"dir":"E","lane":1,"move":"straight","label":"1","color":"red","me":true}]}},"c":1,"e":{"uk":"Якщо перед нерегульованим переходом зупинився або гальмує транспортний засіб, водії на сусідніх смугах зменшують швидкість, за потреби зупиняються і продовжують рух, лише переконавшись, що на переході немає пішоходів.","ru":"Если перед нерегулируемым переходом остановилось или тормозит транспортное средство, водители на соседних полосах снижают скорость, при необходимости останавливаются и продолжают движение, только убедившись, что на переходе нет пешеходов."},"ref":["18.4"],"id":"q788ab9952"},{"t":"s18","q":{"uk":"Кого водій зобов'язаний пропустити в будь-якому місці, навіть поза переходом?","ru":"Кого водитель обязан пропустить в любом месте, даже вне перехода?"},"a":[{"uk":"Дітей","ru":"Детей"},{"uk":"Пішоходів з порушенням зору, які подають сигнал білою тростиною, спрямованою вперед","ru":"Пешеходов с нарушением зрения, подающих сигнал белой тростью, направленной вперёд"},{"uk":"Людей похилого віку","ru":"Пожилых людей"}],"c":1,"e":{"uk":"У будь-якому місці водій повинен пропустити пішоходів з порушенням зору, які подають сигнал тростиною білого кольору, спрямованою вперед.","ru":"В любом месте водитель должен пропустить пешеходов с нарушением зрения, подающих сигнал тростью белого цвета, направленной вперёд."},"ref":["18.5"],"id":"q7983c8105"},{"t":"s18","q":{"uk":"Трамвай стоїть на зупинці без посадкового майданчика, двері відчинені, люди йдуть до нього проїзною частиною. Що повинен зробити водій?","ru":"Трамвай стоит на остановке без посадочной площадки, двери открыты, люди идут к нему по проезжей части. Что должен сделать водитель?"},"a":[{"uk":"Зупинитися й продовжити рух, коли пішоходи залишать проїзну частину і двері трамвая зачиняться","ru":"Остановиться и продолжить движение, когда пешеходы покинут проезжую часть и двери трамвая закроются"},{"uk":"Об'їхати трамвай ліворуч","ru":"Объехать трамвай слева"},{"uk":"Проїхати з мінімальною швидкістю","ru":"Проехать с минимальной скоростью"}],"c":0,"e":{"uk":"Водій зупиняється, щоб дати дорогу пішоходам, що йдуть до трамвая або від нього з боку відчинених дверей. Рушати можна лише коли пішоходи залишать проїзну частину і двері трамвая зачиняться.","ru":"Водитель останавливается, чтобы уступить дорогу пешеходам, идущим к трамваю или от него со стороны открытых дверей. Ехать можно только когда пешеходы покинут проезжую часть и двери трамвая закроются."},"ref":["18.8"],"id":"qaea3ab77b"},{"t":"s18","q":{"uk":"За пішохідним переходом утворився затор. Чи можна в'їхати на перехід?","ru":"За пешеходным переходом образовался затор. Можно ли въехать на переход?"},"a":[{"uk":"Так, якщо на переході немає пішоходів","ru":"Да, если на переходе нет пешеходов"},{"uk":"Ні, якщо доведеться зупинитися на переході","ru":"Нет, если придётся остановиться на переходе"},{"uk":"Так, на зелений сигнал світлофора","ru":"Да, на зелёный сигнал светофора"}],"c":1,"e":{"uk":"Заборонено в'їжджати на пішохідний перехід, якщо за ним затор, через який доведеться зупинитися на переході.","ru":"Запрещено въезжать на пешеходный переход, если за ним затор, из-за которого придётся остановиться на переходе."},"ref":["18.6"],"id":"q07b6d0846"},{"t":"s18","q":{"uk":"Автобус зі знаком «Діти» зупинився з увімкненими оранжевими маячками. Що повинен зробити водій на сусідній смузі?","ru":"Автобус со знаком «Дети» остановился с включёнными оранжевыми маячками. Что должен сделать водитель на соседней полосе?"},"a":[{"uk":"Продовжити рух з тією ж швидкістю","ru":"Продолжить движение с той же скоростью"},{"uk":"Зменшити швидкість, а за потреби зупинитися, щоб не наїхати на дітей","ru":"Снизить скорость, а при необходимости остановиться, чтобы не наехать на детей"},{"uk":"Обов'язково зупинитися і чекати, доки автобус рушить","ru":"Обязательно остановиться и ждать, пока автобус начнёт движение"}],"c":1,"e":{"uk":"Наближаючись до транспортного засобу зі знаком «Діти», що зупинився з оранжевими маячками або аварійною сигналізацією, водії на суміжній смузі зменшують швидкість, а за потреби зупиняються.","ru":"Приближаясь к транспортному средству со знаком «Дети», остановившемуся с оранжевыми маячками или аварийной сигнализацией, водители на смежной полосе снижают скорость, а при необходимости останавливаются."},"ref":["18.9"],"id":"q053cad3c1"},{"t":"s18","q":{"uk":"На регульованому переході для автомобілів увімкнувся зелений, але пішохід ще не закінчив перехід. Як діяти?","ru":"На регулируемом переходе для автомобилей включился зелёный, но пешеход ещё не закончил переход. Как поступить?"},"a":[{"uk":"Дати дорогу пішоходу, який закінчує перехід","ru":"Уступить дорогу пешеходу, который заканчивает переход"},{"uk":"Рушати, бо зелений дає перевагу","ru":"Начинать движение, так как зелёный даёт преимущество"},{"uk":"Подати звуковий сигнал, щоб пішохід поквапився","ru":"Подать звуковой сигнал, чтобы пешеход поторопился"}],"c":0,"e":{"uk":"На дозвільний сигнал водій дає дорогу пішоходам, які закінчують перехід проїзної частини відповідного напрямку.","ru":"На разрешающий сигнал водитель уступает дорогу пешеходам, которые заканчивают переход проезжей части соответствующего направления."},"ref":["18.2"],"id":"q8b7824f5d"},{"t":"s19","q":{"uk":"На якій відстані до зустрічного транспортного засобу слід перемкнути дальнє світло на ближнє?","ru":"На каком расстоянии до встречного транспортного средства следует переключить дальний свет на ближний?"},"a":[{"uk":"Не менш як за 100 м","ru":"Не менее чем за 100 м"},{"uk":"Не менш як за 150 м","ru":"Не менее чем за 150 м"},{"uk":"Не менш як за 250 м","ru":"Не менее чем за 250 м"},{"uk":"Не менш як за 500 м","ru":"Не менее чем за 500 м"}],"c":2,"e":{"uk":"Дальнє світло перемикають на ближнє не менш як за 250 м до зустрічного транспортного засобу, а також коли воно може засліпити водіїв попутного напрямку. Якщо зустрічний водій блимає фарами — перемкніть раніше.","ru":"Дальний свет переключают на ближний не менее чем за 250 м до встречного транспортного средства, а также когда он может ослепить водителей попутного направления. Если встречный водитель мигает фарами — переключите раньше."},"ref":["19.2"],"id":"q32e5889b2"},{"t":"s19","q":{"uk":"Вас засліпили фари зустрічного автомобіля. Що треба зробити?","ru":"Вас ослепили фары встречного автомобиля. Что нужно сделать?"},"a":[{"uk":"Увімкнути дальнє світло у відповідь","ru":"Включить дальний свет в ответ"},{"uk":"Перестроїтися на праве узбіччя і продовжити рух","ru":"Перестроиться на правую обочину и продолжить движение"},{"uk":"Не змінюючи смуги, зупинитися і увімкнути аварійну сигналізацію","ru":"Не меняя полосы, остановиться и включить аварийную сигнализацию"}],"c":2,"e":{"uk":"У разі засліплення водій зупиняється, не змінюючи смуги руху, і вмикає аварійну сигналізацію. Рушати можна, коли мине дія засліплення.","ru":"При ослеплении водитель останавливается, не меняя полосы движения, и включает аварийную сигнализацию. Начинать движение можно, когда пройдёт действие ослепления."},"ref":["19.3"],"id":"qe246a629b"},{"t":"s19","q":{"uk":"Які світлові прилади мають бути ввімкнені на легковому автомобілі під час руху в тунелі вдень?","ru":"Какие световые приборы должны быть включены на легковом автомобиле при движении в тоннеле днём?"},"a":[{"uk":"Жодні, якщо тунель освітлений","ru":"Никакие, если тоннель освещён"},{"uk":"Фари ближнього (дальнього) світла","ru":"Фары ближнего (дальнего) света"},{"uk":"Лише габаритні вогні","ru":"Только габаритные огни"}],"c":1,"e":{"uk":"У темну пору доби, за недостатньої видимості та в тунелях (незалежно від освітлення) на механічних транспортних засобах мають бути ввімкнені фари ближнього або дальнього світла.","ru":"В тёмное время суток, при недостаточной видимости и в тоннелях (независимо от освещения) на механических транспортных средствах должны быть включены фары ближнего или дальнего света."},"ref":["19.1"],"id":"q800a036e6"},{"t":"s19","q":{"uk":"Чи можна в темну пору доби на неосвітленій дорозі їхати лише з протитуманними фарами?","ru":"Можно ли в тёмное время суток на неосвещённой дороге ехать только с противотуманными фарами?"},"a":[{"uk":"Ні, лише разом із ближнім або дальнім світлом","ru":"Нет, только вместе с ближним или дальним светом"},{"uk":"Так","ru":"Да"},{"uk":"Так, якщо швидкість не перевищує 50 км/год","ru":"Да, если скорость не превышает 50 км/ч"}],"c":0,"e":{"uk":"Протитуманні фари використовують за недостатньої видимості окремо або разом із ближнім чи дальнім світлом, а в темну пору на неосвітлених ділянках — лише разом із ближнім або дальнім.","ru":"Противотуманные фары используют при недостаточной видимости отдельно или вместе с ближним либо дальним светом, а в тёмное время на неосвещённых участках — только вместе с ближним или дальним."},"ref":["19.5"],"id":"q52c47dae3"},{"t":"s19","q":{"uk":"Коли можна вмикати задній протитуманний ліхтар?","ru":"Когда можно включать задний противотуманный фонарь?"},"a":[{"uk":"У темну пору доби завжди","ru":"В тёмное время суток всегда"},{"uk":"Лише в умовах недостатньої видимості, вдень і вночі","ru":"Только в условиях недостаточной видимости, днём и ночью"},{"uk":"Під час буксирування","ru":"При буксировке"}],"c":1,"e":{"uk":"Задній протитуманний ліхтар дозволено використовувати виключно в умовах недостатньої видимості (туман, сильний дощ, снігопад) — як удень, так і вночі.","ru":"Задний противотуманный фонарь разрешено использовать исключительно в условиях недостаточной видимости (туман, сильный дождь, снегопад) — как днём, так и ночью."},"ref":["19.9"],"id":"q16a208821"},{"t":"s19","q":{"uk":"Які світлові прилади повинні бути ввімкнені під час зупинки на дорозі в темну пору доби?","ru":"Какие световые приборы должны быть включены во время остановки на дороге в тёмное время суток?"},"a":[{"uk":"Габаритні або стоянкові ліхтарі, а за вимушеної зупинки — ще й аварійна сигналізація","ru":"Габаритные или стояночные огни, а при вынужденной остановке — ещё и аварийная сигнализация"},{"uk":"Лише аварійна сигналізація","ru":"Только аварийная сигнализация"},{"uk":"Ближнє світло фар","ru":"Ближний свет фар"}],"c":0,"e":{"uk":"Під час зупинки в темряві чи за недостатньої видимості вмикають габаритні або стоянкові ліхтарі; за вимушеної зупинки — додатково аварійну світлову сигналізацію.","ru":"Во время остановки в темноте или при недостаточной видимости включают габаритные или стояночные огни; при вынужденной остановке — дополнительно аварийную световую сигнализацию."},"ref":["19.4"],"id":"q0b4fe4624"},{"t":"s19","q":{"uk":"Що можна ввімкнути замість ближнього світла в умовах недостатньої видимості (туман)?","ru":"Что можно включить вместо ближнего света в условиях недостаточной видимости (туман)?"},"a":[{"uk":"Лише габаритні вогні","ru":"Только габаритные огни"},{"uk":"Протитуманні фари","ru":"Противотуманные фары"},{"uk":"Денні ходові вогні","ru":"Дневные ходовые огни"}],"c":1,"e":{"uk":"В умовах недостатньої видимості на механічних транспортних засобах дозволено замість фар ближнього (дальнього) світла ввімкнути протитуманні фари.","ru":"В условиях недостаточной видимости на механических транспортных средствах разрешено вместо фар ближнего (дальнего) света включить противотуманные фары."},"ref":["19.1"],"id":"q433ca08c6"},{"t":"s20","q":{"uk":"Де треба зупинитися перед залізничним переїздом, якщо шлагбаума, світлофора, стоп-лінії та знака 2.2 немає, а наближається поїзд?","ru":"Где нужно остановиться перед железнодорожным переездом, если шлагбаума, светофора, стоп-линии и знака 2.2 нет, а приближается поезд?"},"a":[{"uk":"Не ближче 5 м до рейки","ru":"Не ближе 5 м до рельса"},{"uk":"Не ближче 10 м до найближчої рейки","ru":"Не ближе 10 м до ближайшего рельса"},{"uk":"Не ближче 50 м до переїзду","ru":"Не ближе 50 м до переезда"}],"c":1,"e":{"uk":"Водій зупиняється перед стоп-лінією, знаком {s:2.2}, шлагбаумом чи світлофором, а якщо їх немає — не ближче 10 м до найближчої рейки.","ru":"Водитель останавливается перед стоп-линией, знаком {s:2.2}, шлагбаумом или светофором, а если их нет — не ближе 10 м до ближайшего рельса."},"ref":["20.3"],"id":"qc10960383"},{"t":"s20","q":{"uk":"Шлагбаум почав підніматися, але світлофор на переїзді ще показує заборонний сигнал. Чи можна рушати?","ru":"Шлагбаум начал подниматься, но светофор на переезде ещё показывает запрещающий сигнал. Можно ли начинать движение?"},"a":[{"uk":"Так, шлагбаум має перевагу","ru":"Да, шлагбаум имеет преимущество"},{"uk":"Ні, заборонний сигнал світлофора діє незалежно від положення шлагбаума","ru":"Нет, запрещающий сигнал светофора действует независимо от положения шлагбаума"}],"c":1,"e":{"uk":"Рух через переїзд заборонено, якщо ввімкнено заборонний сигнал світлофора чи звуковий сигнал, незалежно від наявності та положення шлагбаума.","ru":"Движение через переезд запрещено, если включён запрещающий сигнал светофора или звуковой сигнал, независимо от наличия и положения шлагбаума."},"ref":["20.5"],"id":"qc9489c6c6"},{"t":"s20","q":{"uk":"У якому з випадків рух через залізничний переїзд заборонено?","ru":"В каком из случаев движение через железнодорожный переезд запрещено?"},"a":[{"uk":"Шлагбаум почав опускатися","ru":"Шлагбаум начал опускаться"},{"uk":"За переїздом затор, через який доведеться зупинитися на переїзді","ru":"За переездом затор, из-за которого придётся остановиться на переезде"},{"uk":"У межах видимості наближається поїзд","ru":"В пределах видимости приближается поезд"},{"uk":"У всіх перелічених випадках","ru":"Во всех перечисленных случаях"}],"c":3,"e":{"uk":"Рух через переїзд заборонено, якщо черговий подає сигнал заборони, шлагбаум опущений чи опускається, горить заборонний сигнал, за переїздом затор або наближається поїзд.","ru":"Движение через переезд запрещено, если дежурный подаёт сигнал запрещения, шлагбаум опущен или опускается, горит запрещающий сигнал, за переездом затор или приближается поезд."},"ref":["20.5"],"id":"q29ca2d32a"},{"t":"s20","q":{"uk":"Як рухатися через переїзд, якщо немає розмітки чи знаків, що визначають кількість смуг?","ru":"Как двигаться через переезд, если нет разметки или знаков, определяющих количество полос?"},"a":[{"uk":"Лише в один ряд","ru":"Только в один ряд"},{"uk":"Не більше ніж у два ряди","ru":"Не более чем в два ряда"},{"uk":"Будь-якою кількістю рядів","ru":"Любым количеством рядов"}],"c":0,"e":{"uk":"Якщо перед переїздом немає розмітки чи знаків, які визначають кількість смуг, рух через нього дозволено лише в один ряд.","ru":"Если перед переездом нет разметки или знаков, определяющих количество полос, движение через него разрешено только в один ряд."},"ref":["20.4"],"id":"q13687d6f0"},{"t":"s20","q":{"uk":"Перед закритим переїздом стоїть черга автомобілів. Чи можна їх об'їхати?","ru":"Перед закрытым переездом стоит очередь автомобилей. Можно ли их объехать?"},"a":[{"uk":"Так, якщо зустрічна смуга вільна","ru":"Да, если встречная полоса свободна"},{"uk":"Ні","ru":"Нет"},{"uk":"Так, щоб стати першим перед шлагбаумом","ru":"Да, чтобы встать первым перед шлагбаумом"}],"c":1,"e":{"uk":"Заборонено самовільно відкривати чи об'їжджати шлагбаум, а також об'їжджати транспортні засоби, що стоять перед переїздом, коли рух через нього заборонено.","ru":"Запрещено самовольно открывать или объезжать шлагбаум, а также объезжать транспортные средства, стоящие перед переездом, когда движение через него запрещено."},"ref":["20.7"],"id":"qb7301214b"},{"t":"s20","q":{"uk":"Автомобіль заглух на переїзді, звільнити переїзд не вдається. Що є сигналом загальної тривоги?","ru":"Автомобиль заглох на переезде, освободить переезд не удаётся. Что является сигналом общей тревоги?"},"a":[{"uk":"Безперервний звуковий сигнал","ru":"Непрерывный звуковой сигнал"},{"uk":"Серії з одного довгого і трьох коротких звукових сигналів","ru":"Серии из одного длинного и трёх коротких звуковых сигналов"},{"uk":"Три довгі звукові сигнали","ru":"Три длинных звуковых сигнала"}],"c":1,"e":{"uk":"Сигнал загальної тривоги — серії звукових сигналів: один довгий і три короткі. Сигнал зупинки поїзда — круговий рух руки (вдень з яскравою тканиною, вночі з ліхтарем чи факелом).","ru":"Сигнал общей тревоги — серии звуковых сигналов: один длинный и три коротких. Сигнал остановки поезда — круговое движение руки (днём с яркой тканью, ночью с фонарём или факелом)."},"ref":["20.9"],"id":"q76f5009d3"},{"t":"s20","q":{"uk":"Автомобіль вимушено зупинився на переїзді. Що водій повинен зробити насамперед?","ru":"Автомобиль вынужденно остановился на переезде. Что водитель должен сделать в первую очередь?"},"a":[{"uk":"Негайно висадити людей і вжити заходів для звільнення переїзду","ru":"Немедленно высадить людей и принять меры для освобождения переезда"},{"uk":"Увімкнути аварійну сигналізацію й чекати допомоги в салоні","ru":"Включить аварийную сигнализацию и ждать помощи в салоне"},{"uk":"Зателефонувати в поліцію","ru":"Позвонить в полицию"}],"c":0,"e":{"uk":"Водій негайно висаджує людей і звільняє переїзд. Якщо не вдається — за можливості посилає двох людей уздовж колій в обидва боки не менш як на 1000 м, сам залишається біля машини й подає сигнали загальної тривоги, а побачивши поїзд, біжить йому назустріч, подаючи сигнал зупинки.","ru":"Водитель немедленно высаживает людей и освобождает переезд. Если не удаётся — по возможности посылает двух человек вдоль путей в обе стороны не менее чем на 1000 м, сам остаётся у машины и подаёт сигналы общей тревоги, а увидев поезд, бежит ему навстречу, подавая сигнал остановки."},"ref":["20.8"],"id":"q9e83490cd"},{"t":"s20","q":{"uk":"На яку відстань від переїзду треба послати людей уздовж колій, щоб попередити машиніста поїзда?","ru":"На какое расстояние от переезда нужно послать людей вдоль путей, чтобы предупредить машиниста поезда?"},"a":[{"uk":"Не менш як на 300 м","ru":"Не менее чем на 300 м"},{"uk":"Не менш як на 500 м","ru":"Не менее чем на 500 м"},{"uk":"Не менш як на 1000 м","ru":"Не менее чем на 1000 м"}],"c":2,"e":{"uk":"За можливості двох людей посилають уздовж колій в обидва боки від переїзду не менш як на 1000 м.","ru":"По возможности двух человек посылают вдоль путей в обе стороны от переезда не менее чем на 1000 м."},"ref":["20.8"],"id":"q607fd0c7d"},{"t":"s20","q":{"uk":"Черговий по переїзду стоїть до вас грудьми з піднятим над головою жезлом. Що це означає?","ru":"Дежурный по переезду стоит к вам грудью с поднятым над головой жезлом. Что это означает?"},"a":[{"uk":"Можна проїжджати з обережністю","ru":"Можно проезжать с осторожностью"},{"uk":"Рух через переїзд заборонено","ru":"Движение через переезд запрещено"}],"c":1,"e":{"uk":"Черговий подає сигнал заборони, стоячи до водія грудьми або спиною з піднятим над головою жезлом (червоним ліхтарем, прапорцем) або з витягнутими в сторони руками.","ru":"Дежурный подаёт сигнал запрещения, стоя к водителю грудью или спиной с поднятым над головой жезлом (красным фонарём, флажком) или с вытянутыми в стороны руками."},"ref":["20.5"],"id":"qe825cbf68"},{"t":"s21","q":{"uk":"Дитину якого зросту дозволено перевозити в легковому автомобілі без дитячого автокрісла (утримуючої системи)?","ru":"Ребёнка какого роста разрешено перевозить в легковом автомобиле без детского автокресла (удерживающей системы)?"},"a":[{"uk":"Від 120 см","ru":"От 120 см"},{"uk":"Від 135 см","ru":"От 135 см"},{"uk":"Від 150 см","ru":"От 150 см"}],"c":2,"e":{"uk":"Дітей зростом менше 150 см заборонено перевозити без дитячих утримуючих систем, що дають змогу пристебнути дитину штатними ременями безпеки.","ru":"Детей ростом менее 150 см запрещено перевозить без детских удерживающих систем, позволяющих пристегнуть ребёнка штатными ремнями безопасности."},"ref":["21.11"],"id":"q1ab2a7e2c"},{"t":"s21","q":{"uk":"Чи можна встановити дитяче автокрісло на передньому сидінні легкового автомобіля?","ru":"Можно ли установить детское автокресло на переднем сиденье легкового автомобиля?"},"a":[{"uk":"Так, без обмежень","ru":"Да, без ограничений"},{"uk":"Лише для дитини до 3 років, крісло проти напрямку руху й з вимкненою фронтальною подушкою безпеки","ru":"Только для ребёнка до 3 лет, кресло против направления движения и с выключенной фронтальной подушкой безопасности"},{"uk":"Ні, ніколи","ru":"Нет, никогда"}],"c":1,"e":{"uk":"Дитячі утримуючі системи встановлюють не в першому ряду. Для дитини до трьох років у легковому автомобілі допускається переднє сидіння: крісло проти руху, фронтальна подушка вимкнена.","ru":"Детские удерживающие системы устанавливают не в первом ряду. Для ребёнка до трёх лет в легковом автомобиле допускается переднее сиденье: кресло против движения, фронтальная подушка выключена."},"ref":["21.13"],"id":"qb2388957a"},{"t":"s21","q":{"uk":"Коли водієві дозволено відчиняти двері автомобіля з пасажирами?","ru":"Когда водителю разрешено открывать двери автомобиля с пассажирами?"},"a":[{"uk":"Лише після повної зупинки","ru":"Только после полной остановки"},{"uk":"На швидкості до 5 км/год","ru":"На скорости до 5 км/ч"},{"uk":"Коли автомобіль під'їжджає до тротуару","ru":"Когда автомобиль подъезжает к тротуару"}],"c":0,"e":{"uk":"Водієві заборонено починати рух до повного зачинення дверей та відчиняти їх до зупинки транспортного засобу.","ru":"Водителю запрещено начинать движение до полного закрытия дверей и открывать их до остановки транспортного средства."},"ref":["21.4"],"id":"q94a75bd3c"},{"t":"s21","q":{"uk":"Чи можна перевозити дітей до 16 років у кузові вантажного автомобіля?","ru":"Можно ли перевозить детей до 16 лет в кузове грузового автомобиля?"},"a":[{"uk":"Так, якщо є обладнані сидіння","ru":"Да, если есть оборудованные сиденья"},{"uk":"Ні, у кузові будь-якого вантажного автомобіля заборонено","ru":"Нет, в кузове любого грузового автомобиля запрещено"}],"c":1,"e":{"uk":"Заборонено перевозити дітей до 16 років у кузові будь-якого вантажного автомобіля, а організовані групи дітей — у темну пору доби.","ru":"Запрещено перевозить детей до 16 лет в кузове любого грузового автомобиля, а организованные группы детей — в тёмное время суток."},"ref":["21.11"],"id":"q735fe2b67"},{"t":"s23","q":{"uk":"Якою має бути довжина гнучкого зчеплення під час буксирування?","ru":"Какой должна быть длина гибкой сцепки при буксировке?"},"a":[{"uk":"До 4 м","ru":"До 4 м"},{"uk":"4–6 м","ru":"4–6 м"},{"uk":"6–8 м","ru":"6–8 м"}],"c":1,"e":{"uk":"Жорстке зчеплення забезпечує відстань не більше 4 м, гнучке — 4–6 м. Гнучке зчеплення позначають прапорцями або щитками через кожний метр.","ru":"Жёсткая сцепка обеспечивает расстояние не более 4 м, гибкая — 4–6 м. Гибкую сцепку обозначают флажками или щитками через каждый метр."},"ref":["23.3"],"id":"qa5fc21569"},{"t":"s23","q":{"uk":"Що має бути справним в автомобілі, який буксирують на гнучкому зчепленні?","ru":"Что должно быть исправно в автомобиле, который буксируют на гибкой сцепке?"},"a":[{"uk":"Лише рульове керування","ru":"Только рулевое управление"},{"uk":"Робоча гальмова система і рульове керування","ru":"Рабочая тормозная система и рулевое управление"},{"uk":"Лише гальма","ru":"Только тормоза"}],"c":1,"e":{"uk":"На гнучкому зчепленні в буксированому автомобілі мають діяти робоче гальмо і кермо, на жорсткому — кермо. Якщо кермо не працює — лише частковим навантаженням на платформу.","ru":"На гибкой сцепке в буксируемом автомобиле должны действовать рабочий тормоз и руль, на жёсткой — руль. Если руль не работает — только частичной погрузкой на платформу."},"ref":["23.4","23.7"],"id":"q971eb1548"},{"t":"s23","q":{"uk":"Коли заборонено буксирування на гнучкому зчепленні?","ru":"Когда запрещена буксировка на гибкой сцепке?"},"a":[{"uk":"Під час ожеледиці","ru":"Во время гололедицы"},{"uk":"У темну пору доби","ru":"В тёмное время суток"},{"uk":"У населеному пункті","ru":"В населённом пункте"}],"c":0,"e":{"uk":"Буксирування на гнучкому зчепленні під час ожеледиці заборонено. Також не можна буксирувати автобусами, мотоциклами без коляски, транспортним засобом з причепом і більше одного транспортного засобу.","ru":"Буксировка на гибкой сцепке во время гололедицы запрещена. Также нельзя буксировать автобусами, мотоциклами без коляски, транспортным средством с прицепом и более одного транспортного средства."},"ref":["23.10"],"id":"q4ebb958e1"},{"t":"s23","q":{"uk":"Чи можна перевозити пасажирів у легковому автомобілі, який буксирують на тросі?","ru":"Можно ли перевозить пассажиров в легковом автомобиле, который буксируют на тросе?"},"a":[{"uk":"Так, у легковому автомобілі можна","ru":"Да, в легковом автомобиле можно"},{"uk":"Ні, в жодному разі","ru":"Нет, ни в коем случае"}],"c":0,"e":{"uk":"Під час буксирування на жорсткому чи гнучкому зчепленні заборонено перевозити пасажирів у буксированому транспортному засобі, крім легкового автомобіля. На платформі (часткове навантаження) пасажирів перевозять лише в кабіні тягача.","ru":"При буксировке на жёсткой или гибкой сцепке запрещено перевозить пассажиров в буксируемом транспортном средстве, кроме легкового автомобиля. На платформе (частичная погрузка) пассажиров перевозят только в кабине тягача."},"ref":["23.9"],"id":"qb4fcd49bd"},{"t":"s24","q":{"uk":"З якого віку можна навчатися водіння автомобіля?","ru":"С какого возраста можно учиться вождению автомобиля?"},"a":[{"uk":"З 14 років","ru":"С 14 лет"},{"uk":"З 16 років","ru":"С 16 лет"},{"uk":"З 18 років","ru":"С 18 лет"}],"c":1,"e":{"uk":"Навчатися водіння автомобіля можна з 16 років, мотоцикла чи мопеда — з 14. Навчальна їзда на дорогах — лише з інструктором; у житловій зоні та на автомагістралях вона заборонена.","ru":"Учиться вождению автомобиля можно с 16 лет, мотоцикла или мопеда — с 14. Учебная езда на дорогах — только с инструктором; в жилой зоне и на автомагистралях она запрещена."},"ref":["24.2","24.9"],"id":"q64719f3d5"},{"t":"s25","q":{"uk":"На скільки груп ділять колону без супроводу оперативних транспортних засобів?","ru":"На сколько групп делят колонну без сопровождения оперативных транспортных средств?"},"a":[{"uk":"На групи не більше п'яти транспортних засобів","ru":"На группы не более пяти транспортных средств"},{"uk":"На групи по десять","ru":"На группы по десять"},{"uk":"Не ділять","ru":"Не делят"}],"c":0,"e":{"uk":"Колону без супроводу ділять на групи не більше п'яти транспортних засобів з дистанцією, що дає змогу іншим обганяти групу. Іншим заборонено займати місце в колоні.","ru":"Колонну без сопровождения делят на группы не более пяти транспортных средств с дистанцией, позволяющей другим обгонять группу. Другим запрещено занимать место в колонне."},"ref":["25.4","25.6"],"id":"q9b7affec2"},{"t":"s26","q":{"uk":"Хто має перевагу в житловій зоні?","ru":"У кого преимущество в жилой зоне?"},"a":[{"uk":"Пішоходи, але вони не повинні безпідставно заважати транспорту","ru":"Пешеходы, но они не должны без причины мешать транспорту"},{"uk":"Транспортні засоби","ru":"Транспортные средства"},{"uk":"Той, хто праворуч","ru":"Тот, кто справа"}],"img":{"sign":"5.34"},"c":0,"e":{"uk":"У житловій і пішохідній зоні пішоходи можуть іти і тротуаром, і проїзною частиною та мають перевагу. Швидкість — до 20 км/год.","ru":"В жилой и пешеходной зоне пешеходы могут идти и по тротуару, и по проезжей части и имеют преимущество. Скорость — до 20 км/ч."},"ref":["26.1","12.5"],"id":"q1be42aa05"},{"t":"s26","q":{"uk":"Що заборонено в житловій зоні?","ru":"Что запрещено в жилой зоне?"},"a":[{"uk":"Будь-яка зупинка","ru":"Любая остановка"},{"uk":"Транзитний рух, стоянка з працюючим двигуном, навчальна їзда","ru":"Сквозное движение, стоянка с работающим двигателем, учебная езда"},{"uk":"Рух легкових автомобілів","ru":"Движение легковых автомобилей"}],"c":1,"e":{"uk":"У житловій зоні заборонено транзитний рух, стоянку поза відведеними місцями, стоянку з працюючим двигуном, навчальну їзду та рух вантажівок (крім обслуговуючих).","ru":"В жилой зоне запрещены сквозное движение, стоянка вне отведённых мест, стоянка с работающим двигателем, учебная езда и движение грузовиков (кроме обслуживающих)."},"ref":["26.2"],"id":"q5c9f60a31"},{"t":"s26","q":{"uk":"Виїжджаючи з житлової зони, водій повинен...","ru":"Выезжая из жилой зоны, водитель должен..."},"a":[{"uk":"дати дорогу іншим учасникам дорожнього руху","ru":"уступить дорогу другим участникам дорожного движения"},{"uk":"керуватися правилом «перешкода праворуч»","ru":"руководствоваться правилом «помеха справа»"},{"uk":"рухатися першим, якщо їде прямо","ru":"ехать первым, если едет прямо"}],"c":0,"e":{"uk":"Під час виїзду з житлової та пішохідної зони водії дають дорогу іншим учасникам руху.","ru":"При выезде из жилой и пешеходной зоны водители уступают дорогу другим участникам движения."},"ref":["26.4"],"id":"q33ef82241"},{"t":"s27","q":{"uk":"Що з переліченого заборонено на автомагістралі?","ru":"Что из перечисленного запрещено на автомагистрали?"},"a":[{"uk":"Рух зі швидкістю 110 км/год","ru":"Движение со скоростью 110 км/ч"},{"uk":"Розворот, рух заднім ходом і зупинка поза спеціальними майданчиками","ru":"Разворот, движение задним ходом и остановка вне специальных площадок"},{"uk":"Випередження по лівій смузі","ru":"Опережение по левой полосе"}],"c":1,"e":{"uk":"На автомагістралях і дорогах для автомобілів заборонено розворот, в'їзд у технологічні розриви розділювальної смуги, рух заднім ходом, зупинку поза майданчиками {s:5.42.1}, {s:5.43}, {s:6.15}, навчальну їзду, рух тракторів.","ru":"На автомагистралях и дорогах для автомобилей запрещены разворот, въезд в технологические разрывы разделительной полосы, движение задним ходом, остановка вне площадок {s:5.42.1}, {s:5.43}, {s:6.15}, учебная езда, движение тракторов."},"ref":["27.2"],"id":"qc781291f7"},{"t":"s27","q":{"uk":"Автомобіль вимушено зупинився на проїзній частині автомагістралі. Що робити?","ru":"Автомобиль вынужденно остановился на проезжей части автомагистрали. Что делать?"},"a":[{"uk":"Увімкнути аварійку, виставити знак аварійної зупинки і прибрати автомобіль за межі проїзної частини праворуч","ru":"Включить аварийку, выставить знак аварийной остановки и убрать автомобиль за пределы проезжей части вправо"},{"uk":"Залишатися в автомобілі й чекати евакуатор","ru":"Оставаться в автомобиле и ждать эвакуатор"},{"uk":"Рухатися заднім ходом до найближчого з'їзду","ru":"Двигаться задним ходом до ближайшего съезда"}],"c":0,"e":{"uk":"За вимушеної зупинки на автомагістралі транспортний засіб позначають згідно з пунктами 9.9–9.11 (аварійка, знак аварійної зупинки) і вживають заходів, щоб прибрати його за межі проїзної частини праворуч.","ru":"При вынужденной остановке на автомагистрали транспортное средство обозначают согласно пунктам 9.9–9.11 (аварийка, знак аварийной остановки) и принимают меры, чтобы убрать его за пределы проезжей части вправо."},"ref":["27.5"],"id":"q9d703a853"},{"t":"s28","q":{"uk":"Що заборонено на гірських дорогах?","ru":"Что запрещено на горных дорогах?"},"a":[{"uk":"Рухатися з вимкненим двигуном і вимкненим зчепленням або передачею (накатом)","ru":"Двигаться с выключенным двигателем и выключенным сцеплением или передачей (накатом)"},{"uk":"Користуватися моторним гальмуванням","ru":"Пользоваться торможением двигателем"},{"uk":"Вмикати ближнє світло вдень","ru":"Включать ближний свет днём"}],"c":0,"e":{"uk":"На гірських дорогах заборонено рухатися з непрацюючим двигуном і вимкненим зчепленням чи передачею, буксирувати на гнучкому зчепленні, а в ожеледицю — будь-яке буксирування.","ru":"На горных дорогах запрещено двигаться с неработающим двигателем и выключенным сцеплением или передачей, буксировать на гибкой сцепке, а в гололедицу — любая буксировка."},"ref":["28.3"],"id":"qcbf49dbff"},{"t":"s22","q":{"uk":"Вантаж виступає за задній габарит автомобіля на 1,5 м. Що потрібно зробити?","ru":"Груз выступает за задний габарит автомобиля на 1,5 м. Что нужно сделать?"},"a":[{"uk":"Нічого, якщо вантаж надійно закріплений","ru":"Ничего, если груз надёжно закреплён"},{"uk":"Позначити його розпізнавальним знаком «Негабаритний вантаж» (червоно-білі щитки чи прапорці)","ru":"Обозначить его опознавательным знаком «Негабаритный груз» (красно-белые щитки или флажки)"},{"uk":"Увімкнути аварійну сигналізацію на весь час руху","ru":"Включить аварийную сигнализацию на всё время движения"}],"c":1,"e":{"uk":"Вантаж, що виступає спереду або ззаду більш як на 1 м чи збоку більш як на 0,4 м від габаритного ліхтаря, позначають знаком «Негабаритний вантаж», а вночі — ще й ліхтарями або світлоповертачами.","ru":"Груз, выступающий спереди или сзади более чем на 1 м или сбоку более чем на 0,4 м от габаритного фонаря, обозначают знаком «Негабаритный груз», а ночью — ещё и фонарями или световозвращателями."},"ref":["22.4","30.3"],"id":"qc1d641508"},{"t":"s22","q":{"uk":"За якої умови дозволено перевозити вантаж на легковому автомобілі (наприклад, на багажнику даху)?","ru":"При каком условии разрешено перевозить груз на легковом автомобиле (например, на багажнике крыши)?"},"a":[{"uk":"Якщо він не обмежує оглядовість, не закриває світлові прилади й номери та не порушує стійкість автомобіля","ru":"Если он не ограничивает обзорность, не закрывает световые приборы и номера и не нарушает устойчивость автомобиля"},{"uk":"Якщо його маса не перевищує 50 кг","ru":"Если его масса не превышает 50 кг"},{"uk":"Лише в темну пору доби","ru":"Только в тёмное время суток"}],"c":0,"e":{"uk":"Вантаж не повинен наражати на небезпеку інших, порушувати стійкість, обмежувати оглядовість, закривати світлові прилади, світлоповертачі й номерні знаки, шуміти чи пилити. Водій перевіряє кріплення перед рушанням і стежить за ним у дорозі.","ru":"Груз не должен подвергать опасности других, нарушать устойчивость, ограничивать обзорность, закрывать световые приборы, световозвращатели и номерные знаки, шуметь или пылить. Водитель проверяет крепление перед поездкой и следит за ним в пути."},"ref":["22.2","22.3"],"id":"q67439db2a"},{"t":"s30","q":{"uk":"Протягом якого строку треба зареєструвати придбаний автомобіль?","ru":"В течение какого срока нужно зарегистрировать приобретённый автомобиль?"},"a":[{"uk":"30 діб","ru":"30 суток"},{"uk":"10 діб","ru":"10 суток"},{"uk":"3 місяці","ru":"3 месяца"}],"c":1,"e":{"uk":"Власник зобов'язаний зареєструвати (перереєструвати) транспортний засіб протягом 10 діб з моменту придбання, митного оформлення або переобладнання.","ru":"Владелец обязан зарегистрировать (перерегистрировать) транспортное средство в течение 10 суток с момента приобретения, таможенного оформления или переоборудования."},"ref":["30.1"],"id":"qd560b1e8e"},{"t":"s30","q":{"uk":"Де розміщують розпізнавальний знак «Шипи»?","ru":"Где размещают опознавательный знак «Шипы»?"},"a":[{"uk":"Ззаду на транспортних засобах із шипованими шинами","ru":"Сзади на транспортных средствах с шипованными шинами"},{"uk":"Спереду і ззаду","ru":"Спереди и сзади"},{"uk":"На лобовому склі","ru":"На лобовом стекле"}],"c":0,"e":{"uk":"«Шипи» — білий трикутник із червоною каймою і літерою «Ш»; розміщують ззаду. «Навчальний транспортний засіб» — такий самий трикутник з літерою «Н», спереду і ззаду.","ru":"«Шипы» — белый треугольник с красной каймой и буквой «Ш»; размещают сзади. «Учебное транспортное средство» — такой же треугольник с буквой «Н», спереди и сзади."},"ref":["30.3"],"id":"q9c7fd783d"},{"t":"s30","q":{"uk":"На якому автомобілі обов'язково має бути знак «Обмеження максимальної швидкості» ззаду ліворуч?","ru":"На каком автомобиле обязательно должен быть знак «Ограничение максимальной скорости» сзади слева?"},"a":[{"uk":"На автомобілі, яким керує водій зі стажем до 2 років","ru":"На автомобиле, которым управляет водитель со стажем до 2 лет"},{"uk":"На будь-якому автомобілі з причепом","ru":"На любом автомобиле с прицепом"},{"uk":"На автомобілі таксі","ru":"На автомобиле такси"}],"c":0,"e":{"uk":"Знак із зображенням {s:3.29} розміщують ззаду ліворуч на автомобілях водіїв зі стажем до 2 років, великогабаритних і великовагових транспортних засобах, при перевезенні небезпечних вантажів та в інших випадках, коли швидкість обмежена.","ru":"Знак с изображением {s:3.29} размещают сзади слева на автомобилях водителей со стажем до 2 лет, крупногабаритных и тяжеловесных транспортных средствах, при перевозке опасных грузов и в других случаях, когда скорость ограничена."},"ref":["30.3"],"id":"q29edef9f0"},{"t":"s31","q":{"uk":"Яка мінімальна залишкова глибина малюнка протектора шин легкового автомобіля?","ru":"Какая минимальная остаточная глубина рисунка протектора шин легкового автомобиля?"},"a":[{"uk":"1,0 мм","ru":"1,0 мм"},{"uk":"1,6 мм","ru":"1,6 мм"},{"uk":"2,0 мм","ru":"2,0 мм"},{"uk":"0,8 мм","ru":"0,8 мм"}],"c":1,"e":{"uk":"Для легкових автомобілів і вантажівок до 3,5 т — не менше 1,6 мм, для вантажівок понад 3,5 т — 1,0 мм, для автобусів — 2,0 мм, для мотоциклів і мопедів — 0,8 мм.","ru":"Для легковых автомобилей и грузовиков до 3,5 т — не менее 1,6 мм, для грузовиков более 3,5 т — 1,0 мм, для автобусов — 2,0 мм, для мотоциклов и мопедов — 0,8 мм."},"ref":["31.4"],"id":"q84f7aea20"},{"t":"s31","q":{"uk":"Під час дощу перестав працювати склоочисник з боку водія. Що робити?","ru":"Во время дождя перестал работать стеклоочиститель со стороны водителя. Что делать?"},"a":[{"uk":"Їхати до найближчого сервісу з аварійкою","ru":"Ехать до ближайшего сервиса с аварийкой"},{"uk":"Подальший рух заборонено; треба прибрати автомобіль з проїзної частини","ru":"Дальнейшее движение запрещено; нужно убрать автомобиль с проезжей части"},{"uk":"Продовжити рух із меншою швидкістю","ru":"Продолжить движение с меньшей скоростью"}],"c":1,"e":{"uk":"Подальший рух заборонено, якщо несправні робоча гальмова система чи кермо, вночі не горять фари чи задні габарити, під час дощу або снігу не працює склоочисник з боку водія, або зіпсований зчіпний пристрій автопоїзда.","ru":"Дальнейшее движение запрещено, если неисправны рабочая тормозная система или руль, ночью не горят фары или задние габариты, во время дождя или снега не работает стеклоочиститель со стороны водителя либо неисправно сцепное устройство автопоезда."},"ref":["31.6"],"id":"qe524262b3"},{"t":"s31","q":{"uk":"Що обов'язково має бути в легковому автомобілі?","ru":"Что обязательно должно быть в легковом автомобиле?"},"a":[{"uk":"Медична аптечка, знак аварійної зупинки і вогнегасник","ru":"Медицинская аптечка, знак аварийной остановки и огнетушитель"},{"uk":"Аптечка і буксирувальний трос","ru":"Аптечка и буксировочный трос"},{"uk":"Лише знак аварійної зупинки","ru":"Только знак аварийной остановки"}],"c":0,"e":{"uk":"Експлуатацію заборонено, якщо в легковому автомобілі немає аптечки, знака аварійної зупинки (або миготливого червоного ліхтаря) та працездатного вогнегасника.","ru":"Эксплуатация запрещена, если в легковом автомобиле нет аптечки, знака аварийной остановки (или мигающего красного фонаря) и работоспособного огнетушителя."},"ref":["31.4"],"id":"qc1d44b2d9"},{"t":"s31","q":{"uk":"Вдень у дорозі перестала горіти ліва фара ближнього світла. Як діяти?","ru":"Днём в пути перестала гореть левая фара ближнего света. Как поступить?"},"a":[{"uk":"Усунути несправність, а якщо неможливо — обережно їхати найкоротшим шляхом до місця ремонту чи стоянки","ru":"Устранить неисправность, а если невозможно — осторожно ехать кратчайшим путём к месту ремонта или стоянки"},{"uk":"Негайно зупинитися і викликати евакуатор","ru":"Немедленно остановиться и вызвать эвакуатор"},{"uk":"Продовжувати поїздку як зазвичай","ru":"Продолжать поездку как обычно"}],"c":0,"e":{"uk":"Несправність лівої фари ближнього світла — серед несправностей п. 31.4. Якщо усунути її в дорозі не вдається, можна рухатися найкоротшим шляхом до місця ремонту чи стоянки, дотримуючись запобіжних заходів. Уночі без фар рух заборонено.","ru":"Неисправность левой фары ближнего света — среди неисправностей п. 31.4. Если устранить её в пути не удаётся, можно двигаться кратчайшим путём к месту ремонта или стоянки, соблюдая меры предосторожности. Ночью без фар движение запрещено."},"ref":["31.4","31.5","31.6"],"id":"qd03ba6bf0"},{"t":"s31","q":{"uk":"Чи можна встановлювати на одну вісь шиповані і нешиповані шини?","ru":"Можно ли устанавливать на одну ось шипованные и нешипованные шины?"},"a":[{"uk":"Так, якщо вони одного розміру","ru":"Да, если они одного размера"},{"uk":"Ні","ru":"Нет"},{"uk":"Так, лише на задню вісь","ru":"Да, только на заднюю ось"}],"c":1,"e":{"uk":"Заборонено ставити на одну вісь діагональні й радіальні, шиповані й нешиповані, зимові й літні шини, шини різних розмірів, конструкцій чи з різним малюнком протектора.","ru":"Запрещено ставить на одну ось диагональные и радиальные, шипованные и нешипованные, зимние и летние шины, шины разных размеров, конструкций или с разным рисунком протектора."},"ref":["31.4"],"id":"q60a915f1b"},{"t":"s31","q":{"uk":"Який граничний сумарний люфт у рульовому керуванні легкового автомобіля?","ru":"Какой предельный суммарный люфт в рулевом управлении легкового автомобиля?"},"a":[{"uk":"10°","ru":"10°"},{"uk":"20°","ru":"20°"},{"uk":"25°","ru":"25°"}],"c":0,"e":{"uk":"Для легкових автомобілів і вантажівок до 3,5 т сумарний люфт керма — не більше 10°.","ru":"Для легковых автомобилей и грузовиков до 3,5 т суммарный люфт руля — не более 10°."},"ref":["31.4"],"id":"q3a3bacd96"},{"t":"s33","q":{"uk":"До якого місця діє заборонний знак 3.25 «Обгін заборонено», якщо немає таблички чи знака кінця зони?","ru":"До какого места действует запрещающий знак 3.25 «Обгон запрещён», если нет таблички или знака конца зоны?"},"a":[{"uk":"100 м за знаком","ru":"100 м за знаком"},{"uk":"До найближчого перехрестя за ним, а в населеному пункті без перехресть — до кінця населеного пункту","ru":"До ближайшего перекрёстка за ним, а в населённом пункте без перекрёстков — до конца населённого пункта"},{"uk":"До знака 3.42","ru":"До знака 3.42"}],"img":{"sign":"3.25"},"c":1,"e":{"uk":"Зона дії більшості заборонних знаків — від місця встановлення до найближчого перехрестя. Виїзди з прилеглих територій і ґрунтові дороги без знаків пріоритету дію знака не переривають.","ru":"Зона действия большинства запрещающих знаков — от места установки до ближайшего перекрёстка. Выезды с прилегающих территорий и грунтовые дороги без знаков приоритета действие знака не прерывают."},"ref":["33.3"],"id":"q180b56bd3"},{"t":"s33","q":{"uk":"Чим знак 3.34 «Зупинку заборонено» відрізняється від знака 3.35 «Стоянку заборонено»?","ru":"Чем знак 3.34 «Остановка запрещена» отличается от знака 3.35 «Стоянка запрещена»?"},"a":[{"uk":"3.34 забороняє і зупинку, і стоянку; 3.35 — лише стоянку","ru":"3.34 запрещает и остановку, и стоянку; 3.35 — только стоянку"},{"uk":"Це однакові знаки","ru":"Это одинаковые знаки"},{"uk":"3.34 діє лише вночі","ru":"3.34 действует только ночью"}],"img":{"signs":["3.34","3.35"]},"c":0,"e":{"uk":"Під знаком {s:3.34} заборонено зупинятися і стояти (крім таксі для посадки й висадки). Під знаком {s:3.35} зупинятися можна, але стояти понад 5 хвилин — ні. Обидва діють лише на тому боці дороги, де встановлені.","ru":"Под знаком {s:3.34} запрещено останавливаться и стоять (кроме такси для посадки и высадки). Под знаком {s:3.35} останавливаться можно, но стоять более 5 минут — нельзя. Оба действуют только на той стороне дороги, где установлены."},"ref":["33.3"],"id":"q17a4eaa5f"},{"t":"s33","q":{"uk":"Знак 3.23 «Поворот ліворуч заборонено». Чи можна на цьому перехресті розвернутися?","ru":"Знак 3.23 «Поворот налево запрещён». Можно ли на этом перекрёстке развернуться?"},"a":[{"uk":"Так, розворот дозволено","ru":"Да, разворот разрешён"},{"uk":"Ні, розворот теж заборонено","ru":"Нет, разворот тоже запрещён"}],"img":{"sign":"3.23"},"c":0,"e":{"uk":"Знак {s:3.23} забороняє поворот ліворуч, але дозволяє розворот. Знак {s:3.24} навпаки: забороняє розворот, але дозволяє поворот ліворуч.","ru":"Знак {s:3.23} запрещает поворот налево, но разрешает разворот. Знак {s:3.24} наоборот: запрещает разворот, но разрешает поворот налево."},"ref":["33.3"],"id":"qc52ba8e6d"},{"t":"s33","q":{"uk":"Що дозволяє знак 4.3 «Рух ліворуч»?","ru":"Что разрешает знак 4.3 «Движение налево»?"},"a":[{"uk":"Лише поворот ліворуч","ru":"Только поворот налево"},{"uk":"Поворот ліворуч і розворот","ru":"Поворот налево и разворот"},{"uk":"Рух прямо і ліворуч","ru":"Движение прямо и налево"}],"img":{"sign":"4.3"},"c":1,"e":{"uk":"Знаки {s:4.3}, {s:4.5} і {s:4.6} дозволяють також розворот. Наказові знаки напрямку не поширюються на маршрутні транспортні засоби.","ru":"Знаки {s:4.3}, {s:4.5} и {s:4.6} разрешают также разворот. Предписывающие знаки направления не распространяются на маршрутные транспортные средства."},"ref":["33.4"],"id":"q1e0fff511"},{"t":"s33","q":{"uk":"Ви наближаєтеся до вузької ділянки, перед якою встановлено цей знак. Як діяти?","ru":"Вы приближаетесь к узкому участку, перед которым установлен этот знак. Как поступить?"},"a":[{"uk":"Дати дорогу зустрічним транспортним засобам, що вже на вузькій ділянці, і не в'їжджати, якщо заважатимете їм","ru":"Уступить дорогу встречным транспортным средствам, которые уже на узком участке, и не въезжать, если будете им мешать"},{"uk":"Проїхати першим, бо ви маєте перевагу","ru":"Проехать первым, так как у вас преимущество"},{"uk":"Подати звуковий сигнал і проїхати","ru":"Подать звуковой сигнал и проехать"}],"img":{"sign":"2.5"},"c":0,"e":{"uk":"{s:2.5} «Перевага зустрічного руху» — забороняє в'їзд на вузьку ділянку, якщо це утруднить зустрічний рух. Перевагу на вузькій ділянці має той, перед ким стоїть {s:2.6}.","ru":"{s:2.5} «Преимущество встречного движения» — запрещает въезд на узкий участок, если это затруднит встречное движение. Преимущество на узком участке у того, перед кем стоит {s:2.6}."},"ref":["33.2"],"id":"q24a7e427b"},{"t":"s33","q":{"uk":"Де треба зупинитися перед знаком 2.2 «Проїзд без зупинки заборонено», якщо стоп-лінії немає?","ru":"Где нужно остановиться перед знаком 2.2 «Проезд без остановки запрещён», если стоп-линии нет?"},"a":[{"uk":"Не обов'язково зупинятися, якщо дорога вільна","ru":"Не обязательно останавливаться, если дорога свободна"},{"uk":"Перед знаком","ru":"Перед знаком"},{"uk":"На краю перехрещуваної проїзної частини","ru":"На краю пересекаемой проезжей части"}],"img":{"sign":"2.2"},"c":1,"e":{"uk":"Знак {s:2.2} вимагає обов'язкової зупинки перед стоп-лінією {m:1.12}, а якщо її немає — перед знаком, навіть коли дорога вільна. Після цього треба пропустити тих, хто їде перехрещуваною дорогою.","ru":"Знак {s:2.2} требует обязательной остановки перед стоп-линией {m:1.12}, а если её нет — перед знаком, даже когда дорога свободна. После этого нужно пропустить тех, кто едет по пересекаемой дороге."},"ref":["33.2"],"id":"q26639c1e0"},{"t":"s33","q":{"uk":"На якій відстані до небезпечної ділянки встановлюють попереджувальні знаки поза населеним пунктом?","ru":"На каком расстоянии до опасного участка устанавливают предупреждающие знаки вне населённого пункта?"},"a":[{"uk":"50–100 м","ru":"50–100 м"},{"uk":"150–300 м","ru":"150–300 м"},{"uk":"300–500 м","ru":"300–500 м"}],"c":1,"e":{"uk":"Попереджувальні знаки ставлять поза населеними пунктами за 150–300 м, у населених пунктах — за 50–100 м до небезпечної ділянки. Інша відстань позначається табличкою {s:7.1.1}.","ru":"Предупреждающие знаки ставят вне населённых пунктов за 150–300 м, в населённых пунктах — за 50–100 м до опасного участка. Иное расстояние обозначается табличкой {s:7.1.1}."},"ref":["33.1"],"id":"qa0486a5e2"},{"t":"s33","q":{"uk":"Що означає знак 5.49 «Початок населеного пункту» на білому фоні?","ru":"Что означает знак 5.49 «Начало населённого пункта» на белом фоне?"},"a":[{"uk":"З цього місця діють правила руху в населених пунктах (зокрема обмеження 50 км/год)","ru":"С этого места действуют правила движения в населённых пунктах (в частности ограничение 50 км/ч)"},{"uk":"Лише інформує про назву, правила не змінюються","ru":"Только информирует о названии, правила не меняются"}],"img":{"sign":"5.49"},"c":0,"e":{"uk":"Знак {s:5.49} (білий) вмикає правила для населених пунктів: швидкість до 50 км/год, звуковий сигнал заборонено тощо. Знак {s:5.51} (синій) лише інформує про назву: правила для населених пунктів на цій дорозі не діють.","ru":"Знак {s:5.49} (белый) включает правила для населённых пунктов: скорость до 50 км/ч, звуковой сигнал запрещён и т. п. Знак {s:5.51} (синий) только информирует о названии: правила для населённых пунктов на этой дороге не действуют."},"ref":["33.5","12.4"],"id":"q303588ea2"},{"t":"s33","q":{"uk":"Що дозволяє і що забороняє знак 5.29 «Місце для розвороту»?","ru":"Что разрешает и что запрещает знак 5.29 «Место для разворота»?"},"a":[{"uk":"Дозволяє розворот; поворот ліворуч заборонено","ru":"Разрешает разворот; поворот налево запрещён"},{"uk":"Дозволяє розворот і поворот ліворуч","ru":"Разрешает разворот и поворот налево"},{"uk":"Дозволяє лише стоянку","ru":"Разрешает только стоянку"}],"img":{"sign":"5.29"},"c":0,"e":{"uk":"Знаки {s:5.29} і {s:5.30} позначають місце (зону) для розвороту. Поворот ліворуч у цьому місці заборонено.","ru":"Знаки {s:5.29} и {s:5.30} обозначают место (зону) для разворота. Поворот налево в этом месте запрещён."},"ref":["33.5"],"id":"q420301f17"},{"t":"s33","q":{"uk":"Встановлено знаки 3.36 і 3.37 одночасно. Коли треба переставити автомобіль на інший бік вулиці?","ru":"Установлены знаки 3.36 и 3.37 одновременно. Когда нужно переставить автомобиль на другую сторону улицы?"},"a":[{"uk":"З 7 до 9 год ранку","ru":"С 7 до 9 часов утра"},{"uk":"З 19 до 24 год","ru":"С 19 до 24 часов"},{"uk":"Опівночі","ru":"В полночь"}],"img":{"signs":["3.36","3.37"]},"c":1,"e":{"uk":"За одночасного застосування знаків {s:3.36} і {s:3.37} час перестановки автомобілів з одного боку на інший — з 19 до 24 год.","ru":"При одновременном применении знаков {s:3.36} и {s:3.37} время перестановки автомобилей с одной стороны на другую — с 19 до 24 ч."},"ref":["33.3"],"id":"q8e3ad9c25"},{"t":"s33","q":{"uk":"Дію яких знаків скасовує знак 3.42 «Кінець усіх заборон і обмежень»?","ru":"Действие каких знаков отменяет знак 3.42 «Конец всех запрещений и ограничений»?"},"a":[{"uk":"Одночасно кількох заборонних знаків: обгону, швидкості, звукового сигналу, зупинки, стоянки тощо","ru":"Одновременно нескольких запрещающих знаков: обгона, скорости, звукового сигнала, остановки, стоянки и т. п."},{"uk":"Усіх знаків, включно з пріоритету","ru":"Всех знаков, включая приоритета"},{"uk":"Лише обмеження швидкості","ru":"Только ограничения скорости"}],"img":{"sign":"3.42"},"c":0,"e":{"uk":"{s:3.42} одночасно скасовує дію знаків {s:3.20}, {s:3.25}, {s:3.27}, {s:3.29}, {s:3.31}, {s:3.33}–{s:3.38}, {s:3.44}, {s:3.45}.","ru":"{s:3.42} одновременно отменяет действие знаков {s:3.20}, {s:3.25}, {s:3.27}, {s:3.29}, {s:3.31}, {s:3.33}–{s:3.38}, {s:3.44}, {s:3.45}."},"ref":["33.3"],"id":"q5fe25c49d"},{"t":"s33","q":{"uk":"Знак 3.35 «Стоянку заборонено» встановлено праворуч. Чи можна стояти на лівому боці цієї вулиці (у дозволених місцях)?","ru":"Знак 3.35 «Стоянка запрещена» установлен справа. Можно ли стоять на левой стороне этой улицы (в разрешённых местах)?"},"a":[{"uk":"Так, знак діє лише на тому боці, де встановлений","ru":"Да, знак действует только на той стороне, где установлен"},{"uk":"Ні, знак діє на обидва боки","ru":"Нет, знак действует на обе стороны"}],"img":{"sign":"3.35"},"c":0,"e":{"uk":"Знаки {s:3.9}, {s:3.10}, {s:3.34}, {s:3.35}, {s:3.36}, {s:3.37} діють лише на тому боці дороги, на якому встановлені.","ru":"Знаки {s:3.9}, {s:3.10}, {s:3.34}, {s:3.35}, {s:3.36}, {s:3.37} действуют только на той стороне дороги, на которой установлены."},"ref":["33.3"],"id":"q8ce00d659"},{"t":"s33","q":{"uk":"Що означає табличка 7.8 під знаком «Головна дорога»?","ru":"Что означает табличка 7.8 под знаком «Главная дорога»?"},"a":[{"uk":"Показує напрямок головної дороги на перехресті","ru":"Показывает направление главной дороги на перекрёстке"},{"uk":"Показує, куди можна повертати","ru":"Показывает, куда можно поворачивать"},{"uk":"Попереджає про круговий рух","ru":"Предупреждает о круговом движении"}],"img":{"signs":["2.3","7.8"]},"c":0,"e":{"uk":"Табличка {s:7.8} «Напрямок головної дороги» застосовується зі знаками {s:2.1}, {s:2.2}, {s:2.3} і показує, куди повертає головна дорога.","ru":"Табличка {s:7.8} «Направление главной дороги» применяется со знаками {s:2.1}, {s:2.2}, {s:2.3} и показывает, куда поворачивает главная дорога."},"ref":["33.7","16.14"],"id":"qde4dcadd3"},{"t":"s34","q":{"uk":"Чи можна перетинати лінію розмітки 1.1?","ru":"Можно ли пересекать линию разметки 1.1?"},"a":[{"uk":"Так, для обгону будь-якого транспортного засобу","ru":"Да, для обгона любого транспортного средства"},{"uk":"Ні, крім об'їзду нерухомої перешкоди та обгону поодиноких транспортних засобів, що їдуть повільніше 30 км/год","ru":"Нет, кроме объезда неподвижного препятствия и обгона одиночных транспортных средств, едущих медленнее 30 км/ч"},{"uk":"Так, якщо зустрічна смуга вільна","ru":"Да, если встречная полоса свободна"}],"img":{"mark":"1.1"},"c":1,"e":{"uk":"Лінії {m:1.1} і {m:1.3} перетинати заборонено. Як виняток, {m:1.1} можна перетнути, щоб безпечно об'їхати нерухому перешкоду або обігнати поодинокий транспортний засіб, що рухається зі швидкістю менше 30 км/год.","ru":"Линии {m:1.1} и {m:1.3} пересекать запрещено. Как исключение, {m:1.1} можно пересечь, чтобы безопасно объехать неподвижное препятствие или обогнать одиночное транспортное средство, движущееся со скоростью менее 30 км/ч."},"ref":["34.1"],"id":"q11053a2db"},{"t":"s34","q":{"uk":"З якого боку дозволено перетинати розмітку 1.11?","ru":"С какой стороны разрешено пересекать разметку 1.11?"},"a":[{"uk":"З боку переривчастої лінії; з боку суцільної — лише для завершення обгону чи об'їзду","ru":"Со стороны прерывистой линии; со стороны сплошной — только для завершения обгона или объезда"},{"uk":"З будь-якого боку","ru":"С любой стороны"},{"uk":"З боку суцільної лінії","ru":"Со стороны сплошной линии"}],"img":{"mark":"1.11"},"c":0,"e":{"uk":"Лінію {m:1.11} дозволено перетинати з боку переривчастої частини, а з боку суцільної — лише повертаючись на свою смугу після обгону чи об'їзду.","ru":"Линию {m:1.11} разрешено пересекать со стороны прерывистой части, а со стороны сплошной — только возвращаясь на свою полосу после обгона или объезда."},"ref":["34.1"],"id":"qa577df58b"},{"t":"s34","q":{"uk":"Що забороняє жовта суцільна лінія біля краю проїзної частини (розмітка 1.4)?","ru":"Что запрещает жёлтая сплошная линия у края проезжей части (разметка 1.4)?"},"a":[{"uk":"Лише стоянку","ru":"Только стоянку"},{"uk":"Зупинку (і стоянку) з того боку, де вона нанесена","ru":"Остановку (и стоянку) с той стороны, где она нанесена"},{"uk":"Рух вантажівок","ru":"Движение грузовиков"}],"img":{"mark":"1.4"},"c":1,"e":{"uk":"Розмітка {m:1.4} (жовта суцільна) забороняє зупинку, а {m:1.10.1} (жовта переривчаста) — стоянку з того боку, де вона нанесена.","ru":"Разметка {m:1.4} (жёлтая сплошная) запрещает остановку, а {m:1.10.1} (жёлтая прерывистая) — стоянку с той стороны, где она нанесена."},"ref":["34.1"],"id":"q7d62051ef"},{"t":"s34","q":{"uk":"Чи можна перетинати лінію 1.5?","ru":"Можно ли пересекать линию 1.5?"},"a":[{"uk":"Так, з будь-якого боку","ru":"Да, с любой стороны"},{"uk":"Ні","ru":"Нет"},{"uk":"Лише для повороту ліворуч","ru":"Только для поворота налево"}],"img":{"mark":"1.5"},"c":0,"e":{"uk":"Лінії {m:1.5}, {m:1.6}, {m:1.7}, {m:1.8} дозволено перетинати з будь-якого боку. Лінія {m:1.6} попереджає про наближення до суцільної — готуйтеся завершити маневр.","ru":"Линии {m:1.5}, {m:1.6}, {m:1.7}, {m:1.8} разрешено пересекать с любой стороны. Линия {m:1.6} предупреждает о приближении к сплошной — готовьтесь завершить манёвр."},"ref":["34.1"],"id":"q02b005c72"},{"t":"s34","q":{"uk":"Коли можна перетнути широку суцільну лінію 1.2, що позначає край проїзної частини?","ru":"Когда можно пересечь широкую сплошную линию 1.2, обозначающую край проезжей части?"},"a":[{"uk":"Для вимушеної зупинки на узбіччі, а також в інших випадках, якщо це не заборонено знаками","ru":"Для вынужденной остановки на обочине, а также в других случаях, если это не запрещено знаками"},{"uk":"Ніколи","ru":"Никогда"},{"uk":"Лише для обгону","ru":"Только для обгона"}],"img":{"mark":"1.2"},"c":0,"e":{"uk":"Лінію {m:1.2}, якою позначено край проїзної частини, перетинати дозволено, якщо це не заборонено знаками, зокрема для вимушеної зупинки на узбіччі.","ru":"Линию {m:1.2}, которой обозначен край проезжей части, пересекать разрешено, если это не запрещено знаками, в частности для вынужденной остановки на обочине."},"ref":["34.1"],"id":"q505a0bc27"},{"t":"s34","q":{"uk":"Що означає жовта сітка на перехресті (розмітка 1.10.3)?","ru":"Что означает жёлтая сетка на перекрёстке (разметка 1.10.3)?"},"a":[{"uk":"Стоянку таксі","ru":"Стоянку такси"},{"uk":"Заборону в'їжджати на перехрестя, якщо утворився затор","ru":"Запрет въезжать на перекрёсток, если образовался затор"},{"uk":"Зупинку маршрутного транспорту","ru":"Остановку маршрутного транспорта"}],"img":{"mark":"1.10.3"},"c":1,"e":{"uk":"Коробчаста жовта розмітка {m:1.10.3} попереджає: не в'їжджайте на перехрестя, якщо через затор доведеться на ньому зупинитися.","ru":"Коробчатая жёлтая разметка {m:1.10.3} предупреждает: не въезжайте на перекрёсток, если из-за затора придётся на нём остановиться."},"ref":["34.1","16.4"],"id":"q355d8b7a5"},{"t":"safe","q":{"uk":"Як зміниться гальмівний шлях, якщо швидкість збільшити вдвічі?","ru":"Как изменится тормозной путь, если скорость увеличить вдвое?"},"a":[{"uk":"Збільшиться вдвічі","ru":"Увеличится вдвое"},{"uk":"Збільшиться приблизно вчетверо","ru":"Увеличится примерно вчетверо"},{"uk":"Не зміниться","ru":"Не изменится"}],"c":1,"e":{"uk":"Гальмівний шлях пропорційний квадрату швидкості: удвічі вища швидкість — приблизно вчетверо довший гальмівний шлях.","ru":"Тормозной путь пропорционален квадрату скорости: вдвое большая скорость — примерно вчетверо длиннее тормозной путь."},"id":"qc4942c42f"},{"t":"safe","q":{"uk":"Як діяти, якщо задні колеса автомобіля занесло вправо?","ru":"Как действовать, если задние колёса автомобиля занесло вправо?"},"a":[{"uk":"Плавно повернути кермо вправо (у бік заносу), не гальмуючи різко","ru":"Плавно повернуть руль вправо (в сторону заноса), не тормозя резко"},{"uk":"Різко повернути кермо вліво","ru":"Резко повернуть руль влево"},{"uk":"Різко натиснути на гальмо","ru":"Резко нажать на тормоз"}],"c":0,"e":{"uk":"Під час заносу кермо повертають у бік заносу задньої осі, плавно зменшують подачу палива і не гальмують різко — так шини відновлюють зчеплення.","ru":"При заносе руль поворачивают в сторону заноса задней оси, плавно уменьшают подачу топлива и не тормозят резко — так шины восстанавливают сцепление."},"id":"qd573dcd1e"},{"t":"safe","q":{"uk":"Як знизити ризик аквапланування на мокрій дорозі?","ru":"Как снизить риск аквапланирования на мокрой дороге?"},"a":[{"uk":"Підвищити тиск у шинах понад норму","ru":"Повысить давление в шинах сверх нормы"},{"uk":"Знизити швидкість і не їхати на зношених шинах","ru":"Снизить скорость и не ездить на изношенных шинах"},{"uk":"Їхати з увімкненою аварійною сигналізацією","ru":"Ехать с включённой аварийной сигнализацией"}],"c":1,"e":{"uk":"Аквапланування виникає, коли шина не встигає витіснити воду. Ризик зростає зі швидкістю та зношенням протектора. Якщо автомобіль «поплив», плавно скиньте газ і тримайте кермо прямо, без різкого гальмування.","ru":"Аквапланирование возникает, когда шина не успевает вытеснить воду. Риск растёт со скоростью и износом протектора. Если автомобиль «поплыл», плавно сбросьте газ и держите руль прямо, без резкого торможения."},"id":"qf60ebf42a"},{"t":"safe","q":{"uk":"Як правильно екстрено гальмувати на автомобілі з ABS?","ru":"Как правильно экстренно тормозить на автомобиле с ABS?"},"a":[{"uk":"Сильно натиснути педаль гальма і тримати її, керуючи кермом за потреби","ru":"Сильно нажать педаль тормоза и держать её, при необходимости управляя рулём"},{"uk":"Переривчасто натискати педаль","ru":"Прерывисто нажимать педаль"},{"uk":"Гальмувати лише стоянковим гальмом","ru":"Тормозить только стояночным тормозом"}],"c":0,"e":{"uk":"ABS сама запобігає блокуванню коліс. Водієві треба сильно натиснути педаль і не відпускати; автомобіль при цьому залишається керованим. Вібрація педалі — нормальна робота системи.","ru":"ABS сама предотвращает блокировку колёс. Водителю нужно сильно нажать педаль и не отпускать; автомобиль при этом остаётся управляемым. Вибрация педали — нормальная работа системы."},"id":"qa96d6359b"},{"t":"safe","q":{"uk":"Водій відчуває сильну втому за кермом. Що робити?","ru":"Водитель чувствует сильную усталость за рулём. Что делать?"},"a":[{"uk":"Відкрити вікно і їхати далі","ru":"Открыть окно и ехать дальше"},{"uk":"Збільшити гучність музики","ru":"Увеличить громкость музыки"},{"uk":"Зупинитися в безпечному місці й відпочити","ru":"Остановиться в безопасном месте и отдохнуть"}],"c":2,"e":{"uk":"Керувати в стані стомлення заборонено. Кава і відчинене вікно діють недовго — єдиний надійний спосіб відновитися — зупинитися й відпочити (за потреби поспати).","ru":"Управлять в состоянии утомления запрещено. Кофе и открытое окно действуют недолго — единственный надёжный способ восстановиться — остановиться и отдохнуть (при необходимости поспать)."},"ref":["2.9"],"id":"q4505cf03a"},{"t":"safe","q":{"uk":"Як зміниться безпечна дистанція на мокрій або слизькій дорозі?","ru":"Как изменится безопасная дистанция на мокрой или скользкой дороге?"},"a":[{"uk":"Її треба збільшити","ru":"Её нужно увеличить"},{"uk":"Вона не залежить від покриття","ru":"Она не зависит от покрытия"},{"uk":"Її можна зменшити, бо всі їдуть повільніше","ru":"Её можно уменьшить, так как все едут медленнее"}],"c":0,"e":{"uk":"На мокрій і слизькій дорозі зчеплення гірше, тож гальмівний шлях довшає. Безпечна дистанція має бути більшою. Зручний орієнтир на сухій дорозі — щонайменше 2 секунди до автомобіля попереду, на мокрій — удвічі більше.","ru":"На мокрой и скользкой дороге сцепление хуже, поэтому тормозной путь удлиняется. Безопасная дистанция должна быть больше. Удобный ориентир на сухой дороге — не менее 2 секунд до автомобиля впереди, на мокрой — вдвое больше."},"ref":["13.1"],"id":"q972bfc00f"},{"t":"safe","q":{"uk":"Як найкраще контролювати швидкість на тривалому слизькому спуску?","ru":"Как лучше всего контролировать скорость на долгом скользком спуске?"},"a":[{"uk":"Гальмувати двигуном на знижувальній передачі","ru":"Тормозить двигателем на пониженной передаче"},{"uk":"Їхати накатом на нейтральній передачі","ru":"Ехать накатом на нейтральной передаче"},{"uk":"Постійно тримати натиснутою педаль гальма","ru":"Постоянно держать нажатой педаль тормоза"}],"c":0,"e":{"uk":"На спуску безпечніше гальмувати двигуном на нижчій передачі: колеса не блокуються, гальма не перегріваються. Рух накатом з вимкненою передачею на гірських дорогах заборонено.","ru":"На спуске безопаснее тормозить двигателем на пониженной передаче: колёса не блокируются, тормоза не перегреваются. Движение накатом с выключенной передачей на горных дорогах запрещено."},"ref":["28.3"],"id":"q0b178c928"},{"t":"safe","q":{"uk":"Що треба зробити перед перестроюванням, крім огляду в дзеркала?","ru":"Что нужно сделать перед перестроением, кроме взгляда в зеркала?"},"a":[{"uk":"Коротко глянути через плече, щоб перевірити «сліпу зону»","ru":"Коротко взглянуть через плечо, чтобы проверить «слепую зону»"},{"uk":"Нічого, дзеркал достатньо","ru":"Ничего, зеркал достаточно"},{"uk":"Подати звуковий сигнал","ru":"Подать звуковой сигнал"}],"c":0,"e":{"uk":"Дзеркала не показують усього простору поруч — у «сліпій зоні» може бути автомобіль чи мотоцикл. Перед маневром перевірте її поворотом голови і переконайтеся, що маневр безпечний.","ru":"Зеркала не показывают всё пространство рядом — в «слепой зоне» может быть автомобиль или мотоцикл. Перед манёвром проверьте её поворотом головы и убедитесь, что манёвр безопасен."},"ref":["10.1"],"id":"q083074640"},{"t":"med","q":{"uk":"Ви першим під'їхали до місця ДТП з постраждалими. Що зробити насамперед?","ru":"Вы первым подъехали к месту ДТП с пострадавшими. Что сделать в первую очередь?"},"a":[{"uk":"Переконатися у власній безпеці (аварійка, знак, жилет) і викликати допомогу (103 або 112)","ru":"Убедиться в собственной безопасности (аварийка, знак, жилет) и вызвать помощь (103 или 112)"},{"uk":"Одразу витягнути всіх постраждалих з автомобілів","ru":"Сразу вытащить всех пострадавших из автомобилей"},{"uk":"Дати постраждалим попити води","ru":"Дать пострадавшим попить воды"}],"c":0,"e":{"uk":"Спочатку оцініть безпеку для себе: зупиніться, увімкніть аварійку, виставте знак аварійної зупинки. Потім викличте екстрену допомогу (103 — швидка, 112 — єдиний номер) і надавайте домедичну допомогу.","ru":"Сначала оцените безопасность для себя: остановитесь, включите аварийку, выставьте знак аварийной остановки. Затем вызовите экстренную помощь (103 — скорая, 112 — единый номер) и оказывайте домедицинскую помощь."},"ref":["2.10","9.10"],"id":"qce737e4d4"},{"t":"med","q":{"uk":"Масивна кровотеча з рани на нозі (кров б'є струменем). Що робити?","ru":"Массивное кровотечение из раны на ноге (кровь бьёт струёй). Что делать?"},"a":[{"uk":"Промити рану водою","ru":"Промыть рану водой"},{"uk":"Накласти турнікет (джгут) вище рани, затягнути до зупинки кровотечі й записати час накладання","ru":"Наложить турникет (жгут) выше раны, затянуть до остановки кровотечения и записать время наложения"},{"uk":"Підняти ногу й чекати швидку","ru":"Поднять ногу и ждать скорую"}],"c":1,"e":{"uk":"Масивну кровотечу з кінцівки зупиняють турнікетом (джгутом) вище рани, затягнувши до зупинки кровотечі. Обов'язково фіксують час накладання. Якщо турнікета немає — сильно тиснуть на рану або тампонують її.","ru":"Массивное кровотечение из конечности останавливают турникетом (жгутом) выше раны, затянув до остановки кровотечения. Обязательно фиксируют время наложения. Если турникета нет — сильно давят на рану или тампонируют её."},"id":"q64978baa4"},{"t":"med","q":{"uk":"Постраждалий без свідомості, але дихає нормально. У якому положенні його залишити до прибуття швидкої?","ru":"Пострадавший без сознания, но дышит нормально. В каком положении его оставить до прибытия скорой?"},"a":[{"uk":"Сидячи","ru":"Сидя"},{"uk":"У стабільному положенні на боці, постійно контролюючи дихання","ru":"В устойчивом положении на боку, постоянно контролируя дыхание"},{"uk":"На спині з піднятою головою","ru":"На спине с поднятой головой"}],"c":1,"e":{"uk":"Стабільне положення на боці не дає язику запасти, а блювотним масам — потрапити в дихальні шляхи. Дихання перевіряють постійно. Якщо є підозра на травму хребта і людина дихає — без потреби її не перекладають.","ru":"Устойчивое положение на боку не даёт языку западать, а рвотным массам — попасть в дыхательные пути. Дыхание проверяют постоянно. Если есть подозрение на травму позвоночника и человек дышит — без необходимости его не перекладывают."},"id":"q5f2536621"},{"t":"med","q":{"uk":"Постраждалий не дихає. Яке співвідношення натискань на грудну клітку і вдихів під час серцево-легеневої реанімації дорослого?","ru":"Пострадавший не дышит. Какое соотношение нажатий на грудную клетку и вдохов при сердечно-лёгочной реанимации взрослого?"},"a":[{"uk":"15 : 2","ru":"15 : 2"},{"uk":"30 : 2","ru":"30 : 2"},{"uk":"5 : 1","ru":"5 : 1"}],"c":1,"e":{"uk":"Дорослим роблять 30 натискань на центр грудної клітки (глибина 5–6 см, темп 100–120 за хвилину) і 2 вдихи. Якщо вдихи робити не вмієте — лише безперервні натискання до прибуття медиків.","ru":"Взрослым делают 30 нажатий на центр грудной клетки (глубина 5–6 см, темп 100–120 в минуту) и 2 вдоха. Если делать вдохи не умеете — только непрерывные нажатия до прибытия медиков."},"id":"q0d6dbf2e5"},{"t":"med","q":{"uk":"Чи можна переносити постраждалого з підозрою на травму хребта?","ru":"Можно ли переносить пострадавшего с подозрением на травму позвоночника?"},"a":[{"uk":"Лише якщо йому загрожує безпосередня небезпека (пожежа, вибух)","ru":"Только если ему угрожает непосредственная опасность (пожар, взрыв)"},{"uk":"Так, щоб посадити його зручніше","ru":"Да, чтобы усадить его удобнее"},{"uk":"Так, щоб відвезти до лікарні на своєму автомобілі","ru":"Да, чтобы отвезти в больницу на своём автомобиле"}],"c":0,"e":{"uk":"Зайві рухи можуть пошкодити спинний мозок. Постраждалого з підозрою на травму хребта переміщують лише за загрози життю (вогонь, вибух), намагаючись фіксувати голову і шию.","ru":"Лишние движения могут повредить спинной мозг. Пострадавшего с подозрением на травму позвоночника перемещают только при угрозе жизни (огонь, взрыв), стараясь фиксировать голову и шею."},"id":"q582b3ed7e"},{"t":"med","q":{"uk":"Як надати допомогу при термічному опіку руки?","ru":"Как оказать помощь при термическом ожоге руки?"},"a":[{"uk":"Змастити олією або жиром","ru":"Смазать маслом или жиром"},{"uk":"Проколоти пухирі","ru":"Проколоть волдыри"},{"uk":"Охолоджувати проточною прохолодною водою 10–20 хвилин і накрити чистою пов'язкою","ru":"Охлаждать проточной прохладной водой 10–20 минут и накрыть чистой повязкой"}],"c":2,"e":{"uk":"Опік охолоджують прохолодною проточною водою щонайменше 10–20 хвилин, потім накривають чистою сухою пов'язкою. Олію, жир чи лід не використовують, пухирі не проколюють.","ru":"Ожог охлаждают прохладной проточной водой не менее 10–20 минут, затем накрывают чистой сухой повязкой. Масло, жир или лёд не используют, волдыри не прокалывают."},"id":"q11cccf55e"},{"t":"med","q":{"uk":"Що робити при підозрі на перелом кінцівки?","ru":"Что делать при подозрении на перелом конечности?"},"a":[{"uk":"Знерухомити кінцівку в тому положенні, в якому вона є, і викликати швидку","ru":"Обездвижить конечность в том положении, в котором она находится, и вызвать скорую"},{"uk":"Спробувати вправити кістку","ru":"Попытаться вправить кость"},{"uk":"Попросити постраждалого поворушити кінцівкою","ru":"Попросить пострадавшего пошевелить конечностью"}],"c":0,"e":{"uk":"Кінцівку з підозрою на перелом не вправляють, а знерухомлюють (шиною чи підручними засобами), захоплюючи сусідні суглоби. Якщо є кровотеча — спочатку її зупиняють.","ru":"Конечность с подозрением на перелом не вправляют, а обездвиживают (шиной или подручными средствами), захватывая соседние суставы. Если есть кровотечение — сначала его останавливают."},"id":"q1520475ca"},{"t":"med","q":{"uk":"Мотоцикліст лежить без свідомості в шоломі, але дихає. Чи знімати шолом?","ru":"Мотоциклист лежит без сознания в шлеме, но дышит. Снимать ли шлем?"},"a":[{"uk":"Так, обов'язково і негайно","ru":"Да, обязательно и немедленно"},{"uk":"Ні, якщо він дихає; шолом знімають лише якщо треба відновити дихання або прохідність дихальних шляхів","ru":"Нет, если он дышит; шлем снимают только если нужно восстановить дыхание или проходимость дыхательных путей"}],"c":1,"e":{"uk":"Знімання шолома може травмувати шийний відділ хребта. Якщо людина дихає — шолом не чіпають до приїзду медиків. Знімають обережно, удвох, лише коли треба відновити дихання або провести реанімацію.","ru":"Снятие шлема может травмировать шейный отдел позвоночника. Если человек дышит — шлем не трогают до приезда медиков. Снимают осторожно, вдвоём, только когда нужно восстановить дыхание или провести реанимацию."},"id":"q9796012cb"}]};
